/* The light's position, its arc length (percent of the ring) and how much of the
   ring is filled are all registered so they can be transitioned and animated. */
@property --bkc-orbit-a { syntax: "<angle>"; inherits: true; initial-value: 225deg; }
@property --bkc-orbit-arc { syntax: "<number>"; inherits: true; initial-value: 22; }
@property --bkc-orbit-fill { syntax: "<percentage>"; inherits: true; initial-value: 0%; }
@property --bkc-orbit-comet { syntax: "<color>"; inherits: true; initial-value: oklch(90% 0.07 85); }

.bkc-orbit {
  /* re-theme: override these four */
  --bkc-orbit-bg: oklch(16.5% 0.02 48);
  --bkc-orbit-ink: oklch(94% 0.022 86);
  --bkc-orbit-gold: oklch(80% 0.105 82);
  --bkc-orbit-wine: oklch(58% 0.17 22);

  --bkc-orbit-card: color-mix(in oklch, var(--bkc-orbit-bg) 93%, var(--bkc-orbit-gold));
  --bkc-orbit-muted: color-mix(in oklch, var(--bkc-orbit-ink) 66%, var(--bkc-orbit-bg));
  --bkc-orbit-faint: color-mix(in oklch, var(--bkc-orbit-ink) 42%, var(--bkc-orbit-bg));
  --bkc-orbit-line: color-mix(in oklch, var(--bkc-orbit-ink) 11%, transparent);
  --bkc-orbit-gold-hi: color-mix(in oklch, var(--bkc-orbit-gold) 55%, white);
  --bkc-orbit-comet: var(--bkc-orbit-gold-hi);
  --bkc-orbit-serif: ui-serif, "New York", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --bkc-orbit-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.3%, 1.077 24.4%, 1.071 26.8%, 1.017 34.8%, .997 39.6%, .993 44.7%, 1.001 60.8%, 1);
  --bkc-orbit-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  color: var(--bkc-orbit-ink);
  background:
    radial-gradient(60% 70% at 50% 0%, color-mix(in oklch, var(--bkc-orbit-gold) 9%, transparent), transparent 70%),
    var(--bkc-orbit-bg);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  transition: --bkc-orbit-arc .9s var(--bkc-orbit-spring), --bkc-orbit-fill 1.3s var(--bkc-orbit-out), --bkc-orbit-comet .45s ease-out;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, dl, dd, fieldset) { margin: 0; padding: 0; border: 0; }
  & :where(button, input) { font: inherit; color: inherit; }

  /* attention widens the light; a sign-up fills the ring */
  &:has(.bkc-orbit-input:focus) { --bkc-orbit-arc: 30; }
  &:has(.bkc-orbit-go:hover, .bkc-orbit-go:focus-visible) { --bkc-orbit-arc: 38; }
  &.is-error { --bkc-orbit-comet: var(--bkc-orbit-wine); --bkc-orbit-arc: 30; }
  &.is-done { --bkc-orbit-arc: 64; --bkc-orbit-fill: 100%; }
}
.bkc-orbit-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkc-orbit-in { max-width: 1120px; margin-inline: auto; padding: clamp(40px, 8cqi, 104px) clamp(16px, 4.5cqi, 56px); }

/* ---------- frame, light ring and halo ---------- */
.bkc-orbit-frame { position: relative; --bkc-orbit-r: clamp(20px, 2.6cqi, 30px); }
.bkc-orbit-ring, .bkc-orbit-halo {
  position: absolute; inset: 0; border-radius: var(--bkc-orbit-r); pointer-events: none;
  background:
    conic-gradient(from calc(var(--bkc-orbit-a) - var(--bkc-orbit-arc) * 1.8deg),
      transparent 0%,
      color-mix(in oklch, var(--bkc-orbit-comet) 35%, transparent) calc(var(--bkc-orbit-arc) * .22%),
      var(--bkc-orbit-comet) calc(var(--bkc-orbit-arc) * .5%),
      color-mix(in oklch, var(--bkc-orbit-comet) 35%, transparent) calc(var(--bkc-orbit-arc) * .78%),
      transparent calc(var(--bkc-orbit-arc) * 1%)),
    linear-gradient(color-mix(in oklch, var(--bkc-orbit-gold) var(--bkc-orbit-fill), var(--bkc-orbit-line)) 0 0);
}
.bkc-orbit-ring {
  padding: 1.5px;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
}
.bkc-orbit-halo {
  inset: -2px; filter: blur(26px); opacity: .45;
  transition: opacity 1.2s var(--bkc-orbit-out);
  .bkc-orbit.is-done & { opacity: .8; }
  background:
    conic-gradient(from calc(var(--bkc-orbit-a) - var(--bkc-orbit-arc) * 1.8deg),
      transparent 0%, var(--bkc-orbit-comet) calc(var(--bkc-orbit-arc) * .5%), transparent calc(var(--bkc-orbit-arc) * 1%)),
    linear-gradient(color-mix(in oklch, var(--bkc-orbit-gold) calc(var(--bkc-orbit-fill) * .45), transparent) 0 0);
}

/* ---------- card ---------- */
.bkc-orbit-card {
  position: relative; isolation: isolate;
  display: grid; gap: clamp(28px, 4cqi, 44px);
  grid-template-areas: "copy" "act";
  padding: clamp(26px, 5.5cqi, 64px);
  border-radius: var(--bkc-orbit-r);
  background:
    repeating-radial-gradient(circle at 100% 0%, transparent 0 11px, color-mix(in oklch, var(--bkc-orbit-gold) 7%, transparent) 11px 12px),
    var(--bkc-orbit-card);
  background-blend-mode: normal;
  overflow: clip;
  &::before { /* fade the engine-turned lines toward the copy */
    content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
    background: radial-gradient(120% 90% at 0% 100%, var(--bkc-orbit-card) 45%, transparent 85%);
  }
}
@container (width >= 820px) {
  .bkc-orbit-card { grid-template-columns: minmax(0, 1fr) minmax(360px, 1fr); grid-template-areas: "copy act"; column-gap: clamp(36px, 6cqi, 80px); align-items: center; }
}

.bkc-orbit-copy { grid-area: copy; display: grid; gap: clamp(14px, 2cqi, 22px); align-content: start; }
.bkc-orbit-brand {
  display: flex; align-items: center; gap: 10px;
  font-size: 12px; font-weight: 600; letter-spacing: .26em; text-transform: uppercase; color: var(--bkc-orbit-gold);
  & svg { width: 28px; height: 28px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
}
.bkc-orbit-title {
  font-family: var(--bkc-orbit-serif); font-weight: 400;
  font-size: clamp(34px, 6.4cqi, 66px); line-height: 1.02; letter-spacing: -.022em;
  text-wrap: balance;
  & em { font-style: italic; color: var(--bkc-orbit-gold-hi); }
}
.bkc-orbit-lede { max-width: 46ch; font-size: clamp(15px, 1.5cqi, 17px); color: var(--bkc-orbit-muted); text-wrap: pretty; }

/* ---------- action column ---------- */
.bkc-orbit-act { grid-area: act; display: grid; gap: 26px; align-content: start; }
.bkc-orbit-form { display: grid; gap: 10px; &[hidden] { display: none; } }

.bkc-orbit-mode {
  position: relative; display: grid; grid-template-columns: 1fr 1fr; justify-self: start;
  width: min(100%, 300px); margin-bottom: 8px; padding: 3px;
  border-radius: 999px; box-shadow: inset 0 0 0 1px var(--bkc-orbit-line);
  &::before {
    content: ""; position: absolute; inset: 3px auto 3px 3px; width: calc(50% - 3px);
    border-radius: inherit; background: color-mix(in oklch, var(--bkc-orbit-gold) 16%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkc-orbit-gold) 40%, transparent);
    transition: translate .5s var(--bkc-orbit-spring);
  }
  &:has([value="walk"]:checked)::before { translate: 100% 0; }
  & label { position: relative; display: grid; place-items: center; min-height: 36px; cursor: pointer; }
  & input { position: absolute; opacity: 0; pointer-events: none; }
  & span { font-size: 13px; font-weight: 500; letter-spacing: .01em; color: var(--bkc-orbit-faint); transition: color .25s; }
  & input:checked + span { color: var(--bkc-orbit-ink); }
  & label:hover span { color: var(--bkc-orbit-ink); }
  & label:has(input:focus-visible) { outline: 2px solid var(--bkc-orbit-gold); outline-offset: 1px; border-radius: 999px; }
}

.bkc-orbit-label { font-size: 12px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--bkc-orbit-faint); }
.bkc-orbit-field { display: grid; gap: 10px; }
@container (width >= 520px) {
  .bkc-orbit-field { grid-template-columns: minmax(0, 1fr) auto; gap: 0; padding: 5px; border-radius: 16px; background: color-mix(in oklch, var(--bkc-orbit-bg) 70%, black); box-shadow: inset 0 0 0 1px var(--bkc-orbit-line); transition: box-shadow .25s;
    &:has(.bkc-orbit-input:focus) { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkc-orbit-gold) 60%, transparent); }
    & .bkc-orbit-input { background: transparent; box-shadow: none; }
  }
}
.bkc-orbit-input {
  min-width: 0; height: 50px; padding: 0 16px; border: 0; border-radius: 12px;
  background: color-mix(in oklch, var(--bkc-orbit-bg) 70%, black);
  box-shadow: inset 0 0 0 1px var(--bkc-orbit-line);
  font-size: 16px; caret-color: var(--bkc-orbit-gold);
  &::placeholder { color: color-mix(in oklch, var(--bkc-orbit-ink) 30%, transparent); }
  &:focus { outline: none; }
  &:focus-visible { box-shadow: inset 0 0 0 1px var(--bkc-orbit-gold); }
  &[aria-invalid="true"] { box-shadow: inset 0 0 0 1px var(--bkc-orbit-wine); }
}
.bkc-orbit-go {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  height: 50px; padding: 0 20px; border: 0; border-radius: 12px; cursor: pointer;
  background: linear-gradient(180deg, var(--bkc-orbit-gold-hi), var(--bkc-orbit-gold));
  color: color-mix(in oklch, var(--bkc-orbit-bg) 85%, black);
  font-weight: 650; letter-spacing: .005em; white-space: nowrap;
  box-shadow: 0 1px 0 color-mix(in oklch, white 50%, transparent) inset, 0 10px 30px -12px color-mix(in oklch, var(--bkc-orbit-gold) 80%, transparent);
  transition: transform .5s var(--bkc-orbit-spring), box-shadow .3s;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: transform .5s var(--bkc-orbit-spring); }
  &:hover { transform: translateY(-1px); & svg { transform: translateX(3px); } }
  &:active { transform: translateY(0) scale(.98); transition-duration: .1s; }
  &:focus-visible { outline: 2px solid var(--bkc-orbit-gold-hi); outline-offset: 3px; }
}
.bkc-orbit-hint {
  min-height: 1.5em; font-size: 13px; color: var(--bkc-orbit-faint); text-wrap: pretty;
  .bkc-orbit.is-error & { color: color-mix(in oklch, var(--bkc-orbit-wine) 70%, var(--bkc-orbit-ink)); }
}

/* ---------- success ---------- */
.bkc-orbit-done {
  display: grid; justify-items: start; gap: 8px;
  transition: opacity .6s var(--bkc-orbit-out), translate .8s var(--bkc-orbit-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  &[hidden] { display: none; }
  & .bkc-orbit-again { margin-top: 6px; padding: 0; border: 0; background: none; cursor: pointer; font-size: 13px; color: var(--bkc-orbit-gold); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: color-mix(in oklch, var(--bkc-orbit-gold) 40%, transparent);
    &:hover { text-decoration-color: currentColor; }
    &:focus-visible { outline: 2px solid var(--bkc-orbit-gold); outline-offset: 3px; border-radius: 2px; }
  }
}
.bkc-orbit-seal {
  width: 44px; height: 44px; fill: none; stroke: var(--bkc-orbit-gold); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round;
  & circle { stroke-dasharray: 132; stroke-dashoffset: 132; animation: bkc-orbit-draw 1s var(--bkc-orbit-out) .1s forwards; }
  & path { stroke-dasharray: 30; stroke-dashoffset: 30; animation: bkc-orbit-draw .6s var(--bkc-orbit-out) .6s forwards; }
}
@keyframes bkc-orbit-draw { to { stroke-dashoffset: 0; } }
.bkc-orbit-done-t { font-family: var(--bkc-orbit-serif); font-size: clamp(24px, 3cqi, 30px); line-height: 1.15; letter-spacing: -.01em; text-wrap: balance; outline: none; }
.bkc-orbit-done-p { max-width: 42ch; color: var(--bkc-orbit-muted); text-wrap: pretty; overflow-wrap: anywhere; & b { color: var(--bkc-orbit-ink); font-weight: 600; } }

/* ---------- stats ---------- */
.bkc-orbit-stats {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  padding-top: 22px; border-top: 1px solid var(--bkc-orbit-line);
  & div { display: flex; flex-direction: column-reverse; justify-content: flex-end; gap: 4px; padding-inline: 0 10px; }
  & div + div { padding-left: clamp(10px, 2cqi, 18px); border-left: 1px solid var(--bkc-orbit-line); }
  & dt { font-size: 11px; line-height: 1.3; letter-spacing: .06em; text-transform: uppercase; color: var(--bkc-orbit-faint); text-wrap: balance; }
  & dd { font-family: var(--bkc-orbit-serif); font-size: clamp(24px, 3.2cqi, 32px); line-height: 1; letter-spacing: -.02em; font-variant-numeric: lining-nums tabular-nums; color: var(--bkc-orbit-ink); }
  & small { margin-left: 3px; font-family: system-ui, sans-serif; font-size: 13px; letter-spacing: 0; color: var(--bkc-orbit-faint); }
}

/* entrance */
.bkc-orbit-copy > *, .bkc-orbit-act > * {
  transition: opacity .8s var(--bkc-orbit-out), translate 1s var(--bkc-orbit-out);
  transition-delay: calc(var(--i, 0) * 70ms);
}
.bkc-orbit.is-pre :is(.bkc-orbit-copy, .bkc-orbit-act) > * { opacity: 0; translate: 0 14px; }
.bkc-orbit-copy > :nth-child(2) { --i: 1; } .bkc-orbit-copy > :nth-child(3) { --i: 2; }
.bkc-orbit-act > :nth-child(1) { --i: 3; } .bkc-orbit-act > :nth-child(3) { --i: 4; }

@media (prefers-reduced-motion: reduce) {
  .bkc-orbit {
    transition: --bkc-orbit-fill .4s linear, --bkc-orbit-comet .2s linear;
    --bkc-orbit-a: 315deg; --bkc-orbit-arc: 30;
    &:has(.bkc-orbit-input:focus), &:has(.bkc-orbit-go:hover, .bkc-orbit-go:focus-visible) { --bkc-orbit-arc: 30; }
  }
  .bkc-orbit-mode::before, .bkc-orbit-go, .bkc-orbit-go svg { transition: none; }
  .bkc-orbit-go:hover { transform: none; & svg { transform: none; } }
  .bkc-orbit-done { transition: opacity .3s linear; @starting-style { translate: 0 0; } }
  .bkc-orbit-seal :is(circle, path) { animation: none; stroke-dashoffset: 0; }
  .bkc-orbit.is-pre :is(.bkc-orbit-copy, .bkc-orbit-act) > * { opacity: 1; translate: 0 0; }
}

