/* The light on the border is one angle, a, on a damped spring.
   With nothing to look at it orbits; the pointer or the focused control gives it a
   target, and it swings there along the shortest way round. */
const frame = root.querySelector('.bkc-orbit-frame');
const form = root.querySelector('.bkc-orbit-form');
const input = root.querySelector('.bkc-orbit-input');
const goLabel = root.querySelector('[data-go]');
const hint = root.querySelector('[data-hint]');
const done = root.querySelector('.bkc-orbit-done');
const doneT = root.querySelector('[data-done-t]');
const doneP = root.querySelector('[data-done-p]');
const again = root.querySelector('.bkc-orbit-again');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

const COPY = {
  trial: { go: 'Open your cellar book', hint: '30 days free · no card · import your list from any spreadsheet',
    t: 'A cellar is set aside for you.', p: (e) => 'Your import link is on its way to <b>' + e + '</b>. Bring last month’s stock sheet — most lists are live before the next service.' },
  walk: { go: 'Request a walkthrough', hint: '25 minutes with Maëlle Arnaud, our head sommelier · weekdays 10:00–16:00 CET',
    t: 'Maëlle will be in touch.', p: (e) => 'She’ll write to <b>' + e + '</b> within one working day with three times that sit between lunch and dinner service.' },
};
/* a radio group is document-wide by name: give this instance its own */
const group = 'bkc-orbit-mode-' + Math.random().toString(36).slice(2, 8);
root.querySelectorAll('.bkc-orbit-mode input').forEach((r) => { r.name = group; });
const mode = () => (root.querySelector('.bkc-orbit-mode input:checked') || {}).value || 'trial';
root.addEventListener('change', (e) => {
  if (!e.target.closest('.bkc-orbit-mode')) return;
  const c = COPY[mode()];
  goLabel.textContent = c.go;
  if (!root.classList.contains('is-error')) hint.textContent = c.hint;
});

/* ---------------- the spring ---------------- */
let a = 225, v = 0, spin = 34, target = null, pointerT = null, focusT = null;
let raf = 0, last = 0, visible = false, rect = null;

const measure = () => { rect = frame.getBoundingClientRect(); };
/* conic-gradient angles start at 12 o'clock and run clockwise, in real pixels */
const angleAt = (x, y) => Math.atan2(x - (rect.left + rect.width / 2), (rect.top + rect.height / 2) - y) * 180 / Math.PI;
const angleOf = (el) => { const r = el.getBoundingClientRect(); return angleAt(r.left + r.width / 2, r.top + r.height / 2); };
const retarget = () => { target = pointerT != null ? pointerT : focusT; wake(); };
const paint = () => frame.style.setProperty('--bkc-orbit-a', a.toFixed(2) + 'deg');

function tick(now) {
  if (!root.isConnected) { teardown(); return; }
  raf = 0;
  if (!visible || document.hidden || reduce.matches) return;
  const dt = Math.min(0.05, (now - (last || now)) / 1000);
  last = now;
  if (target == null) {
    v += (spin - v) * Math.min(1, dt * 2.2);          /* ease back into the orbit */
    spin += (34 - spin) * Math.min(1, dt * 0.9);       /* a burst of speed decays */
  } else {
    const d = ((target - a) % 360 + 540) % 360 - 180;  /* shortest way round */
    v += (90 * d - 2 * Math.sqrt(90) * 0.82 * v) * dt;
  }
  a = (a + v * dt) % 360;
  paint();
  raf = requestAnimationFrame(tick);
}
function wake() { if (!raf && visible && !reduce.matches) { last = 0; raf = requestAnimationFrame(tick); } }

root.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  if (!rect) measure();
  pointerT = angleAt(e.clientX, e.clientY);
  retarget();
});
root.addEventListener('pointerenter', measure);
root.addEventListener('pointerleave', () => { pointerT = null; retarget(); });
root.addEventListener('focusin', (e) => {
  measure();
  focusT = angleOf(e.target);
  if (reduce.matches) return;
  retarget();
});
root.addEventListener('focusout', (e) => { if (!root.contains(e.relatedTarget)) { focusT = null; retarget(); } });

const io = new IntersectionObserver(([en]) => {
  visible = en.isIntersecting;
  if (visible) { measure(); root.classList.remove('is-pre'); wake(); }
}, { threshold: 0.15 });
io.observe(root);
const ro = new ResizeObserver(measure);
ro.observe(frame);
const onVis = () => {
  if (!root.isConnected) { teardown(); return; }
  if (!document.hidden) wake();
};
const onReduce = () => { if (reduce.matches) frame.style.removeProperty('--bkc-orbit-a'); else wake(); };
function teardown() { document.removeEventListener('visibilitychange', onVis); reduce.removeEventListener('change', onReduce); io.disconnect(); ro.disconnect(); }
document.addEventListener('visibilitychange', onVis);
reduce.addEventListener('change', onReduce);
if (!reduce.matches) root.classList.add('is-pre');

/* ---------------- form ---------------- */
const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
let errT = 0;
function fail(msg) {
  input.setAttribute('aria-invalid', 'true');
  hint.textContent = msg;
  root.classList.add('is-error');
  focusT = angleOf(input); retarget();
  clearTimeout(errT);
  errT = setTimeout(() => root.classList.remove('is-error'), 1400);
  if (!reduce.matches) input.animate(
    [{ transform: 'translateX(0)' }, { transform: 'translateX(-6px)' }, { transform: 'translateX(5px)' }, { transform: 'translateX(-3px)' }, { transform: 'translateX(0)' }],
    { duration: 380, easing: 'cubic-bezier(.36,.07,.19,.97)' });
  input.focus();
}
input.addEventListener('input', () => {
  if (input.getAttribute('aria-invalid') === 'true' && EMAIL.test(input.value.trim())) {
    input.removeAttribute('aria-invalid');
    root.classList.remove('is-error');
    hint.textContent = COPY[mode()].hint;
  }
});
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const val = input.value.trim();
  if (!val) return fail('Add the address you use for supplier orders.');
  if (!EMAIL.test(val)) return fail('That doesn’t look complete — try something like ana@lamerlerie.fr');
  const c = COPY[mode()];
  const safe = val.replace(/[&<>"']/g, (ch) => '&#' + ch.charCodeAt(0) + ';');
  doneT.textContent = c.t;
  doneP.innerHTML = c.p(safe);
  form.hidden = true;
  done.hidden = false;
  root.classList.remove('is-error');
  root.classList.add('is-done');
  focusT = null; pointerT = null; target = null;
  spin = 260; v = Math.max(v, 120);           /* the light races once round, then settles */
  wake();
  doneT.focus({ preventScroll: true });
});
again.addEventListener('click', () => {
  root.classList.remove('is-done');
  done.hidden = true;
  form.hidden = false;
  input.value = '';
  input.removeAttribute('aria-invalid');
  hint.textContent = COPY[mode()].hint;
  input.focus();
});

css:
.bkc-letter {
  /* re-theme: newsprint, ink, postal red, envelope */
  --bkc-letter-paper: oklch(95.4% 0.017 84);
  --bkc-letter-ink: oklch(23% 0.022 52);
  --bkc-letter-red: oklch(53% 0.19 29);
  --bkc-letter-kraft: oklch(83% 0.06 74);

  --bkc-letter-sheet: color-mix(in oklch, var(--bkc-letter-paper) 28%, white);
  --bkc-letter-muted: color-mix(in oklch, var(--bkc-letter-ink) 66%, var(--bkc-letter-paper));
  --bkc-letter-rule: color-mix(in oklch, var(--bkc-letter-ink) 16%, transparent);
  --bkc-letter-kraft-dk: color-mix(in oklch, var(--bkc-letter-kraft) 82%, var(--bkc-letter-ink));
  --bkc-letter-serif: ui-serif, "New York", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --bkc-letter-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkc-letter-out: cubic-bezier(.16, 1, .3, 1);
  --bkc-letter-spring: linear(0, .013, .05 2.3%, .2 5%, .766 13.4%, .963 17.5%, 1.04 21%, 1.065 24%, 1.064 26.9%, 1.015 35%, .995 41.6%, 1.001 60%, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  color: var(--bkc-letter-ink);
  background:
    radial-gradient(70% 60% at 100% 0%, color-mix(in oklch, var(--bkc-letter-kraft) 22%, transparent), transparent 70%),
    var(--bkc-letter-paper);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, figure, blockquote, fieldset) { margin: 0; padding: 0; border: 0; }
  & :where(ol) { list-style: none; }
  & :where(button, input) { font: inherit; color: inherit; }
}

.bkc-letter-in {
  max-width: 1160px; margin-inline: auto;
  padding: clamp(40px, 7cqi, 96px) clamp(16px, 4.5cqi, 56px);
  display: grid; gap: clamp(32px, 5cqi, 48px);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "mast" "desk" "past";
}
@container (width >= 880px) {
  .bkc-letter-in { grid-template-columns: minmax(0, 1fr) minmax(400px, 470px); grid-template-areas: "mast desk" "past desk"; column-gap: clamp(48px, 7cqi, 96px); align-items: start; }
}

/* ---------- masthead ---------- */
.bkc-letter-mast { grid-area: mast; display: grid; gap: clamp(14px, 2cqi, 20px); }
.bkc-letter-rule {
  display: flex; justify-content: space-between; gap: 12px; padding-block: 7px;
  border-block: 3px double var(--bkc-letter-ink);
  font-size: 10.5px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  & span:last-child { white-space: nowrap; }
}
@container (width >= 520px) { .bkc-letter-rule { font-size: 11px; letter-spacing: .16em; } }
.bkc-letter-title {
  font-family: var(--bkc-letter-serif); font-weight: 700;
  font-size: clamp(44px, 8.6cqi, 96px); line-height: .92; letter-spacing: -.035em;
  text-wrap: balance;
  & em { display: block; font-weight: 400; font-style: italic; color: var(--bkc-letter-red); letter-spacing: -.03em; }
}
@container (width >= 880px) { .bkc-letter-title { font-size: clamp(56px, 7.2cqi, 92px); } }
.bkc-letter-dek { max-width: 50ch; font-family: var(--bkc-letter-serif); font-size: clamp(17px, 1.9cqi, 20px); line-height: 1.45; text-wrap: pretty; }
.bkc-letter-facts {
  display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13px; color: var(--bkc-letter-muted);
  & b { color: var(--bkc-letter-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & span { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; }
  & span::before { content: ""; width: 5px; height: 5px; background: var(--bkc-letter-red); rotate: 45deg; }
}

/* ---------- back issues ---------- */
.bkc-letter-past { grid-area: past; display: grid; gap: 14px; align-content: start; }
.bkc-letter-h3 { font-size: 11px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--bkc-letter-muted); }
.bkc-letter-issues {
  border-top: 1px solid var(--bkc-letter-ink);
  & li { display: grid; grid-template-columns: 3.2em minmax(0, 1fr) auto; gap: 12px; align-items: baseline; padding: 12px 0; border-bottom: 1px solid var(--bkc-letter-rule); }
}
.bkc-letter-no { font-family: var(--bkc-letter-mono); font-size: 12px; color: var(--bkc-letter-red); font-variant-numeric: tabular-nums; &::before { content: "No."; margin-right: 2px; } }
.bkc-letter-hl { font-family: var(--bkc-letter-serif); font-size: clamp(16px, 1.8cqi, 19px); line-height: 1.3; text-wrap: pretty; }
.bkc-letter-min { font-size: 12px; color: var(--bkc-letter-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.bkc-letter-quote {
  display: grid; gap: 6px; margin-top: 10px; padding-left: 16px; border-left: 3px solid var(--bkc-letter-red);
  & blockquote { font-family: var(--bkc-letter-serif); font-style: italic; font-size: clamp(17px, 1.9cqi, 20px); line-height: 1.4; text-wrap: balance; }
  & figcaption { font-size: 12px; letter-spacing: .04em; color: var(--bkc-letter-muted); }
}

/* ---------- the desk: sheet, fold, envelope share one grid cell ---------- */
.bkc-letter-desk { grid-area: desk; position: relative; display: grid; isolation: isolate; }
.bkc-letter-desk > * { grid-area: 1 / 1; }

.bkc-letter-sheet {
  position: relative; display: grid; gap: 14px; align-content: start;
  padding: clamp(24px, 3.4cqi, 36px) clamp(20px, 3.4cqi, 36px) clamp(22px, 3cqi, 30px) clamp(34px, 5cqi, 52px);
  background:
    linear-gradient(90deg, transparent clamp(20px, 3cqi, 32px), color-mix(in oklch, var(--bkc-letter-red) 45%, transparent) 0 calc(clamp(20px, 3cqi, 32px) + 1px), transparent 0),
    var(--bkc-letter-sheet);
  border-radius: 3px;
  box-shadow: 0 1px 0 color-mix(in oklch, var(--bkc-letter-ink) 6%, transparent), 0 18px 40px -18px color-mix(in oklch, var(--bkc-letter-ink) 40%, transparent), 0 2px 6px -2px color-mix(in oklch, var(--bkc-letter-ink) 18%, transparent);
  transition: opacity .45s var(--bkc-letter-out), translate .7s var(--bkc-letter-spring), visibility 0s;
  .bkc-letter.is-posted & { opacity: 0; visibility: hidden; translate: 0 10px; transition: opacity .16s linear, translate 0s .16s, visibility 0s .16s; }
}
.bkc-letter-salute { font-family: var(--bkc-letter-serif); font-style: italic; font-size: clamp(20px, 2.4cqi, 24px); }
.bkc-letter-ask { font-family: var(--bkc-letter-serif); font-size: 17px; color: var(--bkc-letter-muted); }
.bkc-letter-input {
  width: 100%; height: 46px; padding: 0 2px; margin-top: -6px;
  border: 0; border-bottom: 1.5px solid var(--bkc-letter-ink); border-radius: 0; background: transparent;
  font-family: var(--bkc-letter-serif); font-size: clamp(19px, 2.3cqi, 22px); caret-color: var(--bkc-letter-red);
  transition: border-color .2s;
  &::placeholder { color: color-mix(in oklch, var(--bkc-letter-ink) 32%, transparent); font-style: italic; }
  &:focus { outline: none; border-bottom-color: var(--bkc-letter-red); box-shadow: 0 2px 0 -0.5px var(--bkc-letter-red); }
  &[aria-invalid="true"] { border-bottom-color: var(--bkc-letter-red); background: color-mix(in oklch, var(--bkc-letter-red) 6%, transparent); }
}
.bkc-letter-desks {
  display: flex; flex-wrap: wrap; gap: 8px;
  & legend { float: left; width: 100%; margin-bottom: 8px; font-family: var(--bkc-letter-serif); font-size: 17px; color: var(--bkc-letter-muted); }
  & label {
    display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px 0 10px; cursor: pointer;
    border: 1px solid var(--bkc-letter-rule); border-radius: 999px; background: var(--bkc-letter-sheet);
    font-size: 14px; font-weight: 550; user-select: none;
    transition: background-color .2s, border-color .2s, transform .45s var(--bkc-letter-spring);
    &:hover { border-color: color-mix(in oklch, var(--bkc-letter-ink) 45%, transparent); }
    &:active { transform: scale(.96); transition-duration: .08s; }
    &:has(input:checked) { border-color: var(--bkc-letter-ink); background: color-mix(in oklch, var(--bkc-letter-ink) 6%, var(--bkc-letter-sheet)); }
    &:has(input:focus-visible) { outline: 2px solid var(--bkc-letter-red); outline-offset: 2px; }
  }
  & input { width: 15px; height: 15px; margin: 0; accent-color: var(--bkc-letter-red); }
  & input:focus-visible { outline: none; }
  & small { font-size: 12px; font-weight: 450; color: var(--bkc-letter-muted); font-variant-numeric: tabular-nums; }
}
.bkc-letter-sum { font-size: 14px; color: var(--bkc-letter-muted); & b { color: var(--bkc-letter-ink); font-variant-numeric: tabular-nums; } }
.bkc-letter-sign {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 16px; margin-top: 4px;
  & span { font-family: var(--bkc-letter-serif); font-style: italic; color: var(--bkc-letter-muted); }
}
.bkc-letter-post {
  display: inline-flex; align-items: center; gap: 10px; height: 48px; padding: 0 20px 0 22px; border: 0; border-radius: 999px; cursor: pointer;
  background: var(--bkc-letter-red); color: var(--bkc-letter-sheet);
  font-weight: 650; letter-spacing: .01em;
  box-shadow: 0 1px 0 color-mix(in oklch, white 30%, transparent) inset, 0 10px 24px -12px var(--bkc-letter-red);
  transition: transform .5s var(--bkc-letter-spring), background-color .2s;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: transform .5s var(--bkc-letter-spring); }
  &:hover { background: color-mix(in oklch, var(--bkc-letter-red) 88%, var(--bkc-letter-ink)); & svg { transform: translateX(3px); } }
  &:active { transform: scale(.97); transition-duration: .08s; }
  &:focus-visible { outline: 2px solid var(--bkc-letter-ink); outline-offset: 3px; }
}
.bkc-letter-err { min-height: 1.3em; font-size: 13px; font-weight: 550; color: var(--bkc-letter-red); }

/* ---------- the folding sheet ---------- */
.bkc-letter-fold {
  position: relative; z-index: 2; display: grid; grid-template-rows: repeat(3, minmax(0, 1fr));
  pointer-events: none;
  &[hidden] { display: none; }
}
.bkc-letter-panel {
  position: relative; transform-style: preserve-3d;
  &[data-p="top"] { z-index: 3; transform-origin: 50% 100%; }
  &[data-p="mid"] { z-index: 1; }
  &[data-p="bot"] { z-index: 2; transform-origin: 50% 0; }
}
.bkc-letter-face {
  position: absolute; inset: 0; overflow: clip; backface-visibility: hidden;
  display: grid; align-content: center; gap: 6px; padding: 0 clamp(20px, 3.4cqi, 36px) 0 clamp(34px, 5cqi, 52px);
  background:
    linear-gradient(90deg, transparent clamp(20px, 3cqi, 32px), color-mix(in oklch, var(--bkc-letter-red) 45%, transparent) 0 calc(clamp(20px, 3cqi, 32px) + 1px), transparent 0),
    var(--bkc-letter-sheet);
  [data-p="top"] > & { border-radius: 3px 3px 0 0; }
  [data-p="bot"] > & { border-radius: 0 0 3px 3px; }
  &::after { content: ""; position: absolute; inset: 0; background: var(--bkc-letter-ink); opacity: var(--bkc-letter-shade, 0); pointer-events: none; }
}
.bkc-letter-rear {
  transform: rotateX(180deg);
  background: linear-gradient(color-mix(in oklch, var(--bkc-letter-sheet) 92%, var(--bkc-letter-ink)), var(--bkc-letter-sheet));
}
.bkc-letter-w1 { font-family: var(--bkc-letter-serif); font-style: italic; font-size: clamp(20px, 2.4cqi, 24px); }
.bkc-letter-w2 { font-family: var(--bkc-letter-serif); font-size: 16px; color: var(--bkc-letter-muted); }
.bkc-letter-w3 { font-family: var(--bkc-letter-serif); font-size: clamp(20px, 2.6cqi, 26px); overflow-wrap: anywhere; border-bottom: 1.5px solid var(--bkc-letter-ink); padding-bottom: 4px; }

/* ---------- envelope ---------- */
.bkc-letter-env {
  --bkc-letter-pk: calc(var(--bkc-letter-h, 540px) * .86 / 3);
  position: relative; z-index: 1; align-self: center; height: calc(var(--bkc-letter-pk) + 56px);
  &[hidden] { display: none; }
}
.bkc-letter-env-back, .bkc-letter-env-face { position: absolute; inset: 0; }
.bkc-letter-env-wall { position: absolute; inset: 0; border-radius: 6px; background: var(--bkc-letter-kraft-dk); }
.bkc-letter-env-paper {
  position: absolute; z-index: 2; inset: 28px 7%;
  background: linear-gradient(color-mix(in oklch, var(--bkc-letter-sheet) 92%, var(--bkc-letter-ink)), var(--bkc-letter-sheet));
  border-radius: 2px; box-shadow: 0 1px 2px color-mix(in oklch, var(--bkc-letter-ink) 20%, transparent);
}
.bkc-letter-env-pocket {
  position: absolute; z-index: 3; inset: 0; border-radius: 6px;
  clip-path: polygon(0 26%, 50% 64%, 100% 26%, 100% 100%, 0 100%);
  background:
    linear-gradient(to top right, transparent calc(50% - 1px), color-mix(in oklch, var(--bkc-letter-ink) 10%, transparent) 50%, transparent calc(50% + 1px)) 0 100% / 50% 74% no-repeat,
    linear-gradient(to top left, transparent calc(50% - 1px), color-mix(in oklch, var(--bkc-letter-ink) 10%, transparent) 50%, transparent calc(50% + 1px)) 100% 100% / 50% 74% no-repeat,
    linear-gradient(color-mix(in oklch, var(--bkc-letter-kraft) 92%, white), var(--bkc-letter-kraft));
}
.bkc-letter-env-flap {
  position: absolute; z-index: 1; inset: 0 0 auto; height: 60%; transform-origin: 50% 0;
  clip-path: polygon(0 0, 100% 0, 52% 100%, 48% 100%);
  background: linear-gradient(color-mix(in oklch, var(--bkc-letter-kraft) 90%, white), color-mix(in oklch, var(--bkc-letter-kraft) 94%, var(--bkc-letter-ink)));
  transform: perspective(700px) rotateX(180deg);
}
.bkc-letter-env-face {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto 1fr;
  grid-template-areas: "from stamp" "to to";
  padding: clamp(12px, 2.4cqi, 20px); border-radius: 6px;
  background:
    repeating-linear-gradient(-45deg, var(--bkc-letter-red) 0 9px, transparent 9px 18px, oklch(45% 0.12 250) 18px 27px, transparent 27px 36px) 0 0 / 100% 5px no-repeat,
    repeating-linear-gradient(-45deg, var(--bkc-letter-red) 0 9px, transparent 9px 18px, oklch(45% 0.12 250) 18px 27px, transparent 27px 36px) 0 100% / 100% 5px no-repeat,
    linear-gradient(color-mix(in oklch, var(--bkc-letter-kraft) 70%, white), color-mix(in oklch, var(--bkc-letter-kraft) 85%, white));
  box-shadow: 0 22px 40px -22px color-mix(in oklch, var(--bkc-letter-ink) 55%, transparent);
  transform: scaleY(0);
}
.bkc-letter-from { grid-area: from; align-self: start; max-width: 24ch; font-size: 10px; line-height: 1.4; letter-spacing: .08em; text-transform: uppercase; color: color-mix(in oklch, var(--bkc-letter-ink) 60%, transparent); }
.bkc-letter-stamp {
  grid-area: stamp; width: clamp(44px, 7cqi, 56px); height: auto; rotate: 3deg;
  & > rect:first-child { fill: var(--bkc-letter-sheet); stroke: color-mix(in oklch, var(--bkc-letter-kraft) 70%, white); stroke-width: 4; stroke-dasharray: 0 6; stroke-linecap: round; }
  & .bkc-letter-stamp-in { fill: color-mix(in oklch, var(--bkc-letter-red) 12%, var(--bkc-letter-sheet)); }
  & path { fill: none; stroke: var(--bkc-letter-red); stroke-width: 1.6; stroke-linejoin: round; }
  & text { font: 700 9px var(--bkc-letter-mono); fill: var(--bkc-letter-red); letter-spacing: .08em; }
}
.bkc-letter-mark {
  position: absolute; top: clamp(4px, 1.2cqi, 10px); right: clamp(30px, 6cqi, 48px); width: clamp(104px, 16cqi, 130px); opacity: 0;
  & circle, & path { fill: none; stroke: color-mix(in oklch, var(--bkc-letter-ink) 78%, var(--bkc-letter-red)); stroke-width: 2; }
  & circle:nth-of-type(2) { stroke-width: 1; }
  & text { font: 700 11px var(--bkc-letter-mono); letter-spacing: .1em; fill: color-mix(in oklch, var(--bkc-letter-ink) 78%, var(--bkc-letter-red)); }
}
.bkc-letter-to {
  grid-area: to; align-self: end; justify-self: start; display: grid; gap: 2px; max-width: 100%;
  padding: 8px 12px; background: var(--bkc-letter-sheet); rotate: -1.2deg;
  box-shadow: 0 1px 2px color-mix(in oklch, var(--bkc-letter-ink) 18%, transparent);
  & small { font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: var(--bkc-letter-muted); }
  & span { font-family: var(--bkc-letter-mono); font-size: clamp(13px, 1.9cqi, 15px); overflow-wrap: anywhere; }
}

/* ---------- confirmation ---------- */
.bkc-letter-ok {
  position: relative; z-index: 3; align-self: end; display: grid; justify-items: center; gap: 4px; text-align: center; padding-bottom: 4px;
  transition: opacity .6s var(--bkc-letter-out), translate .8s var(--bkc-letter-spring);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.bkc-letter-ok-t { font-family: var(--bkc-letter-serif); font-style: italic; font-size: 26px; outline: none; }
.bkc-letter-ok-p { max-width: 38ch; color: var(--bkc-letter-muted); text-wrap: pretty; & b { color: var(--bkc-letter-ink); font-weight: 600; } }
.bkc-letter-unseal {
  margin-top: 6px; padding: 4px 2px; border: 0; background: none; cursor: pointer;
  font-size: 13px; font-weight: 600; color: var(--bkc-letter-red);
  text-decoration: underline; text-underline-offset: 4px; text-decoration-color: color-mix(in oklch, var(--bkc-letter-red) 40%, transparent);
  &:hover { text-decoration-color: currentColor; }
  &:focus-visible { outline: 2px solid var(--bkc-letter-red); outline-offset: 2px; border-radius: 2px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkc-letter-desks label, .bkc-letter-post, .bkc-letter-post svg { transition: background-color .2s, border-color .2s; }
  .bkc-letter-desks label:active, .bkc-letter-post:active { transform: none; }
  .bkc-letter-post:hover svg { transform: none; }
  .bkc-letter-sheet { transition: opacity .3s linear, visibility 0s; }
  .bkc-letter.is-posted .bkc-letter-sheet { translate: 0 0; }
  .bkc-letter-ok { transition: opacity .3s linear; @starting-style { translate: 0 0; } }
}

