/* Sign-up as correspondence: the form is swapped for a three-panel sheet at the
   same size, folded in thirds, slid into an envelope, turned over and postmarked
   with the Sunday the first letter will actually arrive. */
const $ = (s) => root.querySelector(s);
const sheet = $('.bkc-letter-sheet');
const input = $('.bkc-letter-input');
const err = $('.bkc-letter-err');
const sum = $('.bkc-letter-sum');
const boxes = [...root.querySelectorAll('input[name="desk"]')];
const fold = $('.bkc-letter-fold');
const [pTop, pMid, pBot] = ['top', 'mid', 'bot'].map((k) => $('[data-p="' + k + '"]'));
const env = $('.bkc-letter-env');
const back = $('.bkc-letter-env-back');
const wall = $('.bkc-letter-env-wall');
const paper = $('.bkc-letter-env-paper');
const pocket = $('.bkc-letter-env-pocket');
const flap = $('.bkc-letter-env-flap');
const face = $('.bkc-letter-env-face');
const mark = $('.bkc-letter-mark');
const ok = $('.bkc-letter-ok');
const okT = $('.bkc-letter-ok-t');
const okP = $('[data-ok]');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* ---- dates: No. 214 went out on Sunday 27 September 2026; one letter a week ---- */
const BASE = Date.UTC(2026, 8, 27), BASE_NO = 214, WEEK = 6048e5;
const nextSunday = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + ((7 - d.getDay()) % 7 || 7));
  return d;
};
const issueOf = (d) => BASE_NO + Math.round((Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) - BASE) / WEEK);
const upcoming = nextSunday();
const nextNo = issueOf(upcoming);
$('[data-issue-now]').textContent = 'No. ' + (nextNo - 1);
root.querySelectorAll('.bkc-letter-no').forEach((el, i) => { el.textContent = String(nextNo - 1 - i); });
const dayShort = upcoming.toLocaleDateString('en-GB', { weekday: 'short' });
const dateShort = upcoming.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
$('[data-pm-day]').textContent = dayShort.toUpperCase();
$('[data-pm-date]').textContent = dateShort.toUpperCase();

/* ---- read time ---- */
const chosen = () => boxes.filter((b) => b.checked);
function tally() {
  const picked = chosen();
  const mins = picked.reduce((t, b) => t + Number(b.dataset.min), 0);
  sum.innerHTML = picked.length
    ? 'A <b>' + mins + '</b>-minute read, in your inbox Sundays at 06:00.'
    : 'Tick at least one desk &mdash; there&rsquo;s nothing to post yet.';
  if (picked.length && err.dataset.k === 'desk') clearErr();
}
root.addEventListener('change', (e) => { if (e.target.name === 'desk') tally(); });

/* ---- validation ---- */
const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
function clearErr() { err.textContent = ''; err.dataset.k = ''; input.removeAttribute('aria-invalid'); }
function fail(k, msg, el) {
  err.textContent = msg; err.dataset.k = k;
  if (k === 'email') input.setAttribute('aria-invalid', 'true');
  el.focus();
  if (!reduce.matches) el.animate([{ translate: '0' }, { translate: '-5px' }, { translate: '4px' }, { translate: '-2px' }, { translate: '0' }], { duration: 360, easing: 'cubic-bezier(.36,.07,.19,.97)' });
}
input.addEventListener('input', () => { if (err.dataset.k === 'email' && EMAIL.test(input.value.trim())) clearErr(); });

const join = (a) => a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1];
const esc = (s) => s.replace(/[&<>"']/g, (c) => '&#' + c.charCodeAt(0) + ';');

sheet.addEventListener('submit', (e) => {
  e.preventDefault();
  const val = input.value.trim();
  if (!val) return fail('email', 'We’ll need an address to post it to.', input);
  if (!EMAIL.test(val)) return fail('email', 'That address is missing something — check the @ and the dot.', input);
  if (!chosen().length) return fail('desk', 'Tick at least one desk.', boxes[0]);
  clearErr();
  post(val);
});

/* ---- the choreography ---- */
let token = 0, anims = [];
const run = (el, kf, opt) => { const a = el.animate(kf, Object.assign({ fill: 'both' }, opt)); anims.push(a); return a; };
const P = 'perspective(1400px) ';
const FOLD = 'cubic-bezier(.6,0,.25,1)';
const SPRING = 'linear(0, .013, .05 2.3%, .2 5%, .766 13.4%, .963 17.5%, 1.04 21%, 1.065 24%, 1.064 26.9%, 1.015 35%, .995 41.6%, 1.001 60%, 1)';

const measure = () => root.style.setProperty('--bkc-letter-h', sheet.offsetHeight + 'px');
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } measure(); });
ro.observe(sheet);

async function post(email) {
  const gen = ++token;
  const desks = chosen().map((b) => b.value);
  measure();
  $('[data-w-email]').textContent = email;
  $('[data-w-desks]').textContent = 'with the ' + join(desks) + ' desk' + (desks.length > 1 ? 's' : '');
  $('[data-env-to]').textContent = email;
  okP.innerHTML = 'No. ' + nextNo + ' lands <b>' + dayShort + ' ' + dateShort + '</b> at 06:00. One tap on the note we just sent to <b>' + esc(email) + '</b> confirms it.';
  root.classList.add('is-posted');
  sheet.inert = true;

  if (reduce.matches) {
    env.hidden = false;
    back.style.opacity = '0';
    face.style.transform = 'none';
    mark.style.opacity = '.9';
    mark.style.transform = 'rotate(-10deg)';
    ok.hidden = false;
    env.style.translate = '0 ' + -lift() + 'px';
    okT.focus({ preventScroll: true });
    return;
  }

  const live = () => gen === token && root.isConnected;
  fold.hidden = false;
  /* 1 · the bottom third folds up, its face darkening as it turns away from the light */
  const shade = [{ opacity: 0 }, { opacity: .16, offset: .5 }, { opacity: 0 }];
  run(pBot.firstElementChild, shade, { duration: 640, delay: 160, pseudoElement: '::after' });
  await run(pBot, [{ transform: P + 'rotateX(0deg)' }, { transform: P + 'rotateX(180deg)' }], { duration: 640, delay: 160, easing: FOLD }).finished.catch(() => {});
  if (!live()) return;
  /* 2 · the top third folds down over it */
  run(pTop.firstElementChild, shade, { duration: 640, pseudoElement: '::after' });
  await run(pTop, [{ transform: P + 'rotateX(0deg)' }, { transform: P + 'rotateX(-180deg)' }], { duration: 640, easing: FOLD }).finished.catch(() => {});
  if (!live()) return;
  /* 3 · the packet lifts and shrinks to envelope size */
  await run(fold, [{ transform: 'none' }, { transform: 'scale(.86)' }], { duration: 360, easing: 'cubic-bezier(.3,.7,.2,1)' }).finished.catch(() => {});
  if (!live()) return;
  /* 4 · swap to the identical packet inside the envelope, then raise the envelope around it */
  env.hidden = false;
  fold.hidden = true;
  const rise = (el, extra, delay) => run(el, [{ transform: 'translateY(60%) ' + extra, opacity: 0 }, { transform: 'translateY(0) ' + extra, opacity: 1 }], { duration: 620, delay, easing: SPRING });
  rise(wall, '', 0);
  rise(flap, 'perspective(700px) rotateX(180deg)', 0);
  await rise(pocket, '', 50).finished.catch(() => {});
  if (!live()) return;
  /* 5 · the letter settles and the flap closes, crossing in front of it halfway */
  run(paper, [{ transform: 'none' }, { transform: 'translateY(6px)' }], { duration: 360, easing: 'cubic-bezier(.3,.7,.2,1)' });
  await run(flap, [
    { transform: 'perspective(700px) rotateX(180deg)', zIndex: 1 },
    { transform: 'perspective(700px) rotateX(90deg)', zIndex: 1, offset: .5 },
    { transform: 'perspective(700px) rotateX(90deg)', zIndex: 4, offset: .501 },
    { transform: 'perspective(700px) rotateX(0deg)', zIndex: 4 },
  ], { duration: 560, delay: 80, easing: 'cubic-bezier(.5,0,.2,1)' }).finished.catch(() => {});
  if (!live()) return;
  /* 6 · turn it over */
  await run(back, [{ transform: 'scaleY(1)' }, { transform: 'scaleY(0)' }], { duration: 190, easing: 'cubic-bezier(.5,0,1,1)' }).finished.catch(() => {});
  if (!live()) return;
  await run(face, [{ transform: 'scaleY(0)' }, { transform: 'scaleY(1)' }], { duration: 340, easing: 'cubic-bezier(.2,1.25,.4,1)' }).finished.catch(() => {});
  if (!live()) return;
  /* 7 · postmark: ink lands hard, the envelope dips under the hand */
  run(mark, [{ transform: 'scale(1.9) rotate(-26deg)', opacity: 0 }, { transform: 'scale(1) rotate(-10deg)', opacity: .9 }], { duration: 240, easing: 'cubic-bezier(.4,1.6,.6,1)' });
  run(face, [{ translate: '0 0' }, { translate: '0 4px', offset: .35 }, { translate: '0 0' }], { duration: 380, delay: 170, easing: 'ease-out', fill: 'none' });
  await new Promise((r) => setTimeout(r, 420));
  if (!live()) return;
  ok.hidden = false;
  const up = lift();
  if (up) run(env, [{ translate: '0 0' }, { translate: '0 ' + -up + 'px' }], { duration: 640, easing: SPRING });
  okT.focus({ preventScroll: true });
}

/* the envelope sits where the folded packet was; lift it just enough to clear the note below */
function lift() {
  const avail = (sheet.offsetHeight - env.offsetHeight) / 2;
  return Math.max(0, Math.round(ok.offsetHeight + 28 - avail));
}

$('.bkc-letter-unseal').addEventListener('click', () => {
  token++;
  anims.forEach((a) => a.cancel());
  anims = [];
  [back, face, mark, env].forEach((el) => el.removeAttribute('style'));
  ok.hidden = true;
  env.hidden = true;
  fold.hidden = true;
  root.classList.remove('is-posted');
  sheet.inert = false;
  input.focus();
  input.select();
});

tally();

css:
@property --bkc-phone-done { syntax: "<number>"; inherits: true; initial-value: 25; }

.bkc-phone {
  /* re-theme: mint ground, forest ink, tomato for thirst, leaf green for wet */
  --bkc-phone-bg: oklch(94.5% 0.045 152);
  --bkc-phone-ink: oklch(29% 0.06 160);
  --bkc-phone-pop: oklch(67% 0.18 33);
  --bkc-phone-leaf: oklch(63% 0.14 148);

  --bkc-phone-card: color-mix(in oklch, var(--bkc-phone-bg) 35%, white);
  --bkc-phone-muted: color-mix(in oklch, var(--bkc-phone-ink) 68%, var(--bkc-phone-bg));
  --bkc-phone-line: color-mix(in oklch, var(--bkc-phone-ink) 14%, transparent);
  --bkc-phone-glass: oklch(22% 0.02 160);
  --bkc-phone-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  --bkc-phone-spring: linear(0, .009, .036 2.1%, .144 4.4%, .741 13.2%, .945 17%, 1.026 19.8%, 1.075 22.7%, 1.087 25%, 1.078 27.6%, 1.019 35.4%, .996 40.4%, .993 45.8%, 1.001 62%, 1);
  --bkc-phone-out: cubic-bezier(.2, .9, .3, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  overflow: clip;
  color: var(--bkc-phone-ink);
  background:
    radial-gradient(50% 60% at 78% 55%, color-mix(in oklch, var(--bkc-phone-leaf) 22%, transparent), transparent 70%),
    var(--bkc-phone-bg);
  font: 500 15px/1.5 var(--bkc-phone-round);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button, input, select) { font: inherit; color: inherit; }
}

.bkc-phone-in {
  max-width: 1140px; margin-inline: auto;
  padding: clamp(40px, 7cqi, 88px) clamp(16px, 4.5cqi, 56px);
  display: grid; gap: clamp(26px, 4cqi, 36px);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "copy" "stage" "form" "meta";
}
@container (width >= 860px) {
  .bkc-phone-in { grid-template-columns: minmax(0, 1fr) minmax(340px, 440px); grid-template-areas: "copy stage" "form stage" "meta stage"; grid-template-rows: auto auto 1fr; column-gap: clamp(40px, 6cqi, 80px); align-items: start; }
}

/* ---------- copy ---------- */
.bkc-phone-copy { grid-area: copy; display: grid; gap: 14px; align-self: end; }
.bkc-phone-brand {
  display: inline-flex; align-items: center; gap: 8px; font-size: 17px; font-weight: 800; letter-spacing: -.01em;
  & svg { width: 30px; height: 30px; padding: 4px; border-radius: 10px; background: var(--bkc-phone-ink); fill: none; stroke: var(--bkc-phone-bg); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.bkc-phone-title { font-size: clamp(38px, 7.4cqi, 76px); font-weight: 850; line-height: .96; letter-spacing: -.045em; text-wrap: balance; }
@container (width >= 860px) { .bkc-phone-title { font-size: clamp(54px, 6.4cqi, 76px); } }
.bkc-phone-lede { max-width: 48ch; font-size: clamp(15px, 1.6cqi, 18px); font-weight: 500; color: var(--bkc-phone-muted); text-wrap: pretty; }

/* ---------- form ---------- */
.bkc-phone-form { grid-area: form; display: grid; gap: 10px; max-width: 520px; }
.bkc-phone-label { font-size: 13px; font-weight: 750; letter-spacing: .04em; text-transform: uppercase; }
.bkc-phone-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 8px;
  & .bkc-phone-send { grid-column: 1 / -1; }
}
@container (width >= 480px) {
  .bkc-phone-row { grid-template-columns: auto minmax(0, 1fr) auto; padding: 6px; border-radius: 20px; background: var(--bkc-phone-card); box-shadow: 0 0 0 2px var(--bkc-phone-ink);
    & .bkc-phone-send { grid-column: auto; }
    & :is(.bkc-phone-cc, .bkc-phone-num) { box-shadow: none; background-color: transparent; }
    & .bkc-phone-cc { border-radius: 12px; background-color: color-mix(in oklch, var(--bkc-phone-bg) 70%, transparent); }
  }
}
.bkc-phone-cc, .bkc-phone-num {
  height: 50px; border: 0; border-radius: 14px; background-color: var(--bkc-phone-card);
  box-shadow: 0 0 0 2px var(--bkc-phone-ink); font-size: 16px; font-weight: 650;
  &:focus-visible { outline: 3px solid var(--bkc-phone-pop); outline-offset: 2px; }
}
.bkc-phone-cc {
  appearance: none; padding: 0 30px 0 14px; cursor: pointer; font-variant-numeric: tabular-nums;
  background-image: linear-gradient(45deg, transparent 50%, currentColor 50% calc(50% + 2px), transparent 0), linear-gradient(-45deg, transparent 50%, currentColor 50% calc(50% + 2px), transparent 0);
  background-size: 6px 6px; background-repeat: no-repeat; background-position: calc(100% - 17px) 22px, calc(100% - 11px) 22px;
}
.bkc-phone-num {
  min-width: 0; padding: 0 14px; letter-spacing: .02em; font-variant-numeric: tabular-nums;
  &::placeholder { color: color-mix(in oklch, var(--bkc-phone-ink) 36%, transparent); font-weight: 550; }
  &:focus-visible { outline-offset: 2px; }
  &[aria-invalid="true"] { box-shadow: 0 0 0 2px var(--bkc-phone-pop); }
}
.bkc-phone-send {
  position: relative; height: 50px; min-width: 132px; padding: 0 22px; border: 0; border-radius: 14px; cursor: pointer;
  background: var(--bkc-phone-pop); color: oklch(99% 0.01 60); font-weight: 800; letter-spacing: .01em;
  box-shadow: 0 3px 0 color-mix(in oklch, var(--bkc-phone-pop) 60%, var(--bkc-phone-ink));
  transition: transform .45s var(--bkc-phone-spring), box-shadow .2s, background-color .3s;
  &:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 5px 0 color-mix(in oklch, var(--bkc-phone-pop) 60%, var(--bkc-phone-ink)); }
  &:active:not(:disabled) { transform: translateY(2px); box-shadow: 0 1px 0 color-mix(in oklch, var(--bkc-phone-pop) 60%, var(--bkc-phone-ink)); transition-duration: .06s; }
  &:focus-visible { outline: 3px solid var(--bkc-phone-ink); outline-offset: 3px; }
  &:disabled { cursor: default; background: var(--bkc-phone-ink); box-shadow: 0 3px 0 color-mix(in oklch, var(--bkc-phone-ink) 60%, black); }
  & [data-send] { display: inline-flex; align-items: center; gap: 8px; font-variant-numeric: tabular-nums; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
  &.is-busy [data-send]::before { content: ""; width: 14px; height: 14px; border-radius: 50%; border: 2.5px solid currentColor; border-right-color: transparent; animation: bkc-phone-spin .7s linear infinite; }
}
@keyframes bkc-phone-spin { to { rotate: 1turn; } }
.bkc-phone-hint { font-size: 13px; color: var(--bkc-phone-muted); min-height: 1.5em; .bkc-phone-form.is-bad & { color: color-mix(in oklch, var(--bkc-phone-pop) 75%, var(--bkc-phone-ink)); font-weight: 650; } }

/* ---------- meta ---------- */
.bkc-phone-meta { grid-area: meta; display: flex; flex-wrap: wrap; gap: 18px 28px; align-items: center; }
.bkc-phone-scan {
  display: flex; align-items: center; gap: 14px;
  & p { display: grid; font-size: 14px; font-weight: 750; line-height: 1.3; }
  & small { font-size: 12px; font-weight: 550; color: var(--bkc-phone-muted); }
}
.bkc-phone-qr { width: 84px; height: 84px; padding: 7px; border-radius: 14px; background: oklch(99% 0 0); box-shadow: 0 0 0 2px var(--bkc-phone-ink); & path { fill: var(--bkc-phone-ink); } }
.bkc-phone-rate { display: grid; gap: 2px; }
.bkc-phone-stars {
  display: flex; align-items: center; gap: 8px; color: var(--bkc-phone-pop);
  & svg { width: 100px; height: 20px; fill: currentColor; }
  & .bkc-phone-part { fill: url(#bkc-phone-part); stroke: currentColor; stroke-width: 1.2; }
  & b { font-size: 20px; font-weight: 850; color: var(--bkc-phone-ink); font-variant-numeric: tabular-nums; }
}
.bkc-phone-small { font-size: 12.5px; color: var(--bkc-phone-muted); font-variant-numeric: tabular-nums; }

/* ---------- stage + leaves ---------- */
.bkc-phone-stage { grid-area: stage; position: relative; display: grid; place-items: center; padding-block: 8px 12px; }
.bkc-phone-leaves {
  position: absolute; left: 50%; bottom: -6%; width: min(130%, 560px); translate: -50% 0; overflow: visible; pointer-events: none;
  & path { fill: color-mix(in oklch, var(--bkc-phone-leaf) 55%, var(--bkc-phone-bg)); transform-box: fill-box; transform-origin: 50% 100%; animation: bkc-phone-sway 6.5s cubic-bezier(.45, 0, .55, 1) calc(var(--i) * -1.9s) infinite alternate; }
  & path:nth-child(2) { fill: color-mix(in oklch, var(--bkc-phone-leaf) 80%, var(--bkc-phone-ink)); transform-origin: 0% 100%; }
  & path:nth-child(3) { fill: color-mix(in oklch, var(--bkc-phone-leaf) 38%, var(--bkc-phone-bg)); transform-origin: 100% 100%; }
  .bkc-phone.is-off & path { animation-play-state: paused; }
}
@keyframes bkc-phone-sway { from { rotate: -4deg; } to { rotate: 3deg; } }

/* ---------- the phone ---------- */
.bkc-phone-device {
  --bkc-phone-w: clamp(236px, 27cqi, 300px);
  position: relative; width: var(--bkc-phone-w); aspect-ratio: 9 / 19.2;
  padding: calc(var(--bkc-phone-w) * .035); border-radius: calc(var(--bkc-phone-w) * .16);
  background: linear-gradient(150deg, oklch(36% 0.015 160), var(--bkc-phone-glass) 40%, oklch(16% 0.01 160));
  box-shadow: inset 0 0 0 1.5px oklch(48% 0.02 160), inset 0 0 0 4px oklch(14% 0.01 160), 0 30px 60px -24px color-mix(in oklch, var(--bkc-phone-ink) 70%, transparent), 0 12px 24px -12px color-mix(in oklch, var(--bkc-phone-ink) 50%, transparent);
  font-size: calc(var(--bkc-phone-w) / 22);
  animation: bkc-phone-bob 5.5s cubic-bezier(.45, 0, .55, 1) infinite alternate;
  .bkc-phone.is-off & { animation-play-state: paused; }
  &::before, &::after { content: ""; position: absolute; width: 3px; border-radius: 2px; background: oklch(30% 0.012 160); }
  &::before { left: -2px; top: 22%; height: 9%; box-shadow: 0 calc(var(--bkc-phone-w) * .16) 0 oklch(30% 0.012 160); }
  &::after { right: -2px; top: 28%; height: 14%; }
  &.is-buzz { animation: bkc-phone-buzz .42s linear; }
}
@keyframes bkc-phone-bob { from { translate: 0 -5px; } to { translate: 0 7px; } }
@keyframes bkc-phone-buzz { 0%, 100% { rotate: 0deg; } 15% { rotate: -2.4deg; } 30% { rotate: 2.2deg; } 45% { rotate: -1.8deg; } 60% { rotate: 1.4deg; } 75% { rotate: -.7deg; } }

.bkc-phone-screen {
  position: relative; height: 100%; overflow: clip; isolation: isolate;
  border-radius: calc(var(--bkc-phone-w) * .125);
  background: linear-gradient(color-mix(in oklch, var(--bkc-phone-bg) 70%, white), color-mix(in oklch, var(--bkc-phone-bg) 85%, white));
}
.bkc-phone-bar {
  position: absolute; z-index: 3; inset: 0 0 auto; height: 3em; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; padding: 0 1.6em;
  background: linear-gradient(color-mix(in oklch, var(--bkc-phone-bg) 70%, white) 60%, transparent);
  font-size: .95em; font-weight: 750; font-variant-numeric: tabular-nums;
  & .bkc-phone-icons { justify-self: end; display: flex; gap: .35em; align-items: center; }
  & svg { height: .8em; width: auto; fill: currentColor; }
  & svg:last-child { height: .85em; fill: none; stroke: currentColor; stroke-width: 1.2; & .bkc-phone-cell { fill: currentColor; stroke: none; } }
}
.bkc-phone-island { width: 6.2em; height: 1.75em; border-radius: 1em; background: oklch(10% 0 0); }

.bkc-phone-app {
  position: absolute; inset: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none;
  padding: 3.4em .95em 2.6em; display: grid; align-content: start; gap: .55em;
  &::-webkit-scrollbar { display: none; }
  &:focus-visible { outline: 3px solid var(--bkc-phone-pop); outline-offset: -3px; }
}
.bkc-phone-hi { font-size: .9em; font-weight: 600; color: var(--bkc-phone-muted); }
.bkc-phone-sum { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: .6em; margin-bottom: .2em; }
.bkc-phone-big { font-size: 1.6em; font-weight: 850; line-height: 1.05; letter-spacing: -.03em; text-wrap: balance; }
.bkc-phone-ring {
  width: 3.4em; height: 3.4em; rotate: -90deg;
  & circle { fill: none; stroke: var(--bkc-phone-line); stroke-width: 3.5; }
  & .bkc-phone-arc { stroke: var(--bkc-phone-leaf); stroke-linecap: round; stroke-dasharray: var(--bkc-phone-done) 100; transition: --bkc-phone-done .9s var(--bkc-phone-spring); }
  & text { rotate: 90deg; transform-origin: 18px 18px; font: 800 9px var(--bkc-phone-round); fill: var(--bkc-phone-ink); font-variant-numeric: tabular-nums; }
}
.bkc-phone-h { margin-top: .5em; font-size: .78em; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--bkc-phone-muted); }
.bkc-phone-list { display: grid; gap: .45em; &:empty { display: none; } }
.bkc-phone-h:has(+ .bkc-phone-list:empty) { display: none; }

.bkc-phone-card {
  --bkc-phone-mm: var(--m);
  position: relative; display: grid; grid-template-columns: 2.3em minmax(0, 1fr) auto; align-items: center; gap: .6em;
  padding: .6em .6em .75em; border-radius: 1em; overflow: clip;
  background: var(--bkc-phone-card); box-shadow: 0 1px 0 var(--bkc-phone-line), 0 .3em .9em -.5em color-mix(in oklch, var(--bkc-phone-ink) 30%, transparent);
  .bkc-phone-soon & { grid-template-columns: minmax(0, 1fr) auto; padding-block: .55em .7em; }
}
.bkc-phone-plant { width: 2.3em; height: 2.3em; padding: .4em; border-radius: .75em; background: oklch(92% 0.06 var(--h)); fill: none; stroke: color-mix(in oklch, var(--bkc-phone-ink) 85%, oklch(50% 0.1 var(--h))); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.bkc-phone-name { display: grid; font-size: 1em; font-weight: 750; line-height: 1.2; letter-spacing: -.01em; & small { font-size: .78em; font-weight: 550; color: var(--bkc-phone-muted); } }
.bkc-phone-when { font-size: .8em; font-weight: 750; color: var(--bkc-phone-muted); white-space: nowrap; }
.bkc-phone-water, .bkc-phone-tick {
  display: grid; place-items: center; width: 2.4em; height: 2.4em; border-radius: 50%;
  & svg { width: 1.25em; height: 1.25em; }
}
.bkc-phone-water {
  border: 0; cursor: pointer; padding: 0; background: color-mix(in oklch, var(--bkc-phone-pop) 16%, transparent); color: var(--bkc-phone-pop);
  transition: transform .45s var(--bkc-phone-spring), background-color .2s;
  & svg { fill: currentColor; }
  &:hover { background: color-mix(in oklch, var(--bkc-phone-pop) 26%, transparent); transform: scale(1.08); }
  &:active { transform: scale(.9); transition-duration: .06s; }
  &:focus-visible { outline: 2.5px solid var(--bkc-phone-pop); outline-offset: 2px; }
}
.bkc-phone-tick { background: color-mix(in oklch, var(--bkc-phone-leaf) 22%, transparent); color: color-mix(in oklch, var(--bkc-phone-leaf) 70%, var(--bkc-phone-ink));
  & svg { fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 20; stroke-dashoffset: 0; }
  @starting-style { & svg { stroke-dashoffset: 20; } }
  & svg { transition: stroke-dashoffset .5s var(--bkc-phone-out) .15s; }
}
.bkc-phone-moist {
  position: absolute; left: .6em; right: .6em; bottom: .35em; height: .2em; border-radius: 1em; background: var(--bkc-phone-line); overflow: clip;
  &::after { content: ""; position: absolute; inset: 0; border-radius: inherit; transform-origin: 0 50%; transform: scaleX(var(--bkc-phone-mm));
    background: color-mix(in oklch, var(--bkc-phone-pop) calc((1 - var(--bkc-phone-mm)) * 100%), var(--bkc-phone-leaf));
    transition: transform 1.1s var(--bkc-phone-out) .2s, background-color 1.1s .2s; }
  .bkc-phone-card.is-done & { --bkc-phone-mm: .9; }
}
@supports (animation-timeline: view()) {
  .bkc-phone-card { animation: bkc-phone-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }
}
@keyframes bkc-phone-rise { from { opacity: 0; transform: translateY(1.2em) scale(.94); } }

/* incoming text */
.bkc-phone-note {
  position: absolute; z-index: 4; top: .55em; left: .5em; right: .5em;
  display: grid; grid-template-columns: 2.2em minmax(0, 1fr); column-gap: .6em; row-gap: .1em; align-items: center;
  padding: .7em .8em; border-radius: 1.3em; cursor: pointer;
  background: color-mix(in oklch, white 82%, transparent); backdrop-filter: blur(14px) saturate(1.4);
  box-shadow: 0 .5em 1.5em -.4em color-mix(in oklch, var(--bkc-phone-ink) 45%, transparent);
  transform: translateY(calc(-100% - 1em)); opacity: 0;
  transition: transform .5s cubic-bezier(.5, 0, .75, 0), opacity .3s .2s;
  &.is-in { transform: none; opacity: 1; transition: transform .8s var(--bkc-phone-spring), opacity .2s; }
  & p { display: flex; justify-content: space-between; font-size: .82em; font-weight: 750; & span { font-weight: 550; color: var(--bkc-phone-muted); } }
  & .bkc-phone-note-t { grid-column: 2; display: block; font-size: .82em; font-weight: 550; line-height: 1.3; }
}
.bkc-phone-note-ic { grid-row: span 2; align-self: start; width: 2.2em; height: 2.2em; padding: .4em; border-radius: .6em; background: var(--bkc-phone-leaf); fill: oklch(99% 0 0); }
.bkc-phone-home { position: absolute; z-index: 3; left: 50%; bottom: .5em; width: 36%; height: .3em; translate: -50% 0; border-radius: 1em; background: var(--bkc-phone-ink); opacity: .8; }

@media (prefers-reduced-motion: reduce) {
  .bkc-phone-leaves path, .bkc-phone-device, .bkc-phone-device.is-buzz { animation: none; }
  .bkc-phone-card { animation: none; }
  .bkc-phone-note, .bkc-phone-note.is-in { transition: opacity .25s linear; }
  .bkc-phone-note:not(.is-in) { transform: translateY(calc(-100% - 1em)); }
  .bkc-phone-note.is-in { transform: none; }
  .bkc-phone-send, .bkc-phone-water { transition: background-color .2s; }
  .bkc-phone-send:hover:not(:disabled), .bkc-phone-send:active:not(:disabled), .bkc-phone-water:hover, .bkc-phone-water:active { transform: none; }
  .bkc-phone-moist::after { transition: none; }
  .bkc-phone-ring .bkc-phone-arc { transition: none; }
  .bkc-phone-send.is-busy [data-send]::before { animation-duration: 2s; }
}

