/* The phone is a working preview: water a plant and it FLIPs into "Done today";
   ask for the link and a text drops onto its lock screen. */
const $ = (s) => root.querySelector(s);
const app = $('.bkc-phone-app');
const due = $('[data-list="due"]');
const doneList = $('[data-list="done"]');
const big = $('[data-big]');
const ringT = $('[data-ring]');
const device = $('.bkc-phone-device');
const note = $('.bkc-phone-note');
const form = $('.bkc-phone-form');
const cc = $('.bkc-phone-cc');
const num = $('.bkc-phone-num');
const send = $('.bkc-phone-send');
const sendLabel = $('[data-send]');
const hint = $('.bkc-phone-hint');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, .009, .036 2.1%, .144 4.4%, .741 13.2%, .945 17%, 1.026 19.8%, 1.075 22.7%, 1.087 25%, 1.078 27.6%, 1.019 35.4%, .996 40.4%, .993 45.8%, 1.001 62%, 1)';

/* lists must be truly :empty once their last card leaves */
[due, doneList].forEach((ul) => [...ul.childNodes].forEach((n) => { if (n.nodeType === 3) n.remove(); }));
const TOTAL = due.children.length + doneList.children.length;

function counts() {
  const left = due.children.length, fin = TOTAL - left;
  big.textContent = left === 0 ? 'Everyone’s watered.' : left + (left === 1 ? ' plant is' : ' plants are') + ' thirsty';
  ringT.textContent = fin + '/' + TOTAL;
  root.style.setProperty('--bkc-phone-done', (fin / TOTAL * 100).toFixed(1));
}

/* ---------- FLIP: water a plant ---------- */
function water(card) {
  const moving = [...app.querySelectorAll('.bkc-phone-card, .bkc-phone-h')];
  const first = new Map(moving.map((el) => [el, el.getBoundingClientRect()]));
  const btn = card.querySelector('.bkc-phone-water');
  const hadFocus = document.activeElement === btn;
  const tick = document.createElement('span');
  tick.className = 'bkc-phone-tick';
  tick.setAttribute('aria-hidden', 'true');
  tick.innerHTML = '<svg viewBox="0 0 24 24"><path d="M6 12.5l4 4 8-9"/></svg>';
  btn.replaceWith(tick);
  const small = card.querySelector('small');
  small.textContent = small.textContent.split('·')[0].trim() + ' · watered 08:12';   /* matches the status-bar clock */
  card.classList.add('is-done');
  doneList.prepend(card);
  counts();
  if (!reduce.matches) {
    for (const el of moving) {
      const f = first.get(el), l = el.getBoundingClientRect();
      const dx = f.left - l.left, dy = f.top - l.top;
      if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) continue;
      const lift = el === card;
      el.animate(lift
        ? [{ transform: `translate(${dx}px, ${dy}px)` }, { transform: `translate(${dx * 0.4}px, ${dy * 0.4}px) scale(1.04)`, offset: 0.35 }, { transform: 'none' }]
        : [{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }],
        { duration: lift ? 640 : 560, easing: SPRING, composite: 'replace' });
    }
  }
  if (hadFocus) {
    const next = due.querySelector('.bkc-phone-water');
    (next || app).focus({ preventScroll: true });
  }
}
root.addEventListener('click', (e) => {
  const btn = e.target.closest('.bkc-phone-water');
  if (btn) water(btn.closest('.bkc-phone-card'));
  if (e.target.closest('.bkc-phone-note')) hideNote();
});

/* ---------- text me the link ---------- */
const RULES = { 44: [10, 10, [4, 6]], 1: [10, 10, [3, 3, 4]], 353: [9, 9, [2, 3, 4]], 61: [9, 9, [3, 3, 3]], 49: [10, 11, [4, 7]] };
const digits = () => {
  let d = num.value.replace(/\D/g, '');
  if (cc.value !== '1' && d.startsWith('0')) d = d.slice(1);   /* drop the trunk 0 */
  if (d.startsWith(cc.value) && d.length > RULES[cc.value][1]) d = d.slice(cc.value.length);
  return d;
};
const pretty = (d) => {
  const g = RULES[cc.value][2], out = [];
  let i = 0;
  for (const n of g) { if (i >= d.length) break; out.push(d.slice(i, i + n)); i += n; }
  if (i < d.length) out[out.length - 1] += d.slice(i);
  return '+' + cc.value + ' ' + out.join(' ');
};
cc.addEventListener('change', () => { num.placeholder = cc.selectedOptions[0].dataset.ph; num.focus(); });

const BASE_HINT = hint.textContent;
let timer = 0, hideT = 0;
function bad(msg) {
  form.classList.add('is-bad');
  num.setAttribute('aria-invalid', 'true');
  hint.textContent = msg;
  num.focus();
}
num.addEventListener('input', () => {
  if (!form.classList.contains('is-bad')) return;
  form.classList.remove('is-bad');
  num.removeAttribute('aria-invalid');
  hint.textContent = BASE_HINT;
});

function showNote() {
  clearTimeout(hideT);
  note.classList.add('is-in');
  if (!reduce.matches) {
    device.classList.remove('is-buzz');
    void device.offsetWidth;            /* restart the buzz */
    device.classList.add('is-buzz');
  }
  hideT = setTimeout(hideNote, 7000);
}
function hideNote() { clearTimeout(hideT); note.classList.remove('is-in'); }
device.addEventListener('animationend', (e) => { if (e.animationName === 'bkc-phone-buzz') device.classList.remove('is-buzz'); });
note.addEventListener('pointerenter', () => clearTimeout(hideT));
note.addEventListener('pointerleave', () => { if (note.classList.contains('is-in')) hideT = setTimeout(hideNote, 2500); });

form.addEventListener('submit', (e) => {
  e.preventDefault();
  if (send.disabled) return;
  const d = digits(), [lo, hi] = RULES[cc.value];
  if (!d.length) return bad('Add your mobile number and we’ll text the link.');
  if (d.length < lo) return bad('That number looks short — a +' + cc.value + ' mobile has ' + lo + (lo !== hi ? '–' + hi : '') + ' digits after the 0.');
  if (d.length > hi) return bad('That number looks long — check for an extra digit.');
  const shown = pretty(d);
  send.disabled = true;
  send.classList.add('is-busy');
  send.setAttribute('aria-busy', 'true');
  sendLabel.textContent = 'Sending';
  setTimeout(() => {
    if (!root.isConnected) return;
    send.classList.remove('is-busy');
    send.removeAttribute('aria-busy');
    sendLabel.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12.5l4 4 8-9"/></svg>Sent';
    hint.textContent = 'Sent to ' + shown + '. It should land in a few seconds.';
    showNote();
    let left = 30;
    clearInterval(timer);
    timer = setInterval(() => {
      if (!root.isConnected) return clearInterval(timer);
      left -= 1;
      if (left > 0) {
        if (left <= 27) sendLabel.textContent = 'Resend in 0:' + String(left).padStart(2, '0');
        return;
      }
      clearInterval(timer);
      send.disabled = false;
      sendLabel.textContent = 'Resend';
      hint.textContent = 'Didn’t get it? Check the number and send it again.';
    }, 1000);
  }, reduce.matches ? 200 : 750);
});

/* ---------- a decorative scan code (swap in your real one) ---------- */
(function drawCode() {
  const N = 25, g = Array.from({ length: N }, () => new Array(N).fill(-1));
  const finder = (x, y) => {
    for (let j = -1; j < 8; j++) for (let i = -1; i < 8; i++) {
      const X = x + i, Y = y + j;
      if (X < 0 || Y < 0 || X >= N || Y >= N) continue;
      const ring = i === 0 || i === 6 || j === 0 || j === 6, core = i >= 2 && i <= 4 && j >= 2 && j <= 4;
      g[Y][X] = i >= 0 && i <= 6 && j >= 0 && j <= 6 && (ring || core) ? 1 : 0;
    }
  };
  finder(0, 0); finder(N - 7, 0); finder(0, N - 7);
  for (let j = 0; j < 5; j++) for (let i = 0; i < 5; i++) g[16 + j][16 + i] = (i === 0 || i === 4 || j === 0 || j === 4 || (i === 2 && j === 2)) ? 1 : 0;
  for (let k = 8; k < N - 8; k++) { g[6][k] = g[k][6] = k % 2 ? 0 : 1; }
  let s = 0;
  for (const ch of 'mossbud.app/get') s = (s * 31 + ch.charCodeAt(0)) >>> 0;
  const rnd = () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
  let d = '';
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    if (g[y][x] === -1) g[y][x] = rnd() < 0.47 ? 1 : 0;
    if (g[y][x] === 1) d += 'M' + x + ' ' + y + 'h1v1h-1z';
  }
  $('[data-qr]').setAttribute('d', d);
})();

/* ---------- pause ambient motion off screen ---------- */
const io = new IntersectionObserver(([en]) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle('is-off', !en.isIntersecting);
});
io.observe(root);

counts();

