@property --bkc-ticket-ahead { syntax: "<integer>"; inherits: true; initial-value: 0; }

.bkc-ticket {
  /* re-theme: ground, ink, signal red, ticket stock */
  --bkc-ticket-bg: oklch(92% 0.175 106);
  --bkc-ticket-ink: oklch(17% 0.01 95);
  --bkc-ticket-red: oklch(58% 0.225 28);
  --bkc-ticket-stock: oklch(89% 0.065 14);

  --bkc-ticket-paper: color-mix(in oklch, var(--bkc-ticket-bg) 18%, white);
  --bkc-ticket-dim: color-mix(in oklch, var(--bkc-ticket-ink) 70%, var(--bkc-ticket-bg));
  --bkc-ticket-led: color-mix(in oklch, var(--bkc-ticket-red) 80%, oklch(75% 0.2 40));
  --bkc-ticket-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkc-ticket-b: 3px solid var(--bkc-ticket-ink);
  --bkc-ticket-hard: 6px 6px 0 var(--bkc-ticket-ink);
  --bkc-ticket-spring: linear(0, .011, .044 2.2%, .175 4.7%, .757 13.6%, .953 17.6%, 1.036 21%, 1.072 24.2%, 1.074 27.2%, 1.02 35.7%, .996 41.6%, 1.001 61%, 1);
  --bkc-ticket-snap: cubic-bezier(.2, .9, .1, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  overflow: clip;
  color: var(--bkc-ticket-ink);
  background: var(--bkc-ticket-bg);
  font: 600 15px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ol) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button, input, select, code) { font: inherit; color: inherit; }
}
.bkc-ticket-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bkc-ticket-in {
  max-width: 1160px; margin-inline: auto;
  padding: clamp(36px, 6cqi, 80px) clamp(16px, 4.5cqi, 56px);
  display: grid; gap: clamp(22px, 3.4cqi, 32px);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "board" "act" "disp";
}
@container (width >= 900px) {
  .bkc-ticket-in { grid-template-columns: minmax(0, 1fr) 300px; grid-template-areas: "head disp" "board disp" "act disp"; column-gap: clamp(36px, 5cqi, 64px); }
}

/* ---------- head ---------- */
.bkc-ticket-head { grid-area: head; display: grid; gap: 12px; }
.bkc-ticket-brand {
  display: inline-flex; align-items: center; gap: 8px; justify-self: start; padding: 5px 10px 5px 7px;
  border: var(--bkc-ticket-b); background: var(--bkc-ticket-ink); color: var(--bkc-ticket-bg);
  font: 800 13px/1 var(--bkc-ticket-mono); letter-spacing: .12em; text-transform: uppercase;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
}
.bkc-ticket-title {
  font-size: clamp(46px, 10.5cqi, 112px); font-weight: 900; line-height: .86; letter-spacing: -.055em; text-transform: uppercase;
  text-wrap: balance;
}
@container (width >= 900px) { .bkc-ticket-title { font-size: clamp(72px, 8.4cqi, 104px); } }
.bkc-ticket-lede { max-width: 54ch; font-size: clamp(15px, 1.6cqi, 18px); font-weight: 550; text-wrap: pretty; & b { font-weight: 850; background: var(--bkc-ticket-ink); color: var(--bkc-ticket-bg); padding: 0 4px; box-decoration-break: clone; -webkit-box-decoration-break: clone; } }

/* ---------- the board ---------- */
.bkc-ticket-board {
  grid-area: board; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 0;
  border: var(--bkc-ticket-b); background: var(--bkc-ticket-ink); color: var(--bkc-ticket-bg); box-shadow: var(--bkc-ticket-hard);
}
.bkc-ticket-serving, .bkc-ticket-next { display: grid; align-content: start; gap: 4px; padding: clamp(14px, 2.2cqi, 22px); }
.bkc-ticket-next { border-left: 1px solid color-mix(in oklch, var(--bkc-ticket-bg) 25%, transparent); }
.bkc-ticket-k { font: 700 11px/1.2 var(--bkc-ticket-mono); letter-spacing: .14em; text-transform: uppercase; }
.bkc-ticket-led {
  display: grid; justify-items: start; font: 800 clamp(48px, 9cqi, 84px)/1 var(--bkc-ticket-mono); letter-spacing: -.02em; font-variant-numeric: tabular-nums;
  & > * { grid-area: 1 / 1; }
  & [data-serving] { color: var(--bkc-ticket-led); text-shadow: 0 0 18px color-mix(in oklch, var(--bkc-ticket-led) 55%, transparent); }
}
.bkc-ticket-cd { font: 800 clamp(22px, 3.8cqi, 36px)/1.1 var(--bkc-ticket-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; margin-top: auto; padding-top: 10px; }
@container (width < 440px) { .bkc-ticket-cd { font-size: 19px; } }
.bkc-ticket-sub { font: 600 12px/1.35 var(--bkc-ticket-mono); color: color-mix(in oklch, var(--bkc-ticket-bg) 70%, transparent); }

.bkc-ticket-strip {
  grid-column: 1 / -1; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr);
  border-top: 1px solid color-mix(in oklch, var(--bkc-ticket-bg) 25%, transparent);
  & li { position: relative; display: grid; gap: 2px; padding: 10px 10px 26px; font: 700 11px/1.2 var(--bkc-ticket-mono); text-transform: uppercase; letter-spacing: .06em; }
  & li + li { border-left: 1px solid color-mix(in oklch, var(--bkc-ticket-bg) 25%, transparent); }
  & li b { font-size: 13px; font-weight: 800; }
  & li small { font-size: 10px; font-weight: 500; letter-spacing: 0; color: color-mix(in oklch, var(--bkc-ticket-bg) 60%, transparent); font-variant-numeric: tabular-nums; }
  & li::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: 10px; height: 6px; border: 1px solid color-mix(in oklch, var(--bkc-ticket-bg) 45%, transparent); }
  & li.is-sent::after { background: var(--bkc-ticket-bg); border-color: var(--bkc-ticket-bg); }
  & li.is-next { color: var(--bkc-ticket-bg); }
  & li.is-next::after { background: repeating-linear-gradient(-45deg, var(--bkc-ticket-bg) 0 2px, transparent 2px 5px); }
  & li.is-you { background: var(--bkc-ticket-red); color: var(--bkc-ticket-paper); & small { color: color-mix(in oklch, var(--bkc-ticket-paper) 80%, transparent); } }
}
.bkc-ticket-mark {
  position: absolute; z-index: 1; bottom: 4px; left: calc(10px + (100% - 20px) * var(--f)); translate: -50% 0;
  width: 3px; height: 18px; background: var(--bkc-ticket-paper);
  transition: left .9s var(--bkc-ticket-spring);
  &.is-ghost { background: var(--bkc-ticket-led); opacity: .9; }
}
@container (width < 520px) {
  .bkc-ticket-strip li { padding-inline: 6px; & .bkc-ticket-range { display: none; } &::after { left: 6px; right: 6px; } }
  .bkc-ticket-mark { left: calc(6px + (100% - 12px) * var(--f)); }
}

/* ---------- act: form, then your ticket ---------- */
.bkc-ticket-act { grid-area: act; }
.bkc-ticket-form {
  display: grid; gap: 6px 14px; grid-template-columns: minmax(0, 1fr);
  &[hidden] { display: none; }
}
@container (width >= 560px) {
  .bkc-ticket-form { grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); grid-template-areas: "l1 l2" "i1 i2" "then then" "err err";
    & > :nth-child(1) { grid-area: l1; } & > :nth-child(2) { grid-area: i1; } & > :nth-child(3) { grid-area: l2; } & > :nth-child(4) { grid-area: i2; }
    & .bkc-ticket-then { grid-area: then; } & .bkc-ticket-err { grid-area: err; }
  }
}
.bkc-ticket-lab { margin-top: 6px; font: 700 11px/1.2 var(--bkc-ticket-mono); letter-spacing: .14em; text-transform: uppercase; }
.bkc-ticket-input {
  width: 100%; height: 54px; padding: 0 14px; border: var(--bkc-ticket-b); border-radius: 0; background: var(--bkc-ticket-paper);
  font-size: 17px; font-weight: 650;
  transition: box-shadow .25s var(--bkc-ticket-snap), translate .25s var(--bkc-ticket-snap);
  &::placeholder { color: color-mix(in oklch, var(--bkc-ticket-ink) 38%, transparent); }
  &:focus { outline: none; box-shadow: var(--bkc-ticket-hard); translate: -3px -3px; }
  &[aria-invalid="true"] { border-color: var(--bkc-ticket-red); box-shadow: 6px 6px 0 var(--bkc-ticket-red); }
}
.bkc-ticket-select {
  appearance: none; cursor: pointer; padding-right: 40px;
  background-image: linear-gradient(45deg, transparent 50%, var(--bkc-ticket-ink) 50% calc(50% + 2.5px), transparent 0), linear-gradient(-45deg, transparent 50%, var(--bkc-ticket-ink) 50% calc(50% + 2.5px), transparent 0);
  background-size: 8px 8px; background-repeat: no-repeat; background-position: calc(100% - 24px) 21px, calc(100% - 16px) 21px;
}
.bkc-ticket-then {
  display: flex; align-items: center; gap: 10px; margin-top: 14px; font-size: clamp(20px, 2.6cqi, 26px); font-weight: 900; text-transform: uppercase; letter-spacing: -.02em;
  & svg { width: 30px; height: 30px; fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: square; rotate: 90deg; animation: bkc-ticket-nudge 1.6s var(--bkc-ticket-snap) infinite; }
  .bkc-ticket.is-off & svg { animation-play-state: paused; }
}
@container (width >= 900px) { .bkc-ticket-then svg { rotate: 0deg; } }
@keyframes bkc-ticket-nudge { 0%, 55%, 100% { translate: 0 0; } 25% { translate: 6px 0; } }
.bkc-ticket-err { min-height: 1.4em; font: 700 13px/1.4 var(--bkc-ticket-mono); color: var(--bkc-ticket-red); }

.bkc-ticket-you {
  display: grid; gap: 22px 28px; margin-top: 10px; grid-template-columns: minmax(0, 1fr); justify-items: start;
  &[hidden] { display: none; }
  & > :not(.bkc-ticket-pin) { transition: opacity .5s ease-out, translate .7s var(--bkc-ticket-spring); transition-delay: calc(var(--i, 0) * 90ms + 250ms); @starting-style { opacity: 0; translate: 0 16px; } }
  & > :nth-child(2) { --i: 1; } & > :nth-child(3) { --i: 2; }
}
@container (width >= 600px) {
  .bkc-ticket-you { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "pin stats" "pin skip"; align-items: start;
    & .bkc-ticket-pin { grid-area: pin; } & .bkc-ticket-stats { grid-area: stats; } & .bkc-ticket-skip { grid-area: skip; }
  }
}
.bkc-ticket-pin {
  position: relative; justify-self: center; padding-top: 10px;
  filter: drop-shadow(6px 6px 0 var(--bkc-ticket-ink));
  & .bkc-ticket-tk { rotate: -4deg; cursor: default; }
  &::before { content: ""; position: absolute; z-index: 2; top: 0; left: 50%; width: 74px; height: 22px; translate: -50% 0; rotate: 3deg; background: color-mix(in oklch, var(--bkc-ticket-ink) 88%, transparent); }
}
@container (width >= 600px) { .bkc-ticket-pin { justify-self: start; } }
.bkc-ticket-stats { display: grid; gap: 8px; }
.bkc-ticket-ahead { display: grid; }
.bkc-ticket-big {
  counter-reset: bkc-ticket-a var(--bkc-ticket-ahead);
  font-size: clamp(76px, 13cqi, 132px); font-weight: 900; line-height: .82; letter-spacing: -.06em; font-variant-numeric: tabular-nums;
  transition: --bkc-ticket-ahead 1.6s cubic-bezier(.16, 1, .3, 1);
  &::after { content: counter(bkc-ticket-a); }
}
.bkc-ticket-line {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; padding-top: 8px; border-top: var(--bkc-ticket-b);
  & b { font-size: 20px; font-weight: 900; text-transform: uppercase; font-variant-numeric: tabular-nums; }
  & span { font: 600 13px/1.3 var(--bkc-ticket-mono); }
}
.bkc-ticket-skip { display: grid; gap: 10px; max-width: 520px; }
.bkc-ticket-skip-t { font-size: 15px; font-weight: 550; text-wrap: pretty; & b { font-weight: 900; text-transform: uppercase; } & span { font-weight: 800; } }
.bkc-ticket-copy {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; border: var(--bkc-ticket-b); background: var(--bkc-ticket-paper);
  & code { align-self: center; padding: 0 12px; font: 700 14px var(--bkc-ticket-mono); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; user-select: all; }
}
.bkc-ticket-btn {
  height: 46px; padding: 0 16px; border: 0; border-left: var(--bkc-ticket-b); cursor: pointer;
  background: var(--bkc-ticket-ink); color: var(--bkc-ticket-bg); font: 800 13px var(--bkc-ticket-mono); letter-spacing: .1em; text-transform: uppercase;
  transition: background-color .15s;
  &:hover { background: var(--bkc-ticket-red); }
  &:focus-visible { outline: 3px solid var(--bkc-ticket-red); outline-offset: 2px; }
  &.is-done { background: var(--bkc-ticket-red); }
}
.bkc-ticket-again {
  justify-self: start; padding: 2px 0; border: 0; background: none; cursor: pointer; font: 700 12px var(--bkc-ticket-mono); letter-spacing: .06em; text-transform: uppercase;
  text-decoration: underline 2px; text-underline-offset: 4px;
  &:hover { color: var(--bkc-ticket-red); }
  &:focus-visible { outline: 3px solid var(--bkc-ticket-red); outline-offset: 2px; }
}

/* ---------- dispenser ---------- */
.bkc-ticket-disp { grid-area: disp; display: grid; justify-items: center; align-content: start; align-self: center; gap: 0; }
.bkc-ticket-sign {
  position: relative; z-index: 2; display: grid; gap: 10px; width: 270px; padding: 20px 18px 22px; border: var(--bkc-ticket-b);
  background:
    repeating-linear-gradient(-45deg, transparent 0 10px, color-mix(in oklch, var(--bkc-ticket-ink) 10%, transparent) 10px 12px) 0 100% / 100% 14px no-repeat,
    var(--bkc-ticket-red);
  color: var(--bkc-ticket-paper); box-shadow: var(--bkc-ticket-hard);
  font-size: 46px; font-weight: 900; line-height: .84; letter-spacing: -.055em; text-transform: uppercase; text-align: center;
}
.bkc-ticket-mouth {
  position: relative; width: 270px; padding-top: 30px; display: grid; justify-items: center;
  clip-path: inset(22px -60px -800px -60px);   /* anything above the slot is inside the machine */
  &::before { content: ""; position: absolute; z-index: 2; inset: 0 24px auto; height: 30px; background: var(--bkc-ticket-ink); }
  &::after { content: ""; position: absolute; z-index: 3; top: 20px; left: 40px; right: 40px; height: 6px; background: oklch(8% 0 0); box-shadow: 0 -2px 0 color-mix(in oklch, var(--bkc-ticket-bg) 30%, transparent); }
}
.bkc-ticket-tk {
  position: relative; display: grid; justify-items: center; gap: 6px; width: 200px; padding: 18px 16px 14px; margin: 0;
  border: 0; border-radius: 0; cursor: grab; touch-action: none; user-select: none;
  background: var(--bkc-ticket-stock); color: var(--bkc-ticket-ink);
  mask: radial-gradient(circle 4.5px at 50% 0, #0000 96%, #000) 0 0 / 12px 100% repeat-x, radial-gradient(circle 4.5px at 50% 100%, #0000 96%, #000) 0 0 / 12px 100% repeat-x;
  mask-composite: intersect;
  transition: transform .5s var(--bkc-ticket-spring);
  &:hover:not(:disabled):not(.is-drag) { transform: translateY(5px); }
  &:focus-visible { outline: none; box-shadow: inset 0 0 0 3px var(--bkc-ticket-ink); background: color-mix(in oklch, var(--bkc-ticket-stock) 82%, var(--bkc-ticket-red)); }
  &.is-drag { cursor: grabbing; transition: none; }
  &:disabled { cursor: not-allowed; }
  .bkc-ticket-mouth:has(&:focus-visible)::after { background: var(--bkc-ticket-red); }
}
.bkc-ticket-tk-top { font: 700 10px/1 var(--bkc-ticket-mono); letter-spacing: .16em; text-transform: uppercase; }
.bkc-ticket-tk-no {
  display: flex; align-items: baseline; gap: 4px;
  & small { font: 800 15px var(--bkc-ticket-mono); }
  & b { font-size: 54px; font-weight: 900; line-height: .95; letter-spacing: -.05em; font-variant-numeric: tabular-nums; }
}
.bkc-ticket-tk-bar { width: 100%; height: 28px; background: repeating-linear-gradient(90deg, var(--bkc-ticket-ink) 0 2px, transparent 2px 4px, var(--bkc-ticket-ink) 4px 7px, transparent 7px 8px, var(--bkc-ticket-ink) 8px 9px, transparent 9px 12px); }
.bkc-ticket-tk-foot { padding-top: 6px; border-top: 2px dashed var(--bkc-ticket-ink); width: 100%; text-align: center; font: 700 10px/1 var(--bkc-ticket-mono); letter-spacing: .16em; text-transform: uppercase; }
.bkc-ticket-how {
  display: flex; align-items: center; gap: 6px; margin-top: 14px; font: 700 11px/1.3 var(--bkc-ticket-mono); letter-spacing: .06em; text-transform: uppercase;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.6; }
}

@media (prefers-reduced-motion: reduce) {
  .bkc-ticket-then svg { animation: none; }
  .bkc-ticket-tk { transition: none; &:hover:not(:disabled):not(.is-drag) { transform: none; } }
  .bkc-ticket-input { transition: none; &:focus { translate: 0 0; } }
  .bkc-ticket-big { transition: none; }
  .bkc-ticket-mark { transition: none; }
  .bkc-ticket-you > :not(.bkc-ticket-pin) { transition: opacity .3s linear; transition-delay: 0s; @starting-style { translate: 0 0; } }
}

js:
/* A deli-counter waitlist. Everything on the board is derived from three facts:
   Batch 9 (stalls 1–2,250) went out Friday 25 Sep 2026 at 16:00, 2,730 traders were
   queued at that moment, and the doors open to BATCH stalls every Friday. */
const BATCH = 250, PER_REF = 50, WEEK = 6048e5;
const BASE = new Date(2026, 8, 25, 16, 0, 0), BASE_SENT = 9, BASE_QUEUE = 2730, GROWTH = 320;

const $ = (s) => root.querySelector(s);
const form = $('.bkc-ticket-form');
const email = $('#bkc-ticket-email');
const sell = $('#bkc-ticket-sell');
const err = $('.bkc-ticket-err');
const you = $('.bkc-ticket-you');
const pin = $('[data-pin]');
const tk = $('[data-tk]');
const tkN = $('[data-tk-n]');
const how = $('.bkc-ticket-how span');
const strip = $('[data-strip]');
const big = $('.bkc-ticket-big');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, .011, .044 2.2%, .175 4.7%, .757 13.6%, .953 17.6%, 1.036 21%, 1.072 24.2%, 1.074 27.2%, 1.02 35.7%, .996 41.6%, 1.001 61%, 1)';

const fmt = (n) => n.toLocaleString('en-GB');
const day = (d) => d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });

/* ---------- the state of the queue right now ---------- */
const now0 = Date.now();
const weeks = Math.max(0, Math.floor((now0 - BASE) / WEEK));
const sent = BASE_SENT + weeks;                               /* batches already invited */
const serving = sent * BATCH;                                 /* last number let in */
const lastAt = new Date(+BASE + weeks * WEEK);
const nextAt = new Date(+lastAt + WEEK);
let queue = BASE_QUEUE + weeks * GROWTH;                      /* numbers taken so far */
let mine = 0, behind = 0;

$('[data-serving]').textContent = String(serving);
$('[data-last]').textContent = 'Batch ' + sent + ' went out ' + day(lastAt);
$('[data-next]').textContent = 'Batch ' + (sent + 1) + ' · ' + day(nextAt) + ' 16:00';
const cd = $('[data-cd]');
function countdown() {
  const ms = Math.max(0, nextAt - Date.now());
  const s = Math.floor(ms / 1000), p = (n) => String(n).padStart(2, '0');
  const d = Math.floor(s / 86400);
  cd.textContent = (d ? d + 'd ' : '') + p(Math.floor(s / 3600) % 24) + 'h ' + p(Math.floor(s / 60) % 60) + 'm ' + p(s % 60) + 's';
}

/* ---------- batch strip: the last two invited, the next one and yours ---------- */
const batchOf = (n) => Math.ceil(n / BATCH);
function drawStrip() {
  const target = mine || queue + 1;
  const tb = batchOf(target);
  const from = Math.max(1, sent - 1), to = Math.max(from + 4, tb);
  let html = '';
  for (let b = from; b <= to; b++) {
    const cls = (b <= sent ? 'is-sent' : b === sent + 1 ? 'is-next' : '') + (b === tb && mine ? ' is-you' : '');
    const at = new Date(+lastAt + (b - sent) * WEEK).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    html += '<li class="' + cls + '"><b>B' + b + '</b><small>' + (b <= sent ? 'In ' : '') + at + '</small><small class="bkc-ticket-range">' + fmt((b - 1) * BATCH + 1) + '–' + fmt(b * BATCH) + '</small>';
    if (b === tb) html += '<i class="bkc-ticket-mark' + (mine ? '' : ' is-ghost') + '" style="--f:' + (((target - 1) % BATCH) / (BATCH - 1)).toFixed(3) + '" title="' + (mine ? 'You' : 'Next number') + '"></i>';
    html += '</li>';
  }
  strip.innerHTML = html;
}

function setDispenser(n, animate) {
  tkN.textContent = fmt(n);
  tk.setAttribute('aria-label', mine ? 'Ticket dispenser — you already hold number ' + fmt(mine) : 'Take number ' + fmt(n));
  if (animate && !reduce.matches) tkN.animate([{ transform: 'translateY(-60%)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 380, easing: 'cubic-bezier(.2,.9,.1,1)' });
}

/* ---------- your numbers ---------- */
function renderYou() {
  const ahead = mine - serving - 1;
  const b = batchOf(mine), fridays = b - sent;
  const when = new Date(+lastAt + fridays * WEEK);
  root.style.setProperty('--bkc-ticket-ahead', String(ahead));
  $('[data-ahead-sr]').textContent = fmt(ahead) + ' traders ahead of you';
  $('[data-batch]').textContent = 'Batch ' + b;
  $('[data-when]').textContent = day(when) + ', 16:00 — ' + (fridays === 1 ? 'this coming Friday' : 'in ' + fridays + ' Fridays');
  $('[data-behind]').textContent = fmt(behind);
  const goal = (sent + 1) * BATCH;
  const refs = Math.ceil((mine - goal) / PER_REF);
  $('[data-refs]').textContent = refs > 0 ? refs + ' referral' + (refs > 1 ? 's' : '') + ' gets you into Batch ' + (sent + 1) + ' on ' + day(nextAt) + '.' : 'You’re already in the next batch.';
  $('[data-link]').textContent = 'stallkeep.co/q/' + mine;
}

/* ---------- taking a ticket ---------- */
const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
function jam(msg) {
  err.textContent = msg;
  email.setAttribute('aria-invalid', 'true');
  if (!reduce.matches) tk.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-7px) rotate(-2deg)' }, { transform: 'translateX(6px) rotate(1.5deg)' }, { transform: 'translateX(-3px)' }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.36,.07,.19,.97)' });
  email.focus();
}
email.addEventListener('input', () => { if (email.getAttribute('aria-invalid') && EMAIL.test(email.value.trim())) { email.removeAttribute('aria-invalid'); err.textContent = ''; } });

function take(dragY) {
  const v = email.value.trim();
  if (!v) return jam('Email first — that’s where your invite goes.'), false;
  if (!EMAIL.test(v)) return jam('That email looks incomplete.'), false;
  queue += 1;
  mine = queue;
  behind = 0;

  /* FIRST: where the torn ticket is now (including the drag offset) */
  const first = tk.getBoundingClientRect();
  const copy = tk.cloneNode(true);
  copy.removeAttribute('data-tk');
  copy.removeAttribute('aria-describedby');
  copy.removeAttribute('aria-label');
  copy.setAttribute('role', 'img');
  copy.setAttribute('aria-label', 'Your ticket, number ' + fmt(mine) + ', ' + sell.value);
  copy.disabled = true;
  copy.querySelector('.bkc-ticket-tk-foot').textContent = sell.value;
  copy.style.transform = '';
  copy.classList.remove('is-drag');
  pin.replaceChildren(copy);
  form.hidden = true;
  you.hidden = false;
  renderYou();
  drawStrip();

  /* LAST + INVERT + PLAY: arc from the dispenser to the pin */
  const last = copy.getBoundingClientRect();
  const dx = first.left - last.left, dy = first.top - last.top;
  if (!reduce.matches) {
    copy.animate([
      { transform: `translate(${dx}px, ${dy}px) rotate(4deg)` },
      { transform: `translate(${dx * 0.5}px, ${dy * 0.5 - 70}px) rotate(-16deg)`, offset: 0.45 },
      { transform: 'none' },
    ], { duration: 900, easing: SPRING });
    /* the dispenser feeds the next ticket out of the slot */
    tk.animate([{ transform: 'translateY(-105%)' }, { transform: 'translateY(-105%)', offset: 0.3 }, { transform: 'none' }], { duration: 760, easing: 'cubic-bezier(.2,.9,.1,1)' });
  }
  tk.style.transform = '';
  tk.disabled = true;
  how.textContent = 'One ticket per trader';
  setDispenser(queue + 1, false);
  return true;
}

/* ---------- drag to tear ---------- */
const TEAR = 64;
let startY = 0, dy = 0, dragging = false, moved = false;
tk.addEventListener('pointerdown', (e) => {
  if (tk.disabled || e.button !== 0) return;
  dragging = true; moved = false; startY = e.clientY; dy = 0;
  tk.setPointerCapture(e.pointerId);
  tk.classList.add('is-drag');
});
tk.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const raw = Math.max(0, e.clientY - startY);
  if (raw > 4) moved = true;
  /* resists like paper held at the perforation, then gives */
  dy = raw < TEAR ? raw * 0.75 : TEAR * 0.75 + (raw - TEAR) * 0.25;
  tk.style.transform = `translateY(${dy}px) rotate(${Math.min(raw, 120) * 0.02}deg)`;
});
const release = () => {
  if (!dragging) return;
  dragging = false;
  tk.classList.remove('is-drag');
  if (dy >= TEAR * 0.75) { if (take(dy)) return; }
  const from = tk.style.transform;
  tk.style.transform = '';
  if (from && !reduce.matches) tk.animate([{ transform: from }, { transform: 'none' }], { duration: 520, easing: SPRING });
};
tk.addEventListener('pointerup', release);
tk.addEventListener('pointercancel', release);
tk.addEventListener('click', () => { if (!moved) take(0); moved = false; });

/* ---------- copy & reset ---------- */
const copyBtn = $('[data-copy]');
copyBtn.addEventListener('click', async () => {
  const text = $('[data-link]').textContent;
  let ok = false;
  try { await navigator.clipboard.writeText(text); ok = true; } catch (e) { ok = false; }
  if (!ok) {
    const r = document.createRange();
    r.selectNodeContents($('[data-link]'));
    const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r);
  }
  copyBtn.textContent = ok ? 'Copied' : 'Press ⌘C';
  copyBtn.classList.add('is-done');
  setTimeout(() => { copyBtn.textContent = 'Copy link'; copyBtn.classList.remove('is-done'); }, 1800);
});
$('.bkc-ticket-again').addEventListener('click', () => {
  mine = 0; behind = 0;
  pin.replaceChildren();
  you.hidden = true;
  form.hidden = false;
  tk.disabled = false;
  how.textContent = 'Drag down to tear · or press Enter';
  root.style.setProperty('--bkc-ticket-ahead', '0');
  setDispenser(queue + 1, false);
  drawStrip();
  email.focus();
});

/* ---------- the queue keeps moving: other traders take numbers ---------- */
let visible = false;
const io = new IntersectionObserver(([en]) => { visible = en.isIntersecting; root.classList.toggle('is-off', !visible); });
io.observe(root);
let seed = 7;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const clock = setInterval(() => {
  if (!root.isConnected) { clearInterval(clock); io.disconnect(); return; }
  if (!visible || document.hidden) return;
  countdown();
  if (rnd() < 0.16 && !dragging) {
    queue += 1;
    if (mine) { behind += 1; $('[data-behind]').textContent = fmt(behind); }
    else { setDispenser(queue + 1, true); drawStrip(); }
  }
}, 1000);

countdown();
setDispenser(queue + 1, false);
drawStrip();

css:
@property --bkc-agenda-len { syntax: "<integer>"; inherits: true; initial-value: 30; }

.bkc-agenda {
  /* re-theme: paper, ink, signal */
  --bkc-agenda-bg: oklch(98.4% 0.004 95);
  --bkc-agenda-ink: oklch(21% 0.008 260);
  --bkc-agenda-accent: oklch(66% 0.19 44);

  --bkc-agenda-muted: color-mix(in oklch, var(--bkc-agenda-ink) 58%, var(--bkc-agenda-bg));
  --bkc-agenda-hair: color-mix(in oklch, var(--bkc-agenda-ink) 13%, transparent);
  --bkc-agenda-tint: color-mix(in oklch, var(--bkc-agenda-accent) 9%, var(--bkc-agenda-bg));
  --bkc-agenda-spring: linear(0, .01, .04 2.2%, .16 4.6%, .74 13.4%, .95 17.4%, 1.03 20.6%, 1.06 23.6%, 1.06 26.5%, 1.016 34.6%, .997 40.8%, 1.001 60%, 1);
  --bkc-agenda-out: cubic-bezier(.22, 1, .36, 1);

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  color: var(--bkc-agenda-ink);
  background: var(--bkc-agenda-bg);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ol, fieldset, legend) { margin: 0; padding: 0; border: 0; }
  & :where(ol) { list-style: none; }
  & :where(button, input, select) { font: inherit; color: inherit; }
}
.bkc-agenda-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bkc-agenda-in {
  max-width: 1160px; margin-inline: auto;
  padding: clamp(40px, 6cqi, 72px) clamp(16px, 4.5cqi, 56px);
  display: grid; gap: clamp(28px, 4.5cqi, 52px) clamp(32px, 5cqi, 64px);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "pick" "plan";
}
@container (width >= 940px) {
  .bkc-agenda-in { grid-template-columns: minmax(0, 1.16fr) minmax(0, 1fr); grid-template-areas: "head plan" "pick plan"; grid-template-rows: auto 1fr; row-gap: 24px; align-items: start; }
  .bkc-agenda-plan { position: sticky; top: 16px; }
  .bkc-agenda-title { font-size: clamp(40px, 4.7cqi, 54px); }
  .bkc-agenda-topic { padding-block: 11px; }
}

/* ---------- head ---------- */
.bkc-agenda-head {
  grid-area: head; display: grid; gap: 14px 48px; padding-bottom: clamp(20px, 3cqi, 32px); border-bottom: 2px solid var(--bkc-agenda-ink);
  grid-template-columns: minmax(0, 1fr); grid-template-areas: "brand" "kicker" "title" "lede";
}
@container (width >= 940px) {
  .bkc-agenda-head { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "brand kicker" "title title" "lede lede"; }
}
.bkc-agenda-brand {
  grid-area: brand; display: inline-flex; align-items: center; gap: 8px; font-weight: 700; font-size: 16px; letter-spacing: -.01em;
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkc-agenda-accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.bkc-agenda-kicker { grid-area: kicker; justify-self: start; font-size: 12px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase; color: var(--bkc-agenda-muted); }
@container (width >= 940px) { .bkc-agenda-kicker { justify-self: end; } }
.bkc-agenda-title { grid-area: title; font-size: clamp(36px, 6.6cqi, 60px); font-weight: 650; line-height: .98; letter-spacing: -.045em; text-wrap: balance; }
.bkc-agenda-lede { grid-area: lede; max-width: 46ch; font-size: clamp(15px, 1.5cqi, 17px); color: var(--bkc-agenda-muted); text-wrap: pretty; }

/* ---------- topics ---------- */
.bkc-agenda-pick { grid-area: pick; display: grid; min-width: 0; }
.bkc-agenda-lab { margin-bottom: 10px; font-size: 12px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase; color: var(--bkc-agenda-muted); }
.bkc-agenda-topic {
  position: relative; display: grid; grid-template-columns: 20px 30px minmax(0, 1fr) auto; align-items: start; gap: 4px 12px;
  padding: 13px 4px 13px 2px; border-top: 1px solid var(--bkc-agenda-hair); cursor: pointer;
  transition: background-color .2s;
  &:last-child { border-bottom: 1px solid var(--bkc-agenda-hair); }
  &::before { content: ""; position: absolute; left: -12px; top: -1px; bottom: -1px; width: 3px; background: var(--bkc-agenda-accent); transform: scaleY(0); transform-origin: 50% 0; transition: transform .45s var(--bkc-agenda-out); }
  &:hover { background: color-mix(in oklch, var(--bkc-agenda-ink) 3%, transparent); }
  &:has(input:checked)::before { transform: scaleY(1); }
  &:has(input:focus-visible) { outline: 2px solid var(--bkc-agenda-accent); outline-offset: -2px; }
  & input { width: 18px; height: 18px; margin: 2px 0 0; accent-color: var(--bkc-agenda-accent); cursor: pointer; }
  & input:focus-visible { outline: none; }
}
.bkc-agenda-n { padding-top: 2px; font: 500 13px ui-monospace, Menlo, monospace; color: var(--bkc-agenda-muted); font-variant-numeric: tabular-nums; .bkc-agenda-topic:has(input:checked) & { color: var(--bkc-agenda-accent); } }
.bkc-agenda-t {
  display: grid; gap: 3px; font-size: 17px; font-weight: 550; letter-spacing: -.01em; line-height: 1.25;
  & small { font-size: 13.5px; font-weight: 400; letter-spacing: 0; line-height: 1.45; color: var(--bkc-agenda-muted); text-wrap: pretty; }
}
.bkc-agenda-m { font-size: 17px; font-weight: 500; font-variant-numeric: tabular-nums; color: var(--bkc-agenda-muted); .bkc-agenda-topic:has(input:checked) & { color: var(--bkc-agenda-ink); } }

/* ---------- plan ---------- */
.bkc-agenda-plan {
  grid-area: plan; display: grid; gap: 20px; min-width: 0;
  padding: clamp(20px, 3cqi, 32px); border: 1px solid var(--bkc-agenda-ink);
  background: color-mix(in oklch, var(--bkc-agenda-bg) 40%, white);
}
.bkc-agenda-len { display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "big slots" "big fit"; align-items: end; column-gap: 20px; row-gap: 6px; }
.bkc-agenda-big {
  grid-area: big; display: flex; align-items: baseline; gap: 6px; line-height: .8;
  counter-reset: bkc-agenda-c var(--bkc-agenda-len);
  transition: --bkc-agenda-len .8s var(--bkc-agenda-out);
}
.bkc-agenda-num { font-size: clamp(80px, 12cqi, 128px); font-weight: 250; letter-spacing: -.06em; font-variant-numeric: tabular-nums; &::after { content: counter(bkc-agenda-c); } }
@container (width >= 940px) { .bkc-agenda-num { font-size: clamp(96px, 9cqi, 116px); } }
.bkc-agenda-unit { font-size: 18px; font-weight: 600; color: var(--bkc-agenda-muted); }
.bkc-agenda-slots {
  grid-area: slots; display: flex; gap: 4px; justify-self: start;
  & span { position: relative; padding: 3px 8px; font: 500 12px ui-monospace, Menlo, monospace; color: var(--bkc-agenda-muted); font-variant-numeric: tabular-nums; transition: color .3s; }
  & span::after { content: ""; position: absolute; inset: auto 4px -2px; height: 2px; background: var(--bkc-agenda-accent); transform: scaleX(0); transition: transform .5s var(--bkc-agenda-out); }
  & span.is-on { color: var(--bkc-agenda-ink); font-weight: 700; }
  & span.is-on::after { transform: scaleX(1); }
}
.bkc-agenda-fit { grid-area: fit; font-size: 14px; color: var(--bkc-agenda-muted); text-wrap: pretty; }

/* the timeline: every segment and tick is a full-width layer moved and scaled by transform only */
.bkc-agenda-bar { display: grid; gap: 6px; }
.bkc-agenda-track { position: relative; height: 46px; overflow: clip; background: var(--bkc-agenda-hair); }
.bkc-agenda-seg {
  position: absolute; inset: 0; transform-origin: 0 50%;
  background: var(--bkc-agenda-accent);
  transition: transform .75s var(--bkc-agenda-spring), opacity .3s;
  &[data-k="intro"] { background: var(--bkc-agenda-ink); }
  &[data-k="qa"] { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--bkc-agenda-ink) 30%, transparent) 0 1px, transparent 1px 6px), color-mix(in oklch, var(--bkc-agenda-ink) 8%, var(--bkc-agenda-bg)); }
  &.is-alt { background: color-mix(in oklch, var(--bkc-agenda-accent) 62%, var(--bkc-agenda-bg)); }
  @starting-style { opacity: 0; }
}
.bkc-agenda-cut, .bkc-agenda-tag {
  position: absolute; inset: 0; pointer-events: none;
  transition: transform .75s var(--bkc-agenda-spring), opacity .3s;
}
.bkc-agenda-cut::before { content: ""; position: absolute; left: -1px; top: 0; bottom: 0; width: 2px; background: color-mix(in oklch, var(--bkc-agenda-bg) 40%, white); }
.bkc-agenda-tag {
  display: flex; align-items: center; padding-left: 8px;
  font: 600 11px/1 ui-monospace, Menlo, monospace; color: oklch(99% 0 0); font-variant-numeric: tabular-nums;
  & span { overflow: hidden; white-space: nowrap; max-width: calc(var(--w) * 1% - 12px); }
  &[data-k="qa"] { color: var(--bkc-agenda-ink); }
}
.bkc-agenda-scale { position: relative; height: 18px; overflow-x: clip; }   /* ticks past the slot wait off the end */
.bkc-agenda-tick {
  position: absolute; inset: 0; transition: transform .75s var(--bkc-agenda-spring), opacity .4s;
  &::before { content: ""; position: absolute; left: 0; top: 0; width: 1px; height: 5px; background: var(--bkc-agenda-muted); }
  & span { position: absolute; left: 0; top: 6px; translate: -50% 0; font: 500 10.5px ui-monospace, Menlo, monospace; color: var(--bkc-agenda-muted); font-variant-numeric: tabular-nums; }
  &:first-child span { translate: 0 0; }
  &.is-end span { translate: -100% 0; }
  &.is-off { opacity: 0; }
}

/* agenda rows */
.bkc-agenda-list { position: relative; display: grid; border-top: 1px solid var(--bkc-agenda-ink); }
.bkc-agenda-row {
  display: grid; grid-template-columns: 50px minmax(0, 1fr) auto; gap: 12px; align-items: baseline;
  padding: 8px 0; border-bottom: 1px solid var(--bkc-agenda-hair); background: color-mix(in oklch, var(--bkc-agenda-bg) 40%, white);
  transition: opacity .35s var(--bkc-agenda-out), translate .5s var(--bkc-agenda-out);
  @starting-style { opacity: 0; translate: -10px 0; }
  & time { font: 500 13px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--bkc-agenda-muted); }
  & b { font-weight: 550; }
  & span { font-size: 13px; color: var(--bkc-agenda-muted); font-variant-numeric: tabular-nums; }
  &[data-k="intro"] b, &[data-k="qa"] b { font-weight: 400; color: var(--bkc-agenda-muted); }
  &.is-leaving { position: absolute; left: 0; right: 0; opacity: 0; translate: 10px 0; transition-duration: .25s; }
}

.bkc-agenda-guide {
  display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 12px; align-items: center; font-size: 14px; color: var(--bkc-agenda-muted);
  & svg { width: 40px; height: 40px; & circle { fill: var(--bkc-agenda-tint); stroke: var(--bkc-agenda-accent); } & text { font: 700 13px system-ui, sans-serif; fill: var(--bkc-agenda-accent); letter-spacing: .02em; } }
  & b { color: var(--bkc-agenda-ink); font-weight: 600; }
}

/* form */
.bkc-agenda-form { display: grid; gap: 12px; &[hidden] { display: none; } }
.bkc-agenda-fields { display: grid; gap: 12px; }
@container (width >= 520px) { .bkc-agenda-fields { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); } }
.bkc-agenda-f {
  display: grid; gap: 6px;
  & span { font-size: 12px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--bkc-agenda-muted); }
  & :is(input, select) { width: 100%; height: 48px; padding: 0 12px; border: 0; border-bottom: 2px solid var(--bkc-agenda-ink); border-radius: 0; background: color-mix(in oklch, var(--bkc-agenda-ink) 4%, transparent); font-size: 16px; transition: background-color .2s, border-color .2s; }
  & select { appearance: none; cursor: pointer; background-image: linear-gradient(45deg, transparent 50%, currentColor 50% calc(50% + 1.5px), transparent 0), linear-gradient(-45deg, transparent 50%, currentColor 50% calc(50% + 1.5px), transparent 0); background-size: 6px 6px; background-repeat: no-repeat; background-position: calc(100% - 18px) 21px, calc(100% - 12px) 21px; }
  & :is(input, select):focus { outline: none; border-bottom-color: var(--bkc-agenda-accent); background-color: var(--bkc-agenda-tint); }
  & input[aria-invalid="true"] { border-bottom-color: var(--bkc-agenda-accent); }
  & input::placeholder { color: color-mix(in oklch, var(--bkc-agenda-ink) 35%, transparent); }
}
.bkc-agenda-go {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; height: 56px; padding: 0 18px 0 20px; border: 0; cursor: pointer;
  background: var(--bkc-agenda-ink); color: var(--bkc-agenda-bg); font-size: 16px; font-weight: 600; text-align: left;
  transition: background-color .25s;
  & svg { width: 22px; height: 22px; flex: none; fill: none; stroke: var(--bkc-agenda-accent); stroke-width: 2; transition: transform .5s var(--bkc-agenda-spring); }
  &:hover { background: color-mix(in oklch, var(--bkc-agenda-ink) 88%, var(--bkc-agenda-accent)); & svg { transform: translateX(4px); } }
  &:focus-visible { outline: 2px solid var(--bkc-agenda-accent); outline-offset: 3px; }
  & [data-go] { font-variant-numeric: tabular-nums; }
}
.bkc-agenda-err { min-height: 1.3em; font-size: 13px; font-weight: 600; color: color-mix(in oklch, var(--bkc-agenda-accent) 75%, var(--bkc-agenda-ink)); }
.bkc-agenda-done {
  display: grid; gap: 6px; padding: 18px 0 4px; border-top: 2px solid var(--bkc-agenda-accent);
  transition: opacity .5s var(--bkc-agenda-out), translate .7s var(--bkc-agenda-spring);
  @starting-style { opacity: 0; translate: 0 8px; }
  &[hidden] { display: none; }
  & p { color: var(--bkc-agenda-muted); text-wrap: pretty; & b { color: var(--bkc-agenda-ink); font-weight: 600; } }
}
.bkc-agenda-done-t { font-size: 22px; font-weight: 650; letter-spacing: -.02em; color: var(--bkc-agenda-ink) !important; outline: none; }
.bkc-agenda-edit {
  justify-self: start; margin-top: 4px; padding: 2px 0; border: 0; background: none; cursor: pointer; font-size: 14px; font-weight: 600;
  text-decoration: underline 1.5px var(--bkc-agenda-accent); text-underline-offset: 4px;
  &:focus-visible { outline: 2px solid var(--bkc-agenda-accent); outline-offset: 2px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkc-agenda-seg, .bkc-agenda-cut, .bkc-agenda-tag, .bkc-agenda-tick { transition: opacity .2s linear; }
  .bkc-agenda-big { transition: none; }
  .bkc-agenda-row { transition: opacity .2s linear; @starting-style { translate: 0 0; } }
  .bkc-agenda-row.is-leaving { translate: 0 0; }
  .bkc-agenda-topic::before, .bkc-agenda-slots span::after { transition: none; }
  .bkc-agenda-go:hover svg { transform: none; }
  .bkc-agenda-done { transition: opacity .2s linear; @starting-style { translate: 0 0; } }
}

js:
/* The demo plan is computed, never typed: a 5-minute intro, the ticked topics in
   order, and whatever is left of the shortest slot that still leaves 5 minutes of
   questions. Every bar, tick and row is moved by transform only. */
const INTRO = 5, QA_MIN = 5, SLOTS = [30, 45, 60];
const SPRING = 'linear(0, .01, .04 2.2%, .16 4.6%, .74 13.4%, .95 17.4%, 1.03 20.6%, 1.06 23.6%, 1.06 26.5%, 1.016 34.6%, .997 40.8%, 1.001 60%, 1)';
const $ = (s) => root.querySelector(s);
const boxes = [...root.querySelectorAll('.bkc-agenda-topic input')];
const track = $('[data-track]');
const scale = $('[data-scale]');
const list = $('[data-list]');
const fit = $('[data-fit]');
const lenSr = $('[data-len-sr]');
const goLabel = $('[data-go]');
const form = $('.bkc-agenda-form');
const done = $('.bkc-agenda-done');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

const TOPICS = boxes.map((b, i) => ({
  k: b.value, min: Number(b.dataset.min), n: String(i + 1).padStart(2, '0'),
  name: b.closest('label').querySelector('.bkc-agenda-t').firstChild.textContent.trim(),
}));
const clock = (m) => Math.floor(m / 60) + ':' + String(m % 60).padStart(2, '0');

function compute() {
  const picked = TOPICS.filter((t, i) => boxes[i].checked);
  const used = INTRO + picked.reduce((s, t) => s + t.min, 0);
  const len = SLOTS.find((s) => s >= used + QA_MIN) || SLOTS[SLOTS.length - 1];
  const items = [{ k: 'intro', name: 'Intro — your firm, in your words', min: INTRO, tag: 'Intro' }]
    .concat(picked.map((t) => ({ k: t.k, name: t.name, min: t.min, tag: t.n })))
    .concat([{ k: 'qa', name: 'Your questions', min: len - used, tag: 'Q&A' }]);
  return { picked, len, qa: len - used, items };
}

/* ---------- timeline layers ---------- */
const layers = new Map();   /* key -> element; keys: seg:k, cut:k, tag:k */
function layer(key, cls, k, make) {
  let el = layers.get(key);
  if (!el) {
    el = document.createElement('div');
    el.className = cls;
    el.dataset.k = k;
    if (make) make(el);
    track.append(el);
    layers.set(key, el);
    el.dataset.fresh = '1';
  }
  el.dataset.live = '1';
  return el;
}
function drawTrack(items, len) {
  layers.forEach((el) => { el.dataset.live = ''; });
  let t = 0, alt = false;
  items.forEach((it, i) => {
    const x = (t / len) * 100, w = (it.min / len) * 100;
    const seg = layer('seg:' + it.k, 'bkc-agenda-seg', it.k);
    if (seg.dataset.fresh) seg.style.transform = `translateX(${x}%) scaleX(0)`;
    if (it.k !== 'intro' && it.k !== 'qa') { seg.classList.toggle('is-alt', alt); alt = !alt; }
    const tag = layer('tag:' + it.k, 'bkc-agenda-tag', it.k, (el) => { el.innerHTML = '<span></span>'; });
    tag.firstChild.textContent = it.tag;
    tag.style.setProperty('--w', w.toFixed(3));
    if (tag.dataset.fresh) tag.style.transform = `translateX(${x}%)`;
    if (i < items.length - 1) {
      const cut = layer('cut:' + it.k, 'bkc-agenda-cut', it.k);
      if (cut.dataset.fresh) cut.style.transform = `translateX(${x}%)`;
      cut._x = x + w;
    }
    seg._t = `translateX(${x}%) scaleX(${(w / 100).toFixed(4)})`;
    tag._t = `translateX(${x}%)`;
    t += it.min;
  });
  /* keep z-order: segments under cuts under tags */
  [...layers.values()].filter((el) => el.classList.contains('bkc-agenda-cut')).forEach((el) => track.append(el));
  [...layers.values()].filter((el) => el.classList.contains('bkc-agenda-tag')).forEach((el) => track.append(el));
  void track.offsetWidth;                 /* commit the start state of fresh layers */
  layers.forEach((el, key) => {
    delete el.dataset.fresh;
    if (el.dataset.live) {
      el.style.opacity = '';
      el.style.transform = el.classList.contains('bkc-agenda-cut') ? `translateX(${el._x}%)` : el._t;
      return;
    }
    /* leaving: collapse in place, then go */
    layers.delete(key);
    if (el.classList.contains('bkc-agenda-seg')) el.style.transform = el.style.transform.replace(/scaleX\([^)]*\)/, 'scaleX(0)');
    el.style.opacity = '0';
    setTimeout(() => el.remove(), reduce.matches ? 0 : 450);
  });
}

/* ---------- ruler: 13 ticks that re-space themselves when the slot changes ---------- */
const ticks = [];
for (let m = 0; m <= 60; m += 5) {
  const el = document.createElement('div');
  el.className = 'bkc-agenda-tick';
  el.innerHTML = '<span>' + m + '</span>';
  el._m = m;
  scale.append(el);
  ticks.push(el);
}
function drawScale(len) {
  for (const el of ticks) {
    const m = el._m;
    el.style.transform = `translateX(${Math.min(m / len, 1.2) * 100}%)`;
    el.classList.toggle('is-off', m > len);
    el.classList.toggle('is-end', m === len);
    el.querySelector('span').style.visibility = m % 15 === 0 || m === len ? '' : 'hidden';
  }
}

/* ---------- agenda rows with FLIP ---------- */
const rows = new Map();
function drawList(items) {
  const first = new Map();
  rows.forEach((li, k) => first.set(k, li.getBoundingClientRect()));
  const keep = new Set(items.map((it) => it.k));
  rows.forEach((li, k) => {
    if (keep.has(k)) return;
    li.style.top = li.offsetTop + 'px';
    li.classList.add('is-leaving');
    rows.delete(k);
    setTimeout(() => li.remove(), reduce.matches ? 0 : 260);
  });
  const nextLive = (el) => { while (el && el.classList.contains('is-leaving')) el = el.nextElementSibling; return el; };
  let ref = nextLive(list.firstElementChild), t = 0;
  for (const it of items) {
    let li = rows.get(it.k);
    if (!li) {
      li = document.createElement('li');
      li.className = 'bkc-agenda-row';
      li.dataset.k = it.k;
      li.innerHTML = '<time></time><b></b><span></span>';
      rows.set(it.k, li);
    }
    if (li !== ref) list.insertBefore(li, ref);   /* only new rows are ever inserted */
    else ref = nextLive(ref.nextElementSibling);
    li.children[0].textContent = clock(t);
    li.children[1].textContent = it.name;
    li.children[2].textContent = it.min + ' min';
    t += it.min;
  }
  if (reduce.matches) return;
  rows.forEach((li, k) => {
    const f = first.get(k);
    if (!f) return;
    const dy = f.top - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 0.5) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 560, easing: SPRING });
  });
}

/* ---------- glue ---------- */
let current = null;
function render() {
  const p = compute();
  current = p;
  root.style.setProperty('--bkc-agenda-len', String(p.len));
  root.querySelectorAll('[data-slot]').forEach((s) => s.classList.toggle('is-on', Number(s.dataset.slot) === p.len));
  const n = p.picked.length;
  fit.textContent = n
    ? (n === 1 ? 'One topic' : ['Two', 'Three', 'Four', 'Five', 'Six'][n - 2] + ' topics') + ', ' + p.qa + ' minutes for your questions.'
    : 'No topics yet — a ' + p.len + '-minute conversation about your firm.';
  lenSr.textContent = p.len + '-minute demo: ' + p.items.map((it) => it.k === 'qa' ? it.min + ' minutes of questions' : it.name.split(' —')[0]).join(', ') + '.';
  goLabel.textContent = 'Request this ' + p.len + '-minute demo';
  drawTrack(p.items, p.len);
  drawScale(p.len);
  drawList(p.items);
}
root.addEventListener('change', (e) => {
  if (!e.target.closest('.bkc-agenda-topic')) return;
  render();
  if (!done.hidden) { done.hidden = true; form.hidden = false; }   /* the request no longer matches */
});

/* arrow keys move between topics */
$('.bkc-agenda-pick').addEventListener('keydown', (e) => {
  const i = boxes.indexOf(e.target);
  if (i < 0) return;
  let j = -1;
  if (e.key === 'ArrowDown') j = Math.min(boxes.length - 1, i + 1);
  else if (e.key === 'ArrowUp') j = Math.max(0, i - 1);
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = boxes.length - 1;
  if (j < 0) return;
  e.preventDefault();
  boxes[j].focus();
});

/* ---------- request ---------- */
const email = form.querySelector('input[type="email"]');
const vans = form.querySelector('select');
const err = $('.bkc-agenda-err');
const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
const esc = (s) => s.replace(/[&<>"']/g, (c) => '&#' + c.charCodeAt(0) + ';');
email.addEventListener('input', () => { if (EMAIL.test(email.value.trim())) { email.removeAttribute('aria-invalid'); err.textContent = ''; } });
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const v = email.value.trim();
  if (!EMAIL.test(v)) {
    err.textContent = v ? 'That email looks incomplete.' : 'Add a work email so Dele can send times.';
    email.setAttribute('aria-invalid', 'true');
    email.focus();
    return;
  }
  const p = current;
  const names = p.picked.map((t) => t.name);
  const topics = names.length ? names.slice(0, -1).join(', ') + (names.length > 1 ? ' and ' : '') + names[names.length - 1] : 'a conversation about your firm';
  done.querySelector('[data-done]').innerHTML = 'Dele will email <b>' + esc(v) + '</b> within one working day with three times for a <b>' + p.len + '-minute</b> demo: ' + esc(topics) + ', then ' + p.qa + ' minutes of questions. He&rsquo;ll plan for a fleet of <span style="white-space:nowrap">' + esc(vans.value) + ' vans</span>.';
  form.hidden = true;
  done.hidden = false;
  done.querySelector('.bkc-agenda-done-t').focus({ preventScroll: true });
});
$('.bkc-agenda-edit').addEventListener('click', () => {
  done.hidden = true;
  form.hidden = false;
  boxes[0].focus();
});

render();

css:
.bkc-stage {
  /* re-theme: the dark house, curtain velvet, tungsten light, brass */
  --bkc-stage-bg: oklch(12.5% 0.018 22);
  --bkc-stage-velvet: oklch(35% 0.13 23);
  --bkc-stage-light: oklch(94% 0.055 82);
  --bkc-stage-brass: oklch(77% 0.115 76);

  --bkc-stage-dim: color-mix(in oklch, var(--bkc-stage-light) 40%, var(--bkc-stage-bg));
  --bkc-stage-mid: color-mix(in oklch, var(--bkc-stage-light) 64%, var(--bkc-stage-bg));
  --bkc-stage-deep: color-mix(in oklch, var(--bkc-stage-velvet) 55%, black);
  --bkc-stage-serif: ui-serif, "New York", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --bkc-stage-out: cubic-bezier(.16, 1, .3, 1);
  /* written every frame by the script: pool centre and radius, in px of the copy box */
  --bkc-stage-x: 50%;
  --bkc-stage-y: 34%;
  --bkc-stage-r: 220px;

  container-type: inline-size;
  position: relative; isolation: isolate; overflow: clip;
  box-sizing: border-box; width: 100%;
  display: grid; grid-template-rows: 1fr auto;
  color: var(--bkc-stage-mid);
  background:
    radial-gradient(70% 55% at 50% 108%, color-mix(in oklch, var(--bkc-stage-velvet) 45%, transparent), transparent 70%),
    radial-gradient(60% 40% at 50% -10%, color-mix(in oklch, var(--bkc-stage-light) 6%, transparent), transparent 70%),
    var(--bkc-stage-bg);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, form) { margin: 0; }
  & :where(button, input) { font: inherit; color: inherit; }
  &::after { /* the house lights */
    content: ""; position: absolute; inset: 0; z-index: 0; pointer-events: none; opacity: 0;
    background: radial-gradient(90% 80% at 50% 30%, color-mix(in oklch, var(--bkc-stage-light) 20%, transparent), transparent 75%), color-mix(in oklch, var(--bkc-stage-velvet) 22%, transparent);
    transition: opacity 1.4s var(--bkc-stage-out);
  }
  &.is-lit::after { opacity: 1; }
}
.bkc-stage-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- curtains and valance ---------- */
.bkc-stage-curtains {
  position: absolute; inset: 0; z-index: 1; pointer-events: none;
  &::before {
    content: ""; position: absolute; inset: 0 0 auto; height: 30px; z-index: 1;
    background:
      radial-gradient(circle at 50% 0, var(--bkc-stage-velvet) 0 68%, transparent 70%) 0 6px / 44px 24px repeat-x,
      linear-gradient(var(--bkc-stage-deep), var(--bkc-stage-velvet)) 0 0 / 100% 8px no-repeat;
    filter: drop-shadow(0 6px 8px color-mix(in oklch, black 60%, transparent));
  }
  & i {
    position: absolute; top: 0; bottom: 0; width: clamp(22px, 8cqi, 110px);
    background:
      linear-gradient(color-mix(in oklch, black 45%, transparent), transparent 40%, transparent 70%, color-mix(in oklch, black 55%, transparent)),
      repeating-linear-gradient(90deg, var(--bkc-stage-deep) 0, var(--bkc-stage-velvet) 9px, color-mix(in oklch, var(--bkc-stage-velvet) 70%, var(--bkc-stage-light)) 15px, var(--bkc-stage-velvet) 21px, var(--bkc-stage-deep) 30px);
    box-shadow: 0 0 40px 10px color-mix(in oklch, black 50%, transparent);
  }
  & i:first-child { left: 0; border-bottom-right-radius: 40% 12%; }
  & i:last-child { right: 0; scale: -1 1; border-bottom-right-radius: 40% 12%; }
}

/* ---------- the copy, and its lit twin in the same grid cell ---------- */
.bkc-stage-in {
  grid-area: 1 / 1; position: relative; z-index: 2;
  display: grid; justify-items: center; align-content: start; gap: clamp(14px, 2cqi, 22px);
  max-width: 900px; width: 100%; margin-inline: auto;
  padding: clamp(84px, 12cqi, 140px) clamp(40px, 11cqi, 150px) clamp(40px, 6cqi, 72px);
  text-align: center;
}
.bkc-stage-brand {
  display: inline-flex; align-items: center; gap: 10px; color: var(--bkc-stage-mid);
  font-size: 12px; font-weight: 600; letter-spacing: .3em; text-transform: uppercase;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkc-stage-brass); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
}
.bkc-stage-title {
  font-family: var(--bkc-stage-serif); font-weight: 400; color: var(--bkc-stage-dim);
  font-size: clamp(40px, 8cqi, 92px); line-height: .98; letter-spacing: -.025em;
  text-wrap: balance;
  transition: color 1.2s var(--bkc-stage-out);
}
.bkc-stage-lede { max-width: 52ch; font-size: clamp(15px, 1.6cqi, 18px); text-wrap: pretty; transition: color 1.2s var(--bkc-stage-out); }

.bkc-stage-lit {
  z-index: 3; pointer-events: none;
  mask-image: radial-gradient(circle var(--bkc-stage-r) at var(--bkc-stage-x) var(--bkc-stage-y), #000 0 32%, color-mix(in srgb, #000 55%, transparent) 58%, transparent 100%);
  transition: opacity .6s;
  & .bkc-stage-title { color: var(--bkc-stage-light); text-shadow: 0 0 28px color-mix(in oklch, var(--bkc-stage-light) 45%, transparent), 0 0 2px color-mix(in oklch, var(--bkc-stage-light) 60%, transparent); }
  & .bkc-stage-lede { color: color-mix(in oklch, var(--bkc-stage-light) 92%, var(--bkc-stage-bg)); }
  & .bkc-stage-brand { color: var(--bkc-stage-light); }
  & :is(form, .bkc-stage-fine, .bkc-stage-done) { visibility: hidden; }
  .bkc-stage.is-lit & { opacity: 0; }
}
.bkc-stage.is-lit .bkc-stage-title { color: var(--bkc-stage-light); }
.bkc-stage.is-lit .bkc-stage-lede { color: color-mix(in oklch, var(--bkc-stage-light) 88%, var(--bkc-stage-bg)); }

.bkc-stage-light {
  position: absolute; inset: 0; z-index: 4; width: 100%; height: 100%; pointer-events: none;
  mix-blend-mode: screen;
  transition: opacity 1s var(--bkc-stage-out);
  .bkc-stage.is-lit & { opacity: 0; }
}

/* ---------- form ---------- */
.bkc-stage-form {
  display: grid; gap: 10px; width: min(100%, 520px); margin-top: 8px;
  &[hidden] { display: none; }
}
@container (width >= 560px) {
  .bkc-stage-form { grid-template-columns: minmax(0, 1fr) auto; gap: 0; padding: 5px; border-radius: 999px; background: color-mix(in oklch, var(--bkc-stage-bg) 60%, black); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkc-stage-light) 16%, transparent);
    &:has(.bkc-stage-input:focus) { box-shadow: inset 0 0 0 1px var(--bkc-stage-brass); }
    & .bkc-stage-input { background: transparent; box-shadow: none; }
  }
}
.bkc-stage-input {
  min-width: 0; height: 50px; padding: 0 22px; border: 0; border-radius: 999px;
  background: color-mix(in oklch, var(--bkc-stage-bg) 60%, black); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkc-stage-light) 16%, transparent);
  color: var(--bkc-stage-light); font-size: 16px; text-align: left; caret-color: var(--bkc-stage-brass);
  &::placeholder { color: color-mix(in oklch, var(--bkc-stage-light) 34%, transparent); }
  &:focus { outline: none; }
  &:focus-visible { box-shadow: inset 0 0 0 1px var(--bkc-stage-brass); }
  &[aria-invalid="true"] { box-shadow: inset 0 0 0 1px oklch(62% 0.19 25); }
}
.bkc-stage-go {
  height: 50px; padding: 0 26px; border: 0; border-radius: 999px; cursor: pointer; white-space: nowrap;
  background: linear-gradient(color-mix(in oklch, var(--bkc-stage-brass) 70%, white), var(--bkc-stage-brass));
  color: color-mix(in oklch, var(--bkc-stage-bg) 80%, black); font-weight: 650;
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--bkc-stage-brass) 60%, black), 0 12px 30px -10px color-mix(in oklch, var(--bkc-stage-brass) 70%, transparent);
  transition: transform .4s cubic-bezier(.3, 1.5, .5, 1), filter .3s;
  &:hover { transform: translateY(-1px); filter: brightness(1.08); }
  &:active { transform: scale(.97); transition-duration: .08s; }
  &:focus-visible { outline: 2px solid var(--bkc-stage-light); outline-offset: 3px; }
}
.bkc-stage-fine { font-size: 13px; color: var(--bkc-stage-dim); text-wrap: pretty; .bkc-stage.is-error & { color: oklch(72% 0.15 30); } }
.bkc-stage-done {
  display: grid; justify-items: center; gap: 8px; max-width: 46ch;
  transition: opacity .8s var(--bkc-stage-out) .5s, translate 1s var(--bkc-stage-out) .5s;
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
  & p { color: color-mix(in oklch, var(--bkc-stage-light) 82%, var(--bkc-stage-bg)); text-wrap: pretty; & b { color: var(--bkc-stage-light); font-weight: 600; } }
}
.bkc-stage-done-t { font-family: var(--bkc-stage-serif); font-style: italic; font-size: clamp(24px, 3cqi, 30px); color: var(--bkc-stage-brass) !important; outline: none; }
.bkc-stage-down {
  margin-top: 4px; padding: 4px 2px; border: 0; background: none; cursor: pointer; font-size: 13px; letter-spacing: .14em; text-transform: uppercase; color: var(--bkc-stage-mid);
  &:hover { color: var(--bkc-stage-light); }
  &:focus-visible { outline: 2px solid var(--bkc-stage-brass); outline-offset: 2px; border-radius: 2px; }
}

/* ---------- stage lip ---------- */
.bkc-stage-floor {
  position: relative; z-index: 5; grid-row: 2;
  display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 28px;
  padding: 16px clamp(16px, 10cqi, 140px) 18px;
  border-top: 1px solid color-mix(in oklch, var(--bkc-stage-brass) 35%, transparent);
  background:
    radial-gradient(6px 3px at 12.5% 0, var(--bkc-stage-brass), transparent) 0 0 / 25% 100%,
    linear-gradient(color-mix(in oklch, var(--bkc-stage-velvet) 30%, oklch(20% 0.03 50)), oklch(10% 0.01 40));
  font-size: 11px; font-weight: 600; letter-spacing: .2em; text-transform: uppercase; color: color-mix(in oklch, var(--bkc-stage-brass) 75%, var(--bkc-stage-bg));
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion: reduce) {
  .bkc-stage::after, .bkc-stage-title, .bkc-stage-lede, .bkc-stage-light { transition-duration: .3s; }
  .bkc-stage-go { transition: filter .2s; &:hover, &:active { transform: none; } }
  .bkc-stage-done { transition: opacity .3s linear; @starting-style { translate: 0 0; } }
}

js:
/* A followspot. The lamp hangs above the stage; its pool (x, y, r) rides a damped
   spring toward whatever deserves attention — a slow sweep at rest, the pointer, or
   the control in focus, iris closed down to its size. One canvas draws the cone,
   the pool and the dust; the lit copy is an inert twin masked to the same pool. */
const $ = (s) => root.querySelector(s);
const copy = $('[data-copy]');
const lit = $('[data-lit]');
const canvas = $('.bkc-stage-light');
const ctx = canvas.getContext('2d');
const form = $('.bkc-stage-form');
const input = $('.bkc-stage-input');
const fine = $('[data-fine]');
const done = $('.bkc-stage-done');
const title = $('.bkc-stage-title');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* the lit twin: same markup, same grid cell, so it lays out identically */
lit.innerHTML = copy.innerHTML;
lit.querySelectorAll('[id], [for], [aria-describedby], [aria-live], [role]').forEach((el) => {
  ['id', 'for', 'aria-describedby', 'aria-live', 'role'].forEach((a) => el.removeAttribute(a));
});
lit.inert = true;

/* tungsten, resolved from the theme variable to rgb for the canvas */
function rgbOf(cssColor) {
  const c = document.createElement('canvas');
  c.width = c.height = 1;
  const x = c.getContext('2d');
  x.fillStyle = cssColor;
  x.fillRect(0, 0, 1, 1);
  const d = x.getImageData(0, 0, 1, 1).data;
  return d[0] + ',' + d[1] + ',' + d[2];
}
const probe = document.createElement('i');
probe.style.cssText = 'position:absolute;visibility:hidden;color:var(--bkc-stage-light)';
root.append(probe);
const LIGHT = rgbOf(getComputedStyle(probe).color);
probe.remove();

/* ---------- geometry ---------- */
let W = 0, H = 0, dpr = 1, ox = 0, oy = 0, home = { x: 0, y: 0 }, baseR = 180;
function measure() {
  const rr = root.getBoundingClientRect();
  W = rr.width; H = rr.height;
  dpr = Math.min(2, devicePixelRatio || 1);
  canvas.width = Math.round(W * dpr);
  canvas.height = Math.round(H * dpr);
  const lr = lit.getBoundingClientRect();
  ox = lr.left - rr.left; oy = lr.top - rr.top;
  const tr = title.getBoundingClientRect();
  home = { x: tr.left - rr.left + tr.width / 2, y: tr.top - rr.top + tr.height / 2 };
  baseR = Math.max(110, Math.min(210, W * 0.17));
}
const lamp = () => ({ x: W * 0.5, y: -H * 0.42 });

/* ---------- state: pool on a spring ---------- */
let px = 0, py = 0, pr = 0, vx = 0, vy = 0, vr = 0;
let pointer = null, focusEl = null, hoverEl = null, t0 = performance.now();
function target(now) {
  const el = hoverEl || focusEl;
  if (el) {
    const rr = root.getBoundingClientRect(), b = el.getBoundingClientRect();
    return { x: b.left - rr.left + b.width / 2, y: b.top - rr.top + b.height / 2, r: Math.max(72, Math.min(baseR, b.width * 0.62)) };
  }
  if (reduce.matches) return { x: home.x, y: home.y + 18, r: baseR };   /* calm: the light only moves for focus */
  if (pointer) return { x: pointer.x, y: pointer.y, r: baseR };
  const t = (now - t0) / 1000;
  return {
    x: home.x + Math.min(W * 0.26, 340) * Math.sin(t * 0.32),
    y: home.y + Math.min(H * 0.1, 60) * Math.sin(t * 0.51 + 1.2) + 18,
    r: baseR * (1 + 0.06 * Math.sin(t * 0.7)),
  };
}

/* ---------- dust ---------- */
let seed = 11;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const motes = Array.from({ length: 120 }, () => ({ x: rnd(), y: rnd(), s: 0.4 + rnd() * 1.1, v: 0.004 + rnd() * 0.012, ph: rnd() * 6.28, a: 0.25 + rnd() * 0.6 }));

function cone(L, k) {
  const dx = px - L.x, dy = py - L.y, d = Math.hypot(dx, dy), R = pr * k;
  const back = Math.atan2(-dy, -dx), beta = Math.acos(Math.min(0.999, R / d));
  ctx.beginPath();
  ctx.moveTo(L.x, L.y);
  ctx.arc(px, py, R, back + beta, back - beta + Math.PI * 2, false);
  ctx.closePath();
}
function draw(now) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const L = lamp();
  /* three nested cones give the beam a soft edge without a blur filter */
  const d = Math.hypot(px - L.x, py - L.y) || 1, ux = (px - L.x) / d, uy = (py - L.y) / d;
  for (const [k, a] of [[1.16, 0.026], [1, 0.04], [0.82, 0.055]]) {
    /* the gradient runs past the pool and dies at its far rim, so no cone ends in a hard arc */
    const far = d + pr * k;
    const g = ctx.createLinearGradient(L.x, L.y, L.x + ux * far, L.y + uy * far);
    g.addColorStop(0, 'rgba(' + LIGHT + ',' + a * 1.9 + ')');
    g.addColorStop(Math.max(0, (d - pr * k) / far), 'rgba(' + LIGHT + ',' + a + ')');
    g.addColorStop(d / far, 'rgba(' + LIGHT + ',' + a * 0.55 + ')');
    g.addColorStop(1, 'rgba(' + LIGHT + ',0)');
    cone(L, k);
    ctx.fillStyle = g;
    ctx.fill();
  }
  const pool = ctx.createRadialGradient(px, py, 0, px, py, pr * 1.08);
  pool.addColorStop(0, 'rgba(' + LIGHT + ',.26)');
  pool.addColorStop(0.5, 'rgba(' + LIGHT + ',.13)');
  pool.addColorStop(0.85, 'rgba(' + LIGHT + ',.04)');
  pool.addColorStop(1, 'rgba(' + LIGHT + ',0)');
  ctx.fillStyle = pool;
  ctx.beginPath();
  ctx.arc(px, py, pr * 1.08, 0, Math.PI * 2);
  ctx.fill();
  if (reduce.matches) return;
  /* dust only shows where the beam is */
  ctx.save();
  cone(L, 1.1);
  ctx.clip();
  const t = now / 1000;
  const count = Math.round(motes.length * Math.min(1, W / 1100));   /* density, not count, stays constant */
  for (let i = 0; i < count; i++) {
    const m = motes[i];
    m.y -= m.v * 0.016; m.x += Math.sin(t * 0.4 + m.ph) * 0.0004;
    if (m.y < -0.02) { m.y = 1.02; m.x = rnd(); }
    const x = m.x * W, y = m.y * H;
    const tw = 0.55 + 0.45 * Math.sin(t * 1.7 + m.ph * 3);
    ctx.fillStyle = 'rgba(' + LIGHT + ',' + (m.a * tw * 0.75).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(x, y, m.s, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}
function paintMask() {
  root.style.setProperty('--bkc-stage-x', (px - ox).toFixed(1) + 'px');
  root.style.setProperty('--bkc-stage-y', (py - oy).toFixed(1) + 'px');
  root.style.setProperty('--bkc-stage-r', (pr * 1.15).toFixed(1) + 'px');
}

/* ---------- loop ---------- */
let raf = 0, last = 0, visible = false;
function frame(now) {
  if (!root.isConnected) { cleanup(); return; }
  raf = 0;
  if (!visible || document.hidden || root.classList.contains('is-lit')) return;
  const dt = Math.min(0.05, (now - (last || now)) / 1000);
  last = now;
  const T = target(now), k = 34, c = 2 * Math.sqrt(k) * 0.9;
  vx += (k * (T.x - px) - c * vx) * dt; px += vx * dt;
  vy += (k * (T.y - py) - c * vy) * dt; py += vy * dt;
  vr += (60 * (T.r - pr) - 2 * Math.sqrt(60) * 0.9 * vr) * dt; pr += vr * dt;
  draw(now);
  paintMask();
  raf = requestAnimationFrame(frame);
}
function wake() { if (!raf && visible && !reduce.matches) { last = 0; raf = requestAnimationFrame(frame); } }
function still() {            /* reduced motion: the light jumps, it never travels */
  const T = target(performance.now());
  px = T.x; py = T.y; pr = T.r;
  draw(0); paintMask();
}
const refresh = () => (reduce.matches ? still() : wake());

/* ---------- attention ---------- */
root.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  const rr = root.getBoundingClientRect();
  pointer = { x: e.clientX - rr.left, y: e.clientY - rr.top };
});
root.addEventListener('pointerleave', () => { pointer = null; hoverEl = null; });   /* the spring glides back onto the sweep */
root.addEventListener('pointerover', (e) => { hoverEl = e.target.closest('.bkc-stage-go, .bkc-stage-down'); if (reduce.matches) still(); });
root.addEventListener('focusin', (e) => { focusEl = e.target.closest('input, button'); refresh(); });
root.addEventListener('focusout', (e) => { if (!root.contains(e.relatedTarget)) { focusEl = null; refresh(); } });

const io = new IntersectionObserver(([en]) => { visible = en.isIntersecting; if (visible) refresh(); });
io.observe(root);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { cleanup(); return; }
  measure();
  if (!px) { px = home.x; py = home.y; pr = baseR; }
  if (reduce.matches || !visible) still(); else wake();
});
ro.observe(root);
const onVis = () => { if (!root.isConnected) { cleanup(); return; } if (!document.hidden) refresh(); };
document.addEventListener('visibilitychange', onVis);
function cleanup() { cancelAnimationFrame(raf); io.disconnect(); ro.disconnect(); document.removeEventListener('visibilitychange', onVis); reduce.removeEventListener('change', refresh); }
reduce.addEventListener('change', refresh);

/* ---------- the form ---------- */
const FINE = fine.innerHTML;
const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
const esc = (s) => s.replace(/[&<>"']/g, (c) => '&#' + c.charCodeAt(0) + ';');
input.addEventListener('input', () => {
  if (!root.classList.contains('is-error') || !EMAIL.test(input.value.trim())) return;
  root.classList.remove('is-error'); input.removeAttribute('aria-invalid'); fine.innerHTML = FINE;
});
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const v = input.value.trim();
  if (!EMAIL.test(v)) {
    root.classList.add('is-error');
    input.setAttribute('aria-invalid', 'true');
    fine.textContent = v ? 'That address is missing something — check the @ and the dot.' : 'Add the address your box office uses and the doors are open.';
    input.focus();
    return;
  }
  root.classList.remove('is-error');
  done.querySelector('[data-done]').innerHTML = 'Your box office is open in rehearsal mode &mdash; nothing goes on sale until you say so. The keys are on their way to <b>' + esc(v) + '</b>.';
  form.hidden = true;
  fine.hidden = true;
  done.hidden = false;
  root.classList.add('is-lit');
  done.querySelector('.bkc-stage-done-t').focus({ preventScroll: true });
});
$('.bkc-stage-down').addEventListener('click', () => {
  root.classList.remove('is-lit');
  done.hidden = true;
  form.hidden = false;
  fine.hidden = false;
  fine.innerHTML = FINE;
  input.value = '';
  hoverEl = null;
  input.focus();
  measure();
  refresh();
});

measure();
px = home.x; py = home.y; pr = baseR;
still();

css:
.bkc-flap {
  /* re-theme: housing, flap face, characters, signal */
  --bkc-flap-bg: oklch(21% 0.008 70);
  --bkc-flap-tile: oklch(15% 0.004 70);
  --bkc-flap-ink: oklch(94% 0.012 90);
  --bkc-flap-amber: oklch(80% 0.155 72);

  --bkc-flap-muted: color-mix(in oklch, var(--bkc-flap-ink) 58%, var(--bkc-flap-bg));
  --bkc-flap-line: color-mix(in oklch, var(--bkc-flap-ink) 12%, transparent);
  --bkc-flap-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkc-flap-cw: clamp(15px, 1.56cqi, 19px);          /* one flap's width */
  --bkc-flap-gap: 2px;

  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  color: var(--bkc-flap-ink);
  background:
    linear-gradient(90deg, color-mix(in oklch, var(--bkc-flap-ink) 3%, transparent) 1px, transparent 1px) 0 0 / 24px 24px,
    linear-gradient(color-mix(in oklch, var(--bkc-flap-ink) 3%, transparent) 1px, transparent 1px) 0 0 / 24px 24px,
    var(--bkc-flap-bg);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p) { margin: 0; }
  & :where(button, output) { font: inherit; color: inherit; }
}
.bkc-flap-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bkc-flap-in {
  max-width: 1180px; margin-inline: auto;
  padding: clamp(40px, 6.5cqi, 84px) clamp(16px, 4cqi, 52px);
  display: grid; gap: clamp(22px, 3cqi, 32px);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "copy" "board" "cta";
}

/* ---------- copy ---------- */
.bkc-flap-copy { grid-area: copy; display: grid; gap: 14px; grid-template-areas: "brand" "title" "lede"; }
@container (width >= 900px) {
  .bkc-flap-copy { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); grid-template-areas: "brand brand" "title lede"; column-gap: clamp(32px, 5cqi, 64px); align-items: end; }
}
.bkc-flap-brand {
  grid-area: brand; display: inline-flex; align-items: center; gap: 10px; font: 700 13px/1 var(--bkc-flap-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--bkc-flap-amber);
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
}
.bkc-flap-title { grid-area: title; font-size: clamp(34px, 5.6cqi, 64px); font-weight: 750; line-height: 1; letter-spacing: -.035em; text-wrap: balance; }
.bkc-flap-lede { grid-area: lede; max-width: 50ch; color: var(--bkc-flap-muted); font-size: clamp(15px, 1.5cqi, 17px); text-wrap: pretty; }

/* ---------- the board ---------- */
.bkc-flap-board {
  grid-area: board; justify-self: stretch; min-width: 0;
  display: grid; gap: 16px clamp(24px, 3.6cqi, 44px); grid-template-columns: minmax(0, 1fr);
  padding: clamp(14px, 2cqi, 24px) clamp(14px, 2.2cqi, 28px); border-radius: 12px; overflow-x: auto;
  background:
    radial-gradient(circle 3px at 10px 10px, oklch(45% 0.005 70), transparent 4px),
    radial-gradient(circle 3px at calc(100% - 10px) 10px, oklch(45% 0.005 70), transparent 4px),
    radial-gradient(circle 3px at 10px calc(100% - 10px), oklch(45% 0.005 70), transparent 4px),
    radial-gradient(circle 3px at calc(100% - 10px) calc(100% - 10px), oklch(45% 0.005 70), transparent 4px),
    linear-gradient(oklch(11% 0.003 70), oklch(8% 0.002 70));
  box-shadow: inset 0 0 0 1px oklch(30% 0.005 70), inset 0 2px 0 oklch(36% 0.006 70), 0 30px 60px -30px black;
}
.bkc-flap-table {
  display: grid; align-items: center; row-gap: 6px; column-gap: calc(var(--bkc-flap-cw) * .8);
  grid-template-columns: 10px auto auto; justify-content: start;
}
@container (width >= 640px) { .bkc-flap-table { grid-template-columns: 10px repeat(4, auto); } }
.bkc-flap-cd { display: grid; gap: 10px; padding-bottom: 16px; border-bottom: 1px solid var(--bkc-flap-line); }
@container (width >= 1000px) {
  .bkc-flap-board { grid-template-columns: auto minmax(0, 1fr); align-items: stretch; }
  .bkc-flap-cd { padding: 0 clamp(24px, 3.6cqi, 44px) 0 0; border-bottom: 0; border-right: 1px solid var(--bkc-flap-line); align-content: center; }
  .bkc-flap-table { justify-self: end; }
}
.bkc-flap-k, .bkc-flap-head, .bkc-flap-foot { font: 600 11px/1.2 var(--bkc-flap-mono); letter-spacing: .16em; text-transform: uppercase; color: var(--bkc-flap-amber); }
.bkc-flap-clock { display: flex; flex-wrap: wrap; gap: 6px clamp(10px, 2cqi, 22px); }
.bkc-flap-unit { display: grid; gap: 4px; justify-items: start; & small { font: 600 10px/1 var(--bkc-flap-mono); letter-spacing: .16em; text-transform: uppercase; color: var(--bkc-flap-muted); } }
.bkc-flap-big { --bkc-flap-cw: clamp(28px, 3.2cqi, 38px); --bkc-flap-gap: 3px; }

.bkc-flap-head { display: none; }
@container (width >= 640px) {
  .bkc-flap-head { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding-top: 4px; color: var(--bkc-flap-muted); & span:first-child { grid-column: 2; } }
}
.bkc-flap-rows { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; row-gap: 6px; }
.bkc-flap-row {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; row-gap: 4px; align-items: center;
  margin-inline: -8px; padding: 6px 8px; border-radius: 6px; cursor: pointer;
  transition: background-color .25s;
  & > .bkc-flap-f:nth-of-type(1) { grid-column: 2; }
  & > .bkc-flap-f:nth-of-type(2) { grid-column: 3; justify-self: end; }
  & > .bkc-flap-f:nth-of-type(3) { grid-column: 2; grid-row: 2; }
  & > .bkc-flap-f:nth-of-type(4) { grid-column: 3; grid-row: 2; justify-self: end; }
  &:hover:not([aria-disabled="true"]) { background: color-mix(in oklch, var(--bkc-flap-ink) 5%, transparent); }
  &[aria-checked="true"] { background: color-mix(in oklch, var(--bkc-flap-amber) 10%, transparent); }
  &:focus-visible { outline: 2px solid var(--bkc-flap-amber); outline-offset: 0; }
  &[aria-disabled="true"] { cursor: not-allowed; & .bkc-flap-f { opacity: .5; } }
}
@container (width >= 640px) {
  .bkc-flap-row {
    & > .bkc-flap-f:nth-of-type(n) { grid-row: 1; justify-self: start; }
    & > .bkc-flap-f:nth-of-type(1) { grid-column: 2; } & > .bkc-flap-f:nth-of-type(2) { grid-column: 3; }
    & > .bkc-flap-f:nth-of-type(3) { grid-column: 4; } & > .bkc-flap-f:nth-of-type(4) { grid-column: 5; }
  }
}
.bkc-flap-lamp {
  grid-row: 1 / span 2; width: 8px; height: 8px; border-radius: 50%; align-self: center;
  background: oklch(30% 0.01 70); box-shadow: inset 0 1px 1px black;
  transition: background-color .2s, box-shadow .3s;
  .bkc-flap-row[aria-checked="true"] & { background: var(--bkc-flap-amber); box-shadow: 0 0 10px 1px color-mix(in oklch, var(--bkc-flap-amber) 70%, transparent); }
}
@container (width >= 640px) { .bkc-flap-lamp { grid-row: 1; } }
.bkc-flap-foot { grid-column: 1 / -1; display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: 8px; padding-top: 12px; border-top: 1px solid var(--bkc-flap-line); color: var(--bkc-flap-muted); }

/* ---------- one split-flap cell ---------- */
.bkc-flap-f { display: inline-flex; gap: var(--bkc-flap-gap); }
.bkc-flap-c {
  position: relative; flex: none; width: var(--bkc-flap-cw); height: calc(var(--bkc-flap-cw) * 1.46);
  font: 700 calc(var(--bkc-flap-cw) * 1.02) / calc(var(--bkc-flap-cw) * 1.46) var(--bkc-flap-mono);
  color: var(--bkc-flap-ink); text-align: center; text-transform: uppercase;
  perspective: calc(var(--bkc-flap-cw) * 9);
  .bkc-flap-st & { color: var(--bkc-flap-amber); }
  & > span { position: absolute; left: 0; right: 0; height: 50%; overflow: hidden; background: linear-gradient(oklch(19% 0.004 70), var(--bkc-flap-tile)); backface-visibility: hidden; }
  & > span > b { display: block; height: 200%; font-weight: inherit; }
  & .bkc-flap-t, & .bkc-flap-ft { top: 0; border-radius: 2px 2px 0 0; transform-origin: 50% 100%; }
  & .bkc-flap-b, & .bkc-flap-fb { bottom: 0; border-radius: 0 0 2px 2px; transform-origin: 50% 0; background: linear-gradient(var(--bkc-flap-tile), oklch(17% 0.004 70)); & > b { translate: 0 -50%; } }
  & .bkc-flap-ft, & .bkc-flap-fb { z-index: 2; }
  & .bkc-flap-fb { transform: rotateX(90deg); }
  &::after { content: ""; position: absolute; z-index: 3; left: 0; right: 0; top: calc(50% - .5px); height: 1px; background: oklch(5% 0 0); }
}

/* ---------- call to action ---------- */
.bkc-flap-cta { grid-area: cta; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px 16px; align-items: stretch; }
@container (width >= 820px) {
  .bkc-flap-cta { grid-template-columns: auto minmax(0, 380px) minmax(0, 1fr); align-items: center; & .bkc-flap-fine { grid-column: auto; max-width: 46ch; } }
}
.bkc-flap-qty {
  display: grid; grid-template-columns: 44px 36px 44px; align-items: center; border-radius: 12px;
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkc-flap-ink) 22%, transparent);
}
.bkc-flap-step {
  height: 100%; min-height: 56px; border: 0; background: none; cursor: pointer; display: grid; place-items: center; border-radius: 12px;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--bkc-flap-ink) 7%, transparent); }
  &:disabled { opacity: .35; cursor: default; }
  &:focus-visible { outline: 2px solid var(--bkc-flap-amber); outline-offset: -2px; }
}
.bkc-flap-n { text-align: center; font: 700 20px var(--bkc-flap-mono); font-variant-numeric: tabular-nums; }
.bkc-flap-go {
  display: flex; align-items: center; justify-content: space-between; gap: 14px; min-height: 56px; padding: 0 10px 0 18px; border: 0; border-radius: 12px; cursor: pointer;
  background: var(--bkc-flap-amber); color: oklch(18% 0.02 70); font-weight: 700; font-size: 16px; text-align: left;
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--bkc-flap-amber) 60%, black), 0 14px 30px -14px color-mix(in oklch, var(--bkc-flap-amber) 80%, transparent);
  transition: transform .35s cubic-bezier(.3, 1.5, .5, 1), filter .2s;
  &:hover { filter: brightness(1.06); transform: translateY(-1px); }
  &:active { transform: scale(.98); transition-duration: .08s; }
  &:focus-visible { outline: 2px solid var(--bkc-flap-ink); outline-offset: 3px; }
  &.is-held { background: color-mix(in oklch, var(--bkc-flap-amber) 25%, var(--bkc-flap-bg)); color: var(--bkc-flap-ink); box-shadow: inset 0 0 0 1px var(--bkc-flap-amber); }
}
.bkc-flap-tot { --bkc-flap-cw: 16px; --bkc-flap-gap: 1.5px; }
.bkc-flap-fine { grid-column: 1 / -1; font-size: 13px; color: var(--bkc-flap-muted); text-wrap: pretty; & b { color: var(--bkc-flap-ink); } & button { padding: 0; border: 0; background: none; color: var(--bkc-flap-amber); cursor: pointer; text-decoration: underline; text-underline-offset: 3px; } & button:focus-visible { outline: 2px solid var(--bkc-flap-amber); outline-offset: 2px; } }

@media (prefers-reduced-motion: reduce) {
  .bkc-flap-go { transition: filter .2s; &:hover, &:active { transform: none; } }
  .bkc-flap-row, .bkc-flap-lamp { transition: none; }
}

