/* A split-flap board. Every character is four leaves: the static top and bottom
   halves, a top leaf that falls away and a bottom leaf that lands. A cell only
   moves forward through its drum, one character per flip, like the real thing. */
const DRUM = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789€/-.:';
const FLIP = 84;                                    /* ms per character */
const $ = (s) => root.querySelector(s);
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

const FARES = [
  { name: 'Student', price: 140, of: 120, left: 38, status: 'BOARDING' },
  { name: 'Early bird', price: 390, of: 400, left: 112, status: 'ON TIME' },
  { name: 'Patron', price: 890, of: 40, left: 9, status: 'LAST CALL' },
  { name: 'Standard', price: 560, of: 0, left: 0, status: 'WAITING', closed: true },
];
const CAP = FARES.reduce((s, f) => s + f.of, 0);    /* 560 seats on sale */

/* ---------- cells ---------- */
const LEAVES = '<span class="bkc-flap-t"><b> </b></span><span class="bkc-flap-b"><b> </b></span><span class="bkc-flap-ft"><b> </b></span><span class="bkc-flap-fb"><b> </b></span>';
function build(field) {
  field.setAttribute('aria-hidden', 'true');
  field.cells = [];
  const drum = field.dataset.drum || DRUM;
  for (let i = 0; i < Number(field.dataset.len); i++) {
    const el = document.createElement('span');
    el.className = 'bkc-flap-c';
    el.innerHTML = LEAVES;
    field.append(el);
    const [t, b, ft, fb] = [...el.children];
    field.cells.push({ t: t.firstChild, b: b.firstChild, ft, fb, ftb: ft.firstChild, fbb: fb.firstChild, cur: ' ', target: ' ', busy: false, drum });
  }
}
root.querySelectorAll('.bkc-flap-f').forEach((f) => build(f));

let visible = false;
function paint(c, ch) { c.t.textContent = c.b.textContent = c.ftb.textContent = c.fbb.textContent = ch; c.cur = ch; }
function flip(c, next) {
  c.t.textContent = next;      /* revealed behind the falling leaf */
  c.ftb.textContent = c.cur;
  c.fbb.textContent = next;
  c.b.textContent = c.cur;
  const fall = c.ft.animate([{ transform: 'rotateX(0deg)', filter: 'brightness(1)' }, { transform: 'rotateX(-90deg)', filter: 'brightness(.55)' }],
    { duration: FLIP * 0.5, easing: 'cubic-bezier(.55,0,.9,.55)', fill: 'forwards' });
  return fall.finished.then(() => {
    const land = c.fb.animate([
      { transform: 'rotateX(90deg)', filter: 'brightness(.6)' },
      { transform: 'rotateX(-10deg)', filter: 'brightness(1)', offset: 0.78 },
      { transform: 'rotateX(0deg)', filter: 'brightness(1)' },
    ], { duration: FLIP * 0.75, easing: 'cubic-bezier(.25,.6,.4,1)', fill: 'forwards' });
    return land.finished.then(() => {
      c.b.textContent = next; c.ftb.textContent = next;
      fall.cancel(); land.cancel();
      c.cur = next;
    });
  }).catch(() => {});
}
async function run(c) {
  c.busy = true;
  while (c.cur !== c.target) {
    if (!root.isConnected) return;
    const d = c.drum, i = d.indexOf(c.cur), j = d.indexOf(c.target);
    if (reduce.matches || !visible || i < 0 || j < 0) { paint(c, c.target); break; }
    const dist = (j - i + d.length) % d.length;
    if (dist > 9) paint(c, d[(j - 7 + d.length) % d.length]);   /* a long way round: spin fast, show the last few */
    else await flip(c, d[(i + 1) % d.length]);
  }
  c.busy = false;
}
function setField(field, text, stagger) {
  const len = field.cells.length;
  const s = String(text).toUpperCase();
  const v = field.dataset.align === 'right' ? s.padStart(len).slice(-len) : s.padEnd(len).slice(0, len);
  field.cells.forEach((c, k) => {
    if (c.target === v[k] && (c.busy || c.cur === v[k])) return;
    c.target = v[k];
    if (c.busy) return;
    if (stagger && !reduce.matches && visible) setTimeout(() => { if (!c.busy) run(c); }, k * 38 + stagger);
    else run(c);
  });
}
const F = (scope, name) => scope.querySelector('[data-f="' + name + '"]');

/* ---------- fares ---------- */
const rows = [...root.querySelectorAll('.bkc-flap-row')];
let pick = 1, qty = 2, held = 0, heldUntil = 0;
const sold = () => FARES.reduce((s, f) => s + (f.of - f.left), 0);
function drawRow(i, stagger) {
  const f = FARES[i], row = rows[i];
  setField(F(row, 'name'), f.name, stagger);
  setField(F(row, 'price'), '€' + f.price, stagger);
  setField(F(row, 'status'), f.status, stagger);
  setField(F(row, 'left'), f.closed ? '-' : String(f.left), stagger);
  row.setAttribute('aria-label', f.name + ', ' + f.price + ' euros, ' + f.status.toLowerCase() + (f.closed ? '' : ', ' + f.left + ' left'));
  row.setAttribute('aria-disabled', f.closed || !f.left ? 'true' : 'false');
}
function select(i, focus) {
  if (FARES[i].closed || held) return;
  pick = i;
  rows.forEach((r, k) => { r.setAttribute('aria-checked', String(k === i)); r.tabIndex = k === i ? 0 : -1; });
  if (focus) rows[i].focus();
  qty = Math.max(1, Math.min(qty, FARES[i].left, 9));
  drawCta();
}
const steps = [...root.querySelectorAll('.bkc-flap-step')];
const go = $('[data-go]'), goT = $('[data-go-t]'), out = $('[data-n]'), fine = $('[data-fine]');
const FINE = fine.innerHTML;
function drawCta() {
  const f = FARES[pick], total = f.price * qty;
  out.textContent = String(qty);
  steps[0].disabled = qty <= 1 || !!held;
  steps[1].disabled = qty >= Math.min(9, f.left) || !!held;
  setField(F(go, 'total'), '€' + total);
  if (!held) {
    goT.textContent = 'Book ' + qty + ' × ' + f.name;
    go.setAttribute('aria-label', 'Book ' + qty + ' ' + f.name + ' seat' + (qty > 1 ? 's' : '') + ', ' + total + ' euros in total');
  }
}
steps.forEach((b) => b.addEventListener('click', () => { qty += Number(b.dataset.d); drawCta(); }));
rows.forEach((r, i) => r.addEventListener('click', () => select(i, true)));
root.querySelector('.bkc-flap-rows').addEventListener('keydown', (e) => {
  const dir = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
  let j = -1;
  if (dir) { j = pick; do { j = (j + dir + rows.length) % rows.length; } while (FARES[j].closed && j !== pick); }
  else if (e.key === 'Home') j = FARES.findIndex((f) => !f.closed);
  else if (e.key === 'End') j = FARES.length - 1 - [...FARES].reverse().findIndex((f) => !f.closed);
  else if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); select(pick, true); return; }
  if (j < 0) return;
  e.preventDefault();
  select(j, true);
});

/* ---------- hold seats ---------- */
go.addEventListener('click', () => {
  if (held) return;
  const f = FARES[pick];
  held = qty;
  f.left -= qty;
  heldUntil = Date.now() + 15 * 60e3;
  drawRow(pick);
  setField(F(root, 'sold'), sold() + '/' + CAP);
  go.classList.add('is-held');
  go.disabled = true;
  steps.forEach((b) => { b.disabled = true; });
  tickHold();
  fine.innerHTML = '<b>' + qty + ' × ' + f.name + '</b> held for 15 minutes while you check out. <button type="button" data-release>Release seats</button>';
  fine.querySelector('[data-release]').focus();
});
root.addEventListener('click', (e) => {
  if (!e.target.closest('[data-release]')) return;
  FARES[pick].left += held;
  held = 0;
  drawRow(pick);
  setField(F(root, 'sold'), sold() + '/' + CAP);
  go.classList.remove('is-held');
  go.disabled = false;
  fine.innerHTML = FINE;
  drawCta();
  go.focus();
});
function tickHold() {
  if (!held) return;
  const s = Math.max(0, Math.round((heldUntil - Date.now()) / 1000));
  goT.textContent = 'Held ' + Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
  if (!s) root.querySelector('[data-release]')?.click();
}

/* ---------- countdown: a fixed deadline, or a rolling demo one once it has passed ---------- */
let deadline = Date.parse(root.dataset.deadline);
if (!(deadline > Date.now())) deadline = Date.now() + (((12 * 24 + 4) * 60 + 31) * 60 + 8) * 1000;
const cd = { dd: F(root, 'dd'), hh: F(root, 'hh'), mm: F(root, 'mm'), ss: F(root, 'ss') };
const cdSr = $('[data-cd-sr]');
let lastMin = -1;
function tickClock() {
  const s = Math.max(0, Math.floor((deadline - Date.now()) / 1000));
  const p = (n) => String(n).padStart(2, '0');
  const d = Math.floor(s / 86400), h = Math.floor(s / 3600) % 24, m = Math.floor(s / 60) % 60;
  setField(cd.dd, p(Math.min(99, d))); setField(cd.hh, p(h)); setField(cd.mm, p(m)); setField(cd.ss, p(s % 60));
  if (m !== lastMin) { lastMin = m; cdSr.textContent = d + ' days, ' + h + ' hours and ' + m + ' minutes left at the early-bird fare'; }
  if (!s && !FARES[1].closed) {          /* departed: the early fare closes, standard opens */
    Object.assign(FARES[1], { status: 'DEPARTED', closed: true });
    Object.assign(FARES[3], { status: 'BOARDING', closed: false, of: 300, left: 300 });
    drawRow(1); drawRow(3);
    if (pick === 1 && !held) select(3);
  }
}

/* ---------- start when seen: the seconds begin to fall, the totals clatter in ---------- */
let booted = false;
function boot() {
  booted = true;
  rows.forEach((r, i) => drawRow(i));
  setField(F(root, 'sold'), sold() + '/' + CAP, 200);
  select(pick);
  tickClock();
}
const io = new IntersectionObserver(([en]) => {
  visible = en.isIntersecting;
  if (visible && !booted) boot();
});
io.observe(root);
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); return; }
  if (!booted || document.hidden) return;
  tickClock();
  tickHold();
}, 1000);

/* the fare rows are painted settled at mount, so a still frame is a finished board */
rows.forEach((r, i) => {
  const f = FARES[i];
  [['name', f.name], ['price', '€' + f.price], ['status', f.status], ['left', f.closed ? '-' : String(f.left)]].forEach(([k, v]) => {
    const fl = F(r, k), len = fl.cells.length, s = (k === 'left' ? v.padStart(len) : v.padEnd(len)).toUpperCase();
    fl.cells.forEach((c, n) => paint(c, s[n]));
  });
});

css:
.bkc-invite {
  /* re-theme: sky, ink, raspberry, window light */
  --bkc-invite-sky: oklch(95.5% 0.03 62);
  --bkc-invite-ink: oklch(28% 0.05 32);
  --bkc-invite-pop: oklch(60% 0.2 12);
  --bkc-invite-glow: oklch(88% 0.15 88);

  --bkc-invite-card: color-mix(in oklch, var(--bkc-invite-sky) 35%, white);
  --bkc-invite-muted: color-mix(in oklch, var(--bkc-invite-ink) 64%, var(--bkc-invite-sky));
  --bkc-invite-line: color-mix(in oklch, var(--bkc-invite-ink) 16%, transparent);
  --bkc-invite-hatch: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--bkc-invite-ink) 30%, transparent) 0 1.5px, transparent 1.5px 6px);
  --bkc-invite-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  --bkc-invite-spring: linear(0, .008, .032 2.1%, .13 4.5%, .7 13.5%, .925 17.6%, 1.019 20.7%, 1.076 23.9%, 1.093 26.6%, 1.084 29.4%, 1.022 37.6%, .995 43%, .993 49.2%, 1.001 66%, 1);
  --bkc-invite-out: cubic-bezier(.2, .9, .3, 1);

  container-type: inline-size;
  isolation: isolate;
  box-sizing: border-box;
  width: 100%;
  color: var(--bkc-invite-ink);
  background:
    radial-gradient(circle at calc(100% - clamp(48px, 9cqi, 140px)) clamp(52px, 8cqi, 110px), color-mix(in oklch, var(--bkc-invite-glow) 70%, white) 0 clamp(26px, 4cqi, 46px), color-mix(in oklch, var(--bkc-invite-glow) 30%, transparent) calc(clamp(26px, 4cqi, 46px) + 1px), transparent clamp(80px, 14cqi, 180px)),
    linear-gradient(color-mix(in oklch, var(--bkc-invite-pop) 9%, var(--bkc-invite-sky)), var(--bkc-invite-sky) 60%);
  font: 500 15px/1.5 var(--bkc-invite-round);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button, input, code) { font: inherit; color: inherit; }
}

.bkc-invite-in {
  max-width: 1160px; margin-inline: auto;
  padding: clamp(40px, 6.5cqi, 84px) clamp(16px, 4.5cqi, 56px) 0;
  display: grid; gap: clamp(26px, 4cqi, 40px) clamp(32px, 5cqi, 64px);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "copy" "card" "street";
}
@container (width >= 900px) {
  .bkc-invite-in { grid-template-columns: minmax(0, 1fr) minmax(360px, 440px); grid-template-areas: "copy card" "street street"; align-items: start; }
}

/* ---------- copy & meter ---------- */
.bkc-invite-copy { grid-area: copy; display: grid; gap: 14px; }
.bkc-invite-brand {
  display: inline-flex; align-items: center; gap: 8px; font-size: 17px; font-weight: 800; letter-spacing: -.01em;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--bkc-invite-pop); fill: none; stroke: white; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.bkc-invite-title { font-size: clamp(38px, 6.6cqi, 70px); font-weight: 850; line-height: .98; letter-spacing: -.04em; text-wrap: balance; }
.bkc-invite-lede { max-width: 48ch; font-size: clamp(15px, 1.6cqi, 18px); color: var(--bkc-invite-muted); text-wrap: pretty; }
.bkc-invite-meter { display: grid; gap: 12px; margin-top: 4px; }
.bkc-invite-earned {
  display: flex; align-items: center; gap: 12px;
  & b { font-size: clamp(48px, 6cqi, 64px); font-weight: 900; line-height: .9; letter-spacing: -.05em; font-variant-numeric: tabular-nums; color: var(--bkc-invite-pop); }
  & span { display: grid; font-size: 16px; font-weight: 750; line-height: 1.2; }
  & small { font-size: 13px; font-weight: 600; color: var(--bkc-invite-muted); font-variant-numeric: tabular-nums; }
}
.bkc-invite-legend {
  display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 13px; font-weight: 650; color: var(--bkc-invite-muted); font-variant-numeric: tabular-nums;
  & span { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
  & i { width: 12px; height: 12px; border-radius: 3px; border: 1.5px solid var(--bkc-invite-ink); }
  & b { color: var(--bkc-invite-ink); }
  & [data-k="lit"] i { background: var(--bkc-invite-glow); box-shadow: 0 0 8px var(--bkc-invite-glow); }
  & [data-k="invited"] i { background: color-mix(in oklch, var(--bkc-invite-pop) 35%, white); }
  & [data-k="draft"] i { background: var(--bkc-invite-hatch); border-style: dashed; }
  & [data-k="empty"] i { border-style: dashed; border-color: var(--bkc-invite-muted); }
}

/* ---------- card ---------- */
.bkc-invite-card {
  grid-area: card; display: grid; gap: 10px; padding: clamp(18px, 2.6cqi, 26px);
  border-radius: 22px; background: var(--bkc-invite-card);
  box-shadow: 0 0 0 2px var(--bkc-invite-ink), 5px 6px 0 2px var(--bkc-invite-ink);
}
@container (width >= 900px) { .bkc-invite-card { margin-top: 8px; } }
.bkc-invite-lab { font-size: 12.5px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.bkc-invite-lab:not(:first-child) { margin-top: 8px; }
.bkc-invite-link {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 6px; padding: 5px 5px 5px 14px;
  border-radius: 14px; background: color-mix(in oklch, var(--bkc-invite-ink) 6%, transparent);
  & code { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 600 14px ui-monospace, Menlo, monospace; user-select: all; }
}
.bkc-invite-copybtn {
  display: inline-flex; align-items: center; gap: 6px; height: 38px; padding: 0 14px; border: 0; border-radius: 10px; cursor: pointer;
  background: var(--bkc-invite-ink); color: var(--bkc-invite-sky); font-size: 14px; font-weight: 750;
  transition: background-color .2s, transform .4s var(--bkc-invite-spring);
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linejoin: round; }
  &:active { transform: scale(.95); transition-duration: .06s; }
  &:focus-visible { outline: 2.5px solid var(--bkc-invite-pop); outline-offset: 2px; }
  &.is-done { background: oklch(55% 0.13 150); }
}
.bkc-invite-field {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 52px; padding: 7px; cursor: text;
  border-radius: 14px; background: white; box-shadow: inset 0 0 0 2px var(--bkc-invite-line);
  transition: box-shadow .2s;
  &:focus-within { box-shadow: inset 0 0 0 2px var(--bkc-invite-pop); }
}
.bkc-invite-chips { display: contents; }
.bkc-invite-chip {
  display: inline-flex; align-items: center; gap: 6px; max-width: 100%; height: 34px; padding: 0 8px 0 12px; border: 0; border-radius: 999px; cursor: pointer;
  background: color-mix(in oklch, var(--bkc-invite-pop) 13%, white); font-size: 14px; font-weight: 650;
  transition: background-color .2s, scale .45s var(--bkc-invite-spring), opacity .25s;
  @starting-style { scale: .6; opacity: 0; }
  & span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & svg { flex: none; width: 16px; height: 16px; padding: 3px; border-radius: 50%; background: color-mix(in oklch, var(--bkc-invite-ink) 12%, transparent); fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; }
  &:hover svg, &:focus-visible svg { background: var(--bkc-invite-pop); stroke: white; }
  &:focus-visible { outline: 2.5px solid var(--bkc-invite-pop); outline-offset: 1px; }
  &.is-bad { background: white; box-shadow: inset 0 0 0 1.5px var(--bkc-invite-pop); color: color-mix(in oklch, var(--bkc-invite-pop) 75%, var(--bkc-invite-ink)); }
}
.bkc-invite-input {
  flex: 1 1 160px; min-width: 120px; height: 36px; padding: 0 6px; border: 0; background: transparent; font-size: 16px; font-weight: 550;
  &:focus { outline: none; }
  &::placeholder { color: color-mix(in oklch, var(--bkc-invite-ink) 38%, transparent); font-weight: 500; }
}
.bkc-invite-help { min-height: 1.5em; font-size: 13px; color: var(--bkc-invite-muted); text-wrap: pretty; &.is-warn { color: color-mix(in oklch, var(--bkc-invite-pop) 80%, var(--bkc-invite-ink)); font-weight: 650; } }
.bkc-invite-send {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px; height: 52px; margin-top: 2px; border: 0; border-radius: 14px; cursor: pointer;
  background: var(--bkc-invite-pop); color: white; font-size: 16px; font-weight: 800;
  box-shadow: 0 4px 0 color-mix(in oklch, var(--bkc-invite-pop) 55%, var(--bkc-invite-ink));
  transition: transform .45s var(--bkc-invite-spring), box-shadow .2s, background-color .25s, opacity .25s;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linejoin: round; transition: transform .5s var(--bkc-invite-spring); }
  &:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 6px 0 color-mix(in oklch, var(--bkc-invite-pop) 55%, var(--bkc-invite-ink)); & svg { transform: translate(3px, -3px); } }
  &:active:not(:disabled) { transform: translateY(3px); box-shadow: 0 1px 0 color-mix(in oklch, var(--bkc-invite-pop) 55%, var(--bkc-invite-ink)); transition-duration: .06s; }
  &:disabled { cursor: default; background: color-mix(in oklch, var(--bkc-invite-ink) 22%, var(--bkc-invite-card)); box-shadow: none; color: color-mix(in oklch, var(--bkc-invite-ink) 55%, transparent); }
  &:focus-visible { outline: 2.5px solid var(--bkc-invite-ink); outline-offset: 3px; }
}

/* ---------- the street ---------- */
.bkc-invite-street { grid-area: street; margin-inline: calc(-1 * clamp(16px, 4.5cqi, 56px)); padding-inline: clamp(16px, 4.5cqi, 56px); }
.bkc-invite-plots {
  display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 14px clamp(4px, 1cqi, 12px); align-items: end;
}
@container (width >= 760px) { .bkc-invite-plots { grid-template-columns: repeat(12, minmax(0, 1fr)); } }
.bkc-invite-plot {
  position: relative; display: grid; justify-items: center; align-content: end; gap: 6px; min-height: calc(var(--bkc-invite-u) * 1.7 + 24px);
  --bkc-invite-u: clamp(44px, 7.4cqi, 76px);   /* house scale */
  border-bottom: 3px solid color-mix(in oklch, var(--bkc-invite-ink) 22%, transparent);
  padding-bottom: 6px;
}
@container (width >= 760px) { .bkc-invite-plot { --bkc-invite-u: clamp(48px, 6.1cqi, 74px); } }
.bkc-invite-house {
  position: relative; display: grid; width: calc(var(--bkc-invite-u) * .9); height: calc(var(--bkc-invite-u) * var(--h, 1.3));
  grid-template-rows: 42% 1fr;
  transition: opacity .35s, display .35s allow-discrete, translate .5s var(--bkc-invite-spring);
  @starting-style { opacity: 0; translate: 0 10px; }
  .bkc-invite-plot[data-state="empty"] & { display: none; opacity: 0; }
}
.bkc-invite-roof {
  position: relative; margin-inline: -8%; background: color-mix(in oklch, var(--c) 60%, var(--bkc-invite-ink));
  clip-path: polygon(0 100%, 50% 0, 100% 100%);
  transform-origin: 50% 100%;
  transition: background-color .5s, translate .6s var(--bkc-invite-spring), opacity .3s;
  .bkc-invite-plot[data-v="1"] & { clip-path: polygon(0 100%, 26% 8%, 100% 100%); }
  .bkc-invite-plot[data-v="2"] & { clip-path: polygon(6% 100%, 6% 45%, 50% 0, 94% 45%, 94% 100%); }
  .bkc-invite-plot[data-state="draft"] & { background: var(--bkc-invite-hatch); @starting-style { translate: 0 -14px; opacity: 0; } }
}
.bkc-invite-walls {
  position: relative; display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1.3fr; gap: 12% 16%; padding: 14% 16% 0;
  border: 2px solid var(--bkc-invite-ink); border-bottom: 0; border-radius: 3px 3px 0 0;
  background: var(--c);
  transform-origin: 50% 100%;
  transition: background-color .5s var(--bkc-invite-out), border-color .3s, scale .7s var(--bkc-invite-spring);
  .bkc-invite-plot[data-state="draft"] & { background: var(--bkc-invite-hatch); border-style: dashed; border-color: color-mix(in oklch, var(--bkc-invite-ink) 55%, transparent); @starting-style { scale: 1 0; } }
}
.bkc-invite-win {
  border-radius: 2px; background: color-mix(in oklch, var(--bkc-invite-ink) 70%, var(--c));
  transition: background-color .6s, box-shadow .6s;
  .bkc-invite-plot[data-state="lit"] & { background: var(--bkc-invite-glow); box-shadow: 0 0 10px 1px color-mix(in oklch, var(--bkc-invite-glow) 80%, transparent); }
  .bkc-invite-plot[data-state="invited"] & { background: color-mix(in oklch, var(--bkc-invite-glow) 35%, white); }
  .bkc-invite-plot[data-state="draft"] & { opacity: 0; }
}
.bkc-invite-door {
  grid-column: 1 / -1; justify-self: center; align-self: end; width: 34%; height: 78%; border-radius: 40% 40% 0 0 / 30% 30% 0 0;
  background: color-mix(in oklch, var(--c) 45%, var(--bkc-invite-ink));
  .bkc-invite-plot[data-state="draft"] & { opacity: 0; }
}
.bkc-invite-mail {
  position: absolute; z-index: 2; left: 50%; bottom: 3%; width: 38%; aspect-ratio: 3 / 2; translate: -50% 0; opacity: 0;
  border-radius: 2px; background: white; box-shadow: 0 0 0 1.5px var(--bkc-invite-ink);
  &::after { content: ""; position: absolute; inset: 0; background: linear-gradient(to bottom right, transparent 48%, var(--bkc-invite-ink) 49% 52%, transparent 53%) 0 0 / 50% 60% no-repeat, linear-gradient(to bottom left, transparent 48%, var(--bkc-invite-ink) 49% 52%, transparent 53%) 100% 0 / 50% 60% no-repeat; }
  .bkc-invite-plot[data-state="invited"] & { opacity: 1; }
  .bkc-invite-plot.is-posting & { animation: bkc-invite-post .9s var(--bkc-invite-out) calc(var(--k, 0) * 120ms) both; }
}
@keyframes bkc-invite-post {
  0% { opacity: 0; transform: translateY(-260%) rotate(-24deg) scale(1.3); }
  45% { opacity: 1; }
  70% { transform: translateY(8%) rotate(4deg) scale(1); }
  100% { opacity: 1; transform: none; }
}
.bkc-invite-plot[data-state="lit"]::before {
  content: ""; position: absolute; left: 50%; bottom: 20px; width: 160%; aspect-ratio: 1; translate: -50% 0; z-index: -1; pointer-events: none;
  background: radial-gradient(closest-side, color-mix(in oklch, var(--bkc-invite-glow) 55%, transparent), transparent);
}
.bkc-invite-plot[data-state="empty"] {   /* an open plot holds a young tree until a house goes up */
  &::before, &::after { content: ""; position: absolute; left: 50%; translate: -50% 0; pointer-events: none; transition: opacity .3s; @starting-style { opacity: 0; } }
  &::before { bottom: 9px; width: 3px; height: calc(var(--bkc-invite-u) * .28); border-radius: 2px; background: color-mix(in oklch, var(--bkc-invite-ink) 55%, var(--bkc-invite-sky)); }
  &::after {
    bottom: calc(9px + var(--bkc-invite-u) * .2); width: calc(var(--bkc-invite-u) * var(--t, .42)); aspect-ratio: 1; border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, color-mix(in oklch, oklch(72% 0.12 145) 70%, white), oklch(62% 0.12 150));
    box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--bkc-invite-ink) 35%, transparent);
  }
  &:nth-child(odd)::after { --t: .34; }
  &:nth-child(3n)::after { --t: .5; }
}
.bkc-invite-name {
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: 11px; font-weight: 750; color: var(--bkc-invite-muted);
  .bkc-invite-plot[data-state="lit"] & { color: var(--bkc-invite-ink); }
}
@container (width < 560px) { .bkc-invite-name { display: none; } }
.bkc-invite-road {
  height: clamp(30px, 4cqi, 44px); margin-inline: calc(-1 * clamp(16px, 4.5cqi, 56px));
  background:
    linear-gradient(90deg, color-mix(in oklch, var(--bkc-invite-sky) 80%, white) 0 50%, transparent 0) 0 50% / 44px 3px repeat-x,
    color-mix(in oklch, var(--bkc-invite-ink) 82%, var(--bkc-invite-sky));
}

@media (prefers-reduced-motion: reduce) {
  .bkc-invite-chip { transition: background-color .2s; @starting-style { scale: 1; opacity: 1; } }
  .bkc-invite-house { transition: opacity .2s, display .2s allow-discrete; @starting-style { translate: 0 0; } }
  .bkc-invite-roof, .bkc-invite-walls { transition: background-color .3s; }
  .bkc-invite-plot[data-state="draft"] .bkc-invite-roof { @starting-style { translate: 0 0; opacity: 1; } }
  .bkc-invite-plot[data-state="draft"] .bkc-invite-walls { @starting-style { scale: 1 1; } }
  .bkc-invite-plot.is-posting .bkc-invite-mail { animation: none; }
  .bkc-invite-send, .bkc-invite-copybtn { transition: background-color .2s; }
  .bkc-invite-send:hover:not(:disabled), .bkc-invite-send:active:not(:disabled), .bkc-invite-copybtn:active { transform: none; }
  .bkc-invite-send:hover:not(:disabled) svg { transform: none; }
}

js:
/* Twelve plots, one per free month a year. Friends who joined light a house;
   invites you have sent stand with a letter at the door; every address you type
   raises scaffolding on the next empty plot. lit + invited + building + empty = 12. */
const CAP = 12, PRICE = 3.99;
const JOINED = [['Tomás', '12 Aug'], ['Aiko', '3 Sep'], ['Bea', '21 Sep']];
const COLORS = ['oklch(78% 0.09 25)', 'oklch(80% 0.08 150)', 'oklch(82% 0.09 80)', 'oklch(76% 0.07 250)', 'oklch(80% 0.09 350)', 'oklch(84% 0.08 110)',
  'oklch(77% 0.08 200)', 'oklch(81% 0.1 55)', 'oklch(79% 0.07 300)', 'oklch(83% 0.07 170)', 'oklch(78% 0.1 5)', 'oklch(82% 0.06 230)'];
const HEIGHT = [1.3, 1.55, 1.2, 1.45, 1.35, 1.25, 1.6, 1.3, 1.42, 1.18, 1.5, 1.34];
const ROOF = [0, 2, 1, 0, 1, 2, 0, 2, 0, 1, 2, 0];

const $ = (s) => root.querySelector(s);
const plotsEl = $('[data-plots]');
const chipsEl = $('[data-chips]');
const input = $('.bkc-invite-input');
const field = $('[data-field]');
const help = $('[data-help]');
const send = $('[data-send]');
const sendT = $('[data-send-t]');
const legend = $('[data-legend]');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const HELP = help.textContent;
const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;

/* ---------- the street ---------- */
const plots = [];
for (let i = 0; i < CAP; i++) {
  const li = document.createElement('li');
  li.className = 'bkc-invite-plot';
  li.dataset.v = String(ROOF[i]);
  li.style.cssText = '--c:' + COLORS[i] + ';--h:' + HEIGHT[i];
  li.innerHTML = '<div class="bkc-invite-house" aria-hidden="true"><i class="bkc-invite-roof"></i><i class="bkc-invite-walls"><i class="bkc-invite-win"></i><i class="bkc-invite-win"></i><i class="bkc-invite-door"></i></i><i class="bkc-invite-mail"></i></div><span class="bkc-invite-name"></span>';
  plotsEl.append(li);
  plots.push({ el: li, state: 'empty', label: '', note: '' });
}
JOINED.forEach(([name, when], i) => Object.assign(plots[i], { state: 'lit', label: name, note: 'joined ' + when }));
Object.assign(plots[JOINED.length], { state: 'invited', label: 'ruth.adeyemi@postbox.example', note: 'invited 29 Sep' });

const STATE_TEXT = { lit: 'lit', invited: 'invited', draft: 'being built', empty: 'empty plot' };
function drawPlot(p, i) {
  p.el.dataset.state = p.state;
  const name = p.el.querySelector('.bkc-invite-name');
  name.textContent = p.state === 'empty' ? '' : p.state === 'lit' ? p.label : p.label.split('@')[0];
  p.el.title = p.state === 'empty' ? 'Empty plot' : p.label + ' — ' + (p.note || STATE_TEXT[p.state]);
  p.el.setAttribute('aria-label', p.state === 'empty' ? 'Plot ' + (i + 1) + ', empty' : p.label + ', ' + (p.note || STATE_TEXT[p.state]));
}
function count(state) { return plots.filter((p) => p.state === state).length; }
function draw() {
  plots.forEach(drawPlot);
  const lit = count('lit'), inv = count('invited'), dr = count('draft'), em = count('empty');
  $('[data-earned]').textContent = String(lit);
  $('[data-worth]').textContent = 'worth £' + (lit * PRICE).toFixed(2);
  legend.innerHTML =
    '<span data-k="lit"><i></i><b>' + lit + '</b> lit</span>' +
    '<span data-k="invited"><i></i><b>' + inv + '</b> invited</span>' +
    (dr ? '<span data-k="draft"><i></i><b>' + dr + '</b> being built</span>' : '') +
    '<span data-k="empty"><i></i><b>' + em + '</b> open plot' + (em === 1 ? '' : 's') + '</span>';
  const ready = drafts.filter((d) => d.ok).length;
  send.disabled = !ready;
  sendT.textContent = ready ? 'Send ' + ready + ' invite' + (ready > 1 ? 's' : '') : 'Send invites';
}

/* ---------- chips ---------- */
const drafts = [];   /* { email, ok, plot, li } */
function warn(msg) { help.textContent = msg; help.classList.add('is-warn'); }
function calm(msg) { help.textContent = msg || HELP; help.classList.remove('is-warn'); }
function addTokens(text) {
  const parts = text.split(/[\s,;]+/).map((t) => t.trim().replace(/^<|>$/g, '').toLowerCase()).filter(Boolean);
  let added = 0;
  for (const email of parts) {
    if (drafts.some((d) => d.email === email) || plots.some((p) => p.label === email)) { warn(email + ' is already on your street.'); continue; }
    const ok = EMAIL.test(email);
    let plot = null;
    if (ok) {
      plot = plots.find((p) => p.state === 'empty');
      if (!plot) { warn('That’s the whole street — twelve free months is the most you can earn in a year.'); break; }
      Object.assign(plot, { state: 'draft', label: email, note: '' });
    }
    const li = document.createElement('li');
    li.innerHTML = '<button type="button" class="bkc-invite-chip' + (ok ? '' : ' is-bad') + '"><span></span><svg viewBox="0 0 12 12" aria-hidden="true"><path d="M3 3l6 6M9 3l-6 6"/></svg></button>';
    li.querySelector('span').textContent = email;
    li.firstChild.setAttribute('aria-label', (ok ? '' : 'Not a valid address: ') + email + '. Press Delete to remove.');
    chipsEl.append(li);
    drafts.push({ email, ok, plot, li });
    added++;
  }
  if (added) {
    const bad = drafts.filter((d) => !d.ok).length;
    if (bad) warn('Fix or remove the address' + (bad > 1 ? 'es' : '') + ' in red — ' + (bad > 1 ? 'they' : 'it') + ' won’t be sent.');
    else if (!help.classList.contains('is-warn')) calm();
  }
  draw();
}
function removeDraft(d, focusDir) {
  const i = drafts.indexOf(d);
  if (i < 0) return;
  drafts.splice(i, 1);
  if (d.plot) Object.assign(d.plot, { state: 'empty', label: '', note: '' });
  d.li.remove();
  if (!drafts.some((x) => !x.ok)) calm();
  draw();
  if (focusDir === 'prev' && drafts[i - 1]) drafts[i - 1].li.firstChild.focus();
  else if (focusDir && drafts[i]) drafts[i].li.firstChild.focus();
  else input.focus();
}
const commit = () => { if (input.value.trim()) { addTokens(input.value); input.value = ''; } };

input.addEventListener('keydown', (e) => {
  if ((e.key === 'Enter' || e.key === ',' || e.key === ';' || e.key === ' ') && input.value.trim()) { e.preventDefault(); commit(); return; }
  if (e.key === 'Enter' && !input.value.trim() && !send.disabled) { e.preventDefault(); send.click(); return; }
  if ((e.key === 'Backspace' || e.key === 'ArrowLeft') && input.selectionStart === 0 && input.selectionEnd === 0 && drafts.length) {
    e.preventDefault();
    drafts[drafts.length - 1].li.firstChild.focus();
  }
});
input.addEventListener('paste', (e) => {
  const text = (e.clipboardData || {}).getData ? e.clipboardData.getData('text') : '';
  if (!/[\s,;]/.test(text.trim())) return;          /* a single address pastes normally */
  e.preventDefault();
  addTokens(input.value + ' ' + text);
  input.value = '';
});
input.addEventListener('blur', commit);
input.addEventListener('input', () => { if (help.classList.contains('is-warn') && !drafts.some((d) => !d.ok)) calm(); });
field.addEventListener('click', (e) => { if (e.target === field || e.target === chipsEl) input.focus(); });

chipsEl.addEventListener('click', (e) => {
  const btn = e.target.closest('.bkc-invite-chip');
  if (btn) removeDraft(drafts.find((d) => d.li.firstChild === btn), 'next');
});
chipsEl.addEventListener('keydown', (e) => {
  const btn = e.target.closest('.bkc-invite-chip');
  if (!btn) return;
  const i = drafts.findIndex((d) => d.li.firstChild === btn);
  const go = (j) => { e.preventDefault(); if (j >= drafts.length) input.focus(); else drafts[Math.max(0, j)].li.firstChild.focus(); };
  if (e.key === 'ArrowLeft') go(i - 1);
  else if (e.key === 'ArrowRight') go(i + 1);
  else if (e.key === 'Home') go(0);
  else if (e.key === 'End' || e.key === 'Escape') go(drafts.length);
  else if (e.key === 'Backspace') { e.preventDefault(); removeDraft(drafts[i], 'prev'); }
  else if (e.key === 'Delete') { e.preventDefault(); removeDraft(drafts[i], 'next'); }
});

/* ---------- send: a letter drops through every new door ---------- */
let postT = 0;
send.addEventListener('click', () => {
  const ready = drafts.filter((d) => d.ok);
  if (!ready.length) return;
  ready.forEach((d, k) => {
    Object.assign(d.plot, { state: 'invited', note: 'invited today' });
    d.plot.el.style.setProperty('--k', String(k));
    d.plot.el.classList.add('is-posting');
    d.li.remove();
  });
  drafts.splice(0, drafts.length, ...drafts.filter((d) => !d.ok));
  draw();
  clearTimeout(postT);
  postT = setTimeout(() => plots.forEach((p) => p.el.classList.remove('is-posting')), reduce.matches ? 0 : 1000 + ready.length * 120);
  const sentMsg = ready.length + ' invite' + (ready.length > 1 ? 's' : '') + ' sent. You’ll get a month each time one of them starts a household.';
  const left = drafts.length;
  if (left) warn(sentMsg + ' The address' + (left > 1 ? 'es' : '') + ' in red ' + (left > 1 ? 'are' : 'is') + ' still waiting for a fix.');
  else calm(sentMsg);
  input.focus();
});

/* ---------- copy link ---------- */
const copyBtn = $('[data-copy]');
let copyT = 0;
copyBtn.addEventListener('click', async () => {
  const code = $('[data-link]');
  let ok = false;
  try { await navigator.clipboard.writeText(code.textContent); ok = true; } catch (err) { ok = false; }
  if (!ok) { const r = document.createRange(); r.selectNodeContents(code); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); }
  copyBtn.lastChild.textContent = ok ? 'Copied' : 'Selected';
  copyBtn.classList.add('is-done');
  clearTimeout(copyT);
  copyT = setTimeout(() => { copyBtn.lastChild.textContent = 'Copy'; copyBtn.classList.remove('is-done'); }, 1800);
});

draw();
